const (
	gcNativeFrameLayoutAMD64 uint8 = iota
	gcNativeFrameLayoutARM64
	gcNativeFrameLayoutRISCV64
	gcNativeFrameLayoutMask      = 0x7f
	gcNativeFrameSyncGlobalRoots = 0x80
)

type gcNativeFrameRoots struct {
	owner                *Instance
	physicalStack        *coreruntime.Engine
	entryReturnSlot      uintptr
	base                 uintptr
	offsets              []uint32
	frameBytes           uint32
	frameLayout          uint8
	allowExternalReturn  bool
	domainHostRoots      bool // bounded products also retain older same-domain host activations
	codeBase             uintptr
	codeBytes            uintptr
	adapterReturnOffsets []uint32
	callsites            []compiledGCFrameCallsite
	suspended            *gcPublicState
}

type gcHostActivation struct {
	base            uintptr
	ctrl            uintptr
	stack           *coreruntime.Engine
	entryReturnSlot uintptr
	callsite        uint32
	noFrame         bool
	savedControl    gcHostSavedControl
}

// Include the outer callback as well as every permitted nested host reentry.
// Preserve the existing capacity for builds with a lower reentry limit.
const gcHostActivationLimit = max(8, maxHostReentryDepth+1)

// Skip foreign parked-chain discovery when AMD64/ARM64 have no parked GC host call.
var gcNativeHostActivations atomic.Int64

func (r *gcNativeFrameRoots) RangeRoots(fn func(gc.RootSlot) bool) {
	r.walk(fn, nil)
}

func (r *gcNativeFrameRoots) RangeRootRefs(sink gc.RootRefSink) bool {
	return r.walk(nil, sink)
}

func (r *gcNativeFrameRoots) syncGlobalsBeforeCollection() {
	if r == nil || r.frameLayout&gcNativeFrameSyncGlobalRoots == 0 || r.owner == nil || r.suspended == nil {
		return
	}
	if err := r.owner.syncGenericGCGlobalRootsLocked(r.suspended); err != nil {
		panic(gcHelperFailure(err))
	}
	// Native execution remains parked for the complete allocation attempt. One
	// synchronization therefore covers a minor collection, root rewrites, and a
	// possible full-collection retry. The next helper republishes this flag.
	r.frameLayout &^= gcNativeFrameSyncGlobalRoots
}

// RangeClassifiedRootRefs preserves exact runtime ownership for opt-in
// root traversal without allocating composite RootSet values on helper
// paths.
func (r *gcNativeFrameRoots) RangeClassifiedRootRefs(sink gc.ClassifiedRootRefSink) bool {
	if r == nil || sink == nil {
		return true
	}
	r.syncGlobalsBeforeCollection()
	if !r.rangeChain(nil, classifiedRootSink{sink: sink, class: gc.RootNativeFrame}, r.physicalStack) {
		return false
	}
	if !r.rangeSuspendedRoots(r.owner, r.suspended, nil, classifiedRootSink{sink: sink, class: gc.RootNativeFrame}) {
		return false
	}
	if r.domainHostRoots && (compiledArchitecture == 4 || gcNativeHostActivations.Load() != 0) && r.owner != nil && r.owner.refStore != nil && !r.owner.refStore.rangeGCDomainSuspendedRoots(r.owner.gc, r.suspended, r, nil, classifiedRootSink{sink: sink, class: gc.RootNativeFrame}) {
		return false
	}
	if r.owner != nil && r.owner.refStore != nil && r.owner.refStore.ownsGCCollector(r.owner.gc) {
		return r.owner.refStore.rangeGCDomainPersistentRootsClassified(r.owner.gc, sink)
	}
	if r.owner != nil && managedFunctionOwnerRootsStrong(r.owner, r.owner.gc) {
		return r.owner.rangeLocalGCTableRoots(nil, classifiedRootSink{sink: sink, class: gc.RootTable})
	}
	return true
}

func (r *gcNativeFrameRoots) rangeSuspendedRoots(owner *Instance, state *gcPublicState, fn func(gc.RootSlot) bool, sink gc.RootRefSink) bool {
	if state != nil && state.hostRootPlan != nil {
		for i := int(state.hostActivationCount) - 1; i >= 0; i-- {
			activation := &state.hostActivations[i]
			if activation.noFrame {
				continue
			}
			if int(activation.callsite) >= len(state.hostRootPlan.callsites) {
				panic(gcHelperFailuref("generic GC host activation callsite %d is unavailable", activation.callsite))
			}
			callsite := &state.hostRootPlan.callsites[activation.callsite]
			chain := gcNativeFrameRoots{
				owner:                r.owner,
				entryReturnSlot:      activation.entryReturnSlot,
				base:                 activation.base,
				offsets:              callsite.offsets,
				frameBytes:           callsite.frameBytes,
				frameLayout:          r.frameLayout,
				allowExternalReturn:  r.allowExternalReturn,
				codeBase:             state.hostCodeBase,
				codeBytes:            state.hostCodeBytes,
				adapterReturnOffsets: state.hostRootPlan.adapterReturnOffsets,
				callsites:            state.hostRootPlan.callsites,
			}
			if !chain.rangeChainFrom(owner, fn, sink, activation.stack) {
				return false
			}
		}
	}
	return true
}

type classifiedRootSink struct {
	sink  gc.ClassifiedRootRefSink
	class gc.RootClass
}

func (s classifiedRootSink) VisitRootRef(r gc.Ref) bool {
	return s.sink.VisitClassifiedRootRef(s.class, r)
}

func (r *gcNativeFrameRoots) rangeTransientRoots(fn func(gc.RootSlot) bool, sink gc.RootRefSink) bool {
	r.syncGlobalsBeforeCollection()
	if !r.rangeChain(fn, sink, r.physicalStack) {
		return false
	}
	if !r.rangeSuspendedRoots(r.owner, r.suspended, fn, sink) {
		return false
	}
	if r.domainHostRoots && (compiledArchitecture == 4 || gcNativeHostActivations.Load() != 0) && r.owner != nil && r.owner.refStore != nil && !r.owner.refStore.rangeGCDomainSuspendedRoots(r.owner.gc, r.suspended, r, fn, sink) {
		return false
	}

	return true
}

func (r *gcNativeFrameRoots) walk(fn func(gc.RootSlot) bool, sink gc.RootRefSink) bool {
	if !r.rangeTransientRoots(fn, sink) {
		return false
	}

	domainRoots := false
	if r.owner != nil && r.owner.refStore != nil && r.owner.refStore.ownsGCCollector(r.owner.gc) {
		domainRoots = true
		if !r.owner.refStore.rangeGCDomainPersistentRoots(r.owner.gc, fn, sink) {
			return false
		}
	}
	if !domainRoots && r.owner != nil && managedFunctionOwnerRootsStrong(r.owner, r.owner.gc) {
		return r.owner.rangeLocalGCTableRoots(fn, sink)
	}
	return true
}

type gcNativeTableRoots struct {
	desc  uintptr
	bytes uintptr
}

func (r *gcNativeTableRoots) RangeRoots(fn func(gc.RootSlot) bool) {
	r.walk(fn, nil)
}

func (r *gcNativeTableRoots) RangeRootRefs(sink gc.RootRefSink) bool {
	return r.walk(nil, sink)
}

func (r *gcNativeTableRoots) walk(fn func(gc.RootSlot) bool, sink gc.RootRefSink) bool {
	if r == nil || r.desc == 0 || r.bytes < 8 {
		return true
	}
	header := unsafe.Slice((*byte)(offHeapPtr(r.desc)), 8)
	length := uint64(binary.LittleEndian.Uint32(header))
	if length > uint64((r.bytes-8)/8) {
		panic(gcHelperFailuref("generic GC table length %d exceeds descriptor capacity", length))
	}
	for i := uint64(0); i < length; i++ {
		addr := r.desc + 8 + uintptr(i*8)
		word := binary.LittleEndian.Uint64(unsafe.Slice((*byte)(offHeapPtr(addr)), 8))
		if word != uint64(gc.Ref(uint32(word))) {
			panic(gcHelperFailuref("generic GC table root %d contains non-compact reference %#x", i, word))
		}
		slot := (*gc.Root)(offHeapPtr(addr))
		if sink != nil {
			if !sink.VisitRootRef(slot.GetRef()) {
				return false
			}
		} else if !fn(slot) {
			return false
		}
	}
	return true
}

func (in *Instance) rangeLocalGCTableRoots(fn func(gc.RootSlot) bool, sink gc.RootRefSink) bool {
	if in == nil || in.c == nil {
		return true
	}
	mirrored := in.existingGCRefTestTableState()
	if !rangeLocalCompactExternRoots(in, fn, sink) {
		return false
	}
	// The exact abstract ref.test, ref.cast, and extern-conversion products
	// register compact collector slots separately. Their physical descriptors can also
	// contain bounded foreign conversion identities, which are not collector
	// references and therefore must never be scanned as raw roots. Other products
	// retain their established descriptor walk as an additional transient root
	// source during helper publication.
	if !rv64GCRefTestAbstract(in.c) && !rv64GCExtern(in.c) && !rv64GCRefCastAbstract(in.c) && !rv64GCBrOnCastAbstract(in.c) && !rv64GCBrOnCastFailAbstract(in.c) {
		for tableIndex := 0; tableIndex < in.c.tableCount(); tableIndex++ {
			if !isGCRefValType(in.c.tableElementType(tableIndex)) {
				continue
			}
			// Staged mirrors retain checked collector roots and filter foreign identities.
			if compiledArchitecture != 4 && mirrored != nil && tableIndex < len(mirrored.kinds) && mirrored.kinds[tableIndex] == gcRefTableRoot {
				continue
			}
			desc := in.tableDescriptor(tableIndex)
			if len(desc) < 8 {
				panic(gcHelperFailuref("generic GC table %d descriptor is unavailable", tableIndex))
			}
			roots := gcNativeTableRoots{desc: uintptr(unsafe.Pointer(&desc[0])), bytes: uintptr(len(desc))}
			if !roots.walk(fn, sink) {
				return false
			}
		}
	}
	passiveBase := in.jm.PassiveElemPtr()
	for i := range in.c.passiveElems {
		elem := &in.c.passiveElems[i]
		if elem.Mode != ElemModePassive || !isGCRefValType(normalizedElemRefType(elem.RefType)) {
			continue
		}
		if passiveBase == 0 {
			panic(gcHelperFailuref("generic GC passive element descriptor %d is unavailable", i))
		}
		descAddr := passiveBase + uintptr(i*coreruntime.PassiveElemDescBytes)
		desc := unsafe.Slice((*byte)(offHeapPtr(descAddr)), coreruntime.PassiveElemDescBytes)
		entries := uintptr(binary.LittleEndian.Uint64(desc))
		length := uint64(binary.LittleEndian.Uint32(desc[8:]))
		if length > uint64(len(elem.Values)) {
			panic(gcHelperFailuref("generic GC passive element %d length %d exceeds %d", i, length, len(elem.Values)))
		}
		if length != 0 && entries == 0 {
			panic(gcHelperFailuref("generic GC passive element %d entries are unavailable", i))
		}
		for j := uint64(0); j < length; j++ {
			slot := (*gc.Root)(offHeapPtr(entries + uintptr(j*8)))
			if sink != nil {
				if !sink.VisitRootRef(slot.GetRef()) {
					return false
				}
			} else if !fn(slot) {
				return false
			}
		}
	}
	return true
}

func gcNativeFrameFitsStack(base uintptr, frameBytes uint32, stack *coreruntime.Engine) bool {
	if stack == nil {
		return true
	}
	top := stack.StackTop()
	bytes := uintptr(stack.StackBytes())
	return bytes != 0 && top >= bytes && base >= top-bytes && base < top && uintptr(frameBytes) <= top-base
}

func (r *gcNativeFrameRoots) rangeChain(fn func(gc.RootSlot) bool, sink gc.RootRefSink, stack *coreruntime.Engine) bool {
	return r.rangeChainFrom(r.owner, fn, sink, stack)
}

func (r *gcNativeFrameRoots) rangeChainFrom(owner *Instance, fn func(gc.RootSlot) bool, sink gc.RootRefSink, stack *coreruntime.Engine) bool {
	base, offsets, frameBytes := r.base, r.offsets, r.frameBytes
	codeBase, codeBytes := r.codeBase, r.codeBytes
	adapterReturnOffsets, callsites := r.adapterReturnOffsets, r.callsites
	// Parked host activations carry their physical stack bounds because reentry
	// may replace owner.eng while their native frames remain on the old stack.
	// Other chains use the owner mapping only when their first frame lies in it.
	var stackTop uintptr
	if stack != nil {
		stackTop = stack.StackTop()
		if !gcNativeFrameFitsStack(base, frameBytes, stack) {
			panic(gcHelperFailuref("generic GC native frame exceeds stack bounds"))
		}
	} else if owner != nil && owner.eng != nil {
		top := owner.eng.StackTop()
		ownerStackBytes := uintptr(owner.eng.StackBytes())
		if ownerStackBytes != 0 && top >= ownerStackBytes && base >= top-ownerStackBytes && base < top {
			stackTop = top
		}
	}
	for {
		// A host-activation aggregate can carry no direct native frame of its own;
		// its parked activation records are walked separately below.
		if base == 0 {
			return true
		}
		if stackTop != 0 && (base >= stackTop || uintptr(frameBytes) > stackTop-base) {
			panic(gcHelperFailuref("generic GC native frame exceeds stack bounds"))
		}
		if r.owner != nil && !visitManagedFunctionOwnerFrameRoot(owner, r.owner.gc, fn, sink) {
			return false
		}
		frameOffsets := offsets
		if owner != r.owner && r.owner != nil && owner != nil && owner.gc != r.owner.gc {
			// Compact handles are local to a collector. Traverse a foreign
			// frame's physical return map, never feed its words to this heap.
			frameOffsets = nil
		}
		for _, off := range frameOffsets {
			encoded := off
			off = shared.GCFrameRootOffset(encoded)
			if encoded&shared.GCFrameExternRefRootFlag != 0 {
				word := nativeGCFrameWord(base + uintptr(off))
				if r.owner == nil || !visitCompactExternFrameRoot(owner, r.owner.gc, word, fn, sink) {
					return false
				}
				continue
			}
			if encoded&shared.GCFrameFuncRefRootFlag != 0 {
				word := nativeGCFrameWord(base + uintptr(off))
				if !visitManagedFunctionFrameRoot(owner, word, fn, sink) {
					return false
				}
				continue
			}
			if r.frameLayout&gcNativeFrameLayoutMask != gcNativeFrameLayoutRISCV64 {
				bits := nativeGCFrameWord(base + uintptr(off))
				if bits != uint64(gc.Ref(uint32(bits))) {
					if owner == nil || !owner.isForeignAnyref(bits) {
						panic(gcHelperFailuref("generic GC frame-root offset %d contains non-compact reference %#x", off, bits))
					}
					continue
				}
			}
			// gc.Ref is the low 32 bits of the validated little-endian native qword.
			// Expose the actual off-heap word so a moving/reference-rewriting policy
			// updates the parked frame rather than a copied scratch value.
			slot := nativeGCFrameRootSlot(base + uintptr(off))
			if sink != nil {
				if !sink.VisitRootRef(slot.GetRef()) {
					return false
				}
			} else if !fn(slot) {
				return false
			}
		}
		// A callsite-free foreign target can still return through a caller owned by
		// another instance. Inspect the saved return PC before concluding that the
		// chain is complete; the caller's root plan supplies the continuation map.
		returnPCBias, callerFrameBias := uintptr(0), uintptr(abi.AMD64CallReturnAddressBytes)
		returnAddressAfterFrame := true
		switch r.frameLayout & gcNativeFrameLayoutMask {
		case gcNativeFrameLayoutARM64:
			returnPCBias = uintptr(shared.ARM64SavedLROffset)
			callerFrameBias = uintptr(shared.ARM64FrameRecordBytes)
		case gcNativeFrameLayoutRISCV64:
			// RV64 saves RA in word zero of the callee's allocated frame. The
			// caller frame begins immediately after that complete allocation.
			returnAddressAfterFrame = false
			callerFrameBias = 0
		}
		frameEnd := base
		if returnAddressAfterFrame {
			if base > ^uintptr(0)-uintptr(frameBytes) {
				panic(gcHelperFailuref("generic GC native frame address overflows"))
			}
			frameEnd += uintptr(frameBytes)
		}
		if frameEnd > ^uintptr(0)-returnPCBias {
			panic(gcHelperFailuref("generic GC native frame address overflows"))
		}
		retAddr := frameEnd + returnPCBias
		if stackTop != 0 && (retAddr > stackTop || stackTop-retAddr < 8) {
			panic(gcHelperFailuref("generic GC native return address exceeds stack bounds"))
		}
		retPC := uintptr(nativeGCFrameWord(retAddr))
		calleeOwner := owner
		if base > ^uintptr(0)-uintptr(frameBytes)-callerFrameBias {
			panic(gcHelperFailuref("generic GC caller frame address overflows"))
		}
		returnBase := base + uintptr(frameBytes) + callerFrameBias
		adapterRead := false
		for {
			if retPC < codeBase || retPC-codeBase >= codeBytes {
				// A stack-ABI public entry has no register adapter. Its top return
				// word is exactly the entry's existing trap landing slot. An unknown
				// PC elsewhere in the stack must still fail ownership validation.
				if r.frameLayout&gcNativeFrameLayoutMask == gcNativeFrameLayoutAMD64 && stack != nil && owner != nil && owner.jm != nil {
					landing := r.entryReturnSlot
					if landing%8 == 0 && landing == retAddr && stackTop >= uintptr(stack.StackBytes()) && landing >= stackTop-uintptr(stack.StackBytes()) && landing < stackTop && stackTop-landing >= 8 {
						return true
					}
				}
				if r.owner == nil || r.owner.refStore == nil || !r.owner.refStore.ownsGCCollector(r.owner.gc) {
					return true
				}
				foreign := r.owner.refStore.gcFrameOwner(retPC, owner.gc)
				if foreign == nil && r.frameLayout&gcNativeFrameLayoutMask != gcNativeFrameLayoutRISCV64 {
					foreign = r.owner.refStore.gcAnyFrameOwner(retPC, 0)
				}
				if foreign == nil {
					if r.allowExternalReturn {
						return true
					}
					panic(gcHelperFailuref("generic GC foreign return PC %#x has no Runtime GC-domain owner", retPC))
				}
				if foreign.c.genericGCFrameRoots() == nil {
					panic(gcHelperFailuref("generic GC foreign return PC %#x has no native unwind map; recompile the caller", retPC))
				}
				owner = foreign
				plan := foreign.c.genericGCFrameRoots()
				codeBase, codeBytes = foreign.base, uintptr(len(foreign.c.code))
				adapterReturnOffsets, callsites = plan.adapterReturnOffsets, plan.callsites
			}
			rel := uint32(retPC - codeBase)
			adapterIndex := 0
			if len(adapterReturnOffsets) <= 8 {
				for adapterIndex < len(adapterReturnOffsets) && adapterReturnOffsets[adapterIndex] < rel {
					adapterIndex++
				}
			} else {
				adapterIndex = sort.Search(len(adapterReturnOffsets), func(i int) bool { return adapterReturnOffsets[i] >= rel })
			}
			if adapterIndex == len(adapterReturnOffsets) || adapterReturnOffsets[adapterIndex] != rel {
				break
			}
			// RV64 keeps its validated adapter boundary. The physical record
			// traversal below is specific to AMD64 and ARM64.
			if r.frameLayout&gcNativeFrameLayoutMask == gcNativeFrameLayoutRISCV64 {
				return true
			}
			if owner == nil || owner.c == nil {
				return true // This chain has no retained compiled wrapper.
			}
			if adapterRead {
				panic(gcHelperFailuref("generic GC native return crosses nested adapters"))
			}
			// The validated register adapter saves one results-pointer word on
			// AMD64, or an LR/results pair on ARM64. Neither is the end of a
			// native cross-instance call: its caller can still own live roots.
			// Include AMD64's outer CALL return word in the same 16-byte span.
			if returnBase%8 != 0 || returnBase > ^uintptr(0)-16 || stackTop == 0 || returnBase > stackTop || stackTop-returnBase < 16 {
				panic(gcHelperFailuref("generic GC native adapter record exceeds stack bounds"))
			}
			outerReturnOffset := uintptr(8)
			if r.frameLayout&gcNativeFrameLayoutMask == gcNativeFrameLayoutARM64 {
				outerReturnOffset = 0
			}
			retAddr = returnBase + outerReturnOffset
			retPC = uintptr(binary.LittleEndian.Uint64(unsafe.Slice((*byte)(offHeapPtr(retAddr)), 8)))
			returnBase += 16
			adapterRead = true
		}
		rel := uint32(retPC - codeBase)
		// Tiny sorted tables beat binary-search setup; larger tables retain
		// logarithmic lookup. The measured crossover is between 8 and 16.
		callsiteIndex := 0
		if len(callsites) <= 8 {
			for callsiteIndex < len(callsites) && callsites[callsiteIndex].returnOffset < rel {
				callsiteIndex++
			}
		} else {
			callsiteIndex = sort.Search(len(callsites), func(i int) bool { return callsites[i].returnOffset >= rel })
		}
		if callsiteIndex == len(callsites) || callsites[callsiteIndex].returnOffset != rel {
			panic(gcHelperFailuref("generic GC native return offset %d has no callsite map", rel))
		}
		callsite := &callsites[callsiteIndex]
		offsets = callsite.offsets
		frameBytes = callsite.frameBytes
		stackAdjust := callsite.stackAdjust
		if owner != calleeOwner && stackAdjust != 64 && r.frameLayout&gcNativeFrameLayoutMask != gcNativeFrameLayoutRISCV64 && owner != nil && calleeOwner != nil && owner.gc != calleeOwner.gc {
			panic(gcHelperFailuref("generic GC cross-domain return lacks its saved caller context"))
		}
		if returnBase > ^uintptr(0)-uintptr(stackAdjust) {
			panic(gcHelperFailuref("generic GC caller stack adjustment overflows"))
		}
		// Every production 64-byte wrapper is a dynamic import or a
		// home-aware indirect/ref call. Both preserve the caller's immutable
		// native-context pointer: AMD64 at record+8, ARM64 at record+0.
		// Code can be shared by instances, so its representative owner only
		// selects the immutable plan; this saved identity selects the roots.
		if r.frameLayout&gcNativeFrameLayoutMask != gcNativeFrameLayoutRISCV64 && stackAdjust == 64 && owner != nil && owner.refStore != nil {
			if returnBase > ^uintptr(0)-64 || stackTop != 0 && (returnBase > stackTop || stackTop-returnBase < 64) {
				panic(gcHelperFailuref("generic GC caller context record exceeds stack bounds"))
			}
			contextOffset := uintptr(8)
			arm64 := r.frameLayout&gcNativeFrameLayoutMask == gcNativeFrameLayoutARM64
			if arm64 {
				contextOffset = 0
			}
			context := uintptr(binary.LittleEndian.Uint64(unsafe.Slice((*byte)(offHeapPtr(returnBase+contextOffset)), 8)))
			// ARM64 writes zero only when no context switch occurred.
			if context == 0 && arm64 && owner == calleeOwner {
				// Keep the current exact instance identity.
			} else if context == 0 {
				panic(gcHelperFailuref("generic GC caller context is unavailable"))
			} else if context != owner.nativeContext {
				caller := r.owner.refStore.gcFrameContextOwner(retPC, owner.gc, context)
				if caller == nil {
					caller = r.owner.refStore.gcAnyFrameOwner(retPC, context)
				}
				if caller == nil {
					panic(gcHelperFailuref("generic GC caller context %#x has no Runtime GC-domain code owner", context))
				}
				owner = caller
			}
		}
		base = returnBase + uintptr(stackAdjust)
	}
}

const gcPublicSlotLimit = 64

// gcPublicState serializes public-token, generic helper, and boundary-collection
// access. The first 64 result and argument roots stay inline. Wider workloads use
// reusable overflow slices; released result slots remain holes and are reused
// without making stale opaque tokens valid again.
type gcPublicState struct {
	gcDomainHostRootScratch
	mu                     sync.Mutex
	resultTokenCount       uint32
	resultRootsMade        uint32
	resultTokens           [gcPublicSlotLimit]uint64
	resultTokensExtra      []uint64
	resultRootSlots        [gcPublicSlotLimit]uint32
	resultRootSlotsExtra   []uint32
	argumentRootCount      uint32
	argumentRootsMade      uint32
	argumentRootSlots      [gcPublicSlotLimit]uint32
	argumentRootSlotsExtra []uint32
	cloneRootSlot          uint32
	cloneRootMade          bool
	// values is the bounded synchronous-helper constructor scratch. Collector
	// access is serialized by mu, so struct.new and array.new_fixed reuse it
	// without per-allocation Go heap traffic.
	values                [63]gc.Value
	valuesExtra           []gc.Value
	initializerRoots      gc.InitializerWordRootScratch
	arrayInitializerRoots gc.ArrayInitializerRootScratch
	frameRoots            gcNativeFrameRoots    // exact parked native-frame roots; reused under mu
	globalRoots           []gcGlobalRootMapping // generic-GC safe-boundary roots; allocated only when needed
	hostActivations       [gcHostActivationLimit]gcHostActivation
	hostActivationCount   uint8
	hostArgumentRootSlots [gcHostActivationLimit][coreruntime.MaxHostArity]uint32
	hostArgumentRootsMade [gcHostActivationLimit]uint8
	hostArgumentRootCount [gcHostActivationLimit]uint8
	hostResultRootSlots   [gcHostActivationLimit][coreruntime.MaxHostArity]uint32
	hostResultRootsMade   [gcHostActivationLimit]uint8
	hostResultRootCount   [gcHostActivationLimit]uint8
	hostRootPlan          *compiledGCFrameRoots
	hostCodeBase          uintptr
	hostCodeBytes         uintptr
}

type gcSuspendedRootOwner struct {
	owner *Instance
	state *gcPublicState
}

func (s *gcPublicState) resultCapacity() uint32 {
	return gcPublicSlotLimit + uint32(len(s.resultTokensExtra))
}

func (s *gcPublicState) resultToken(index uint32) uint64 {
	if index < gcPublicSlotLimit {
		return s.resultTokens[index]
	}
	return s.resultTokensExtra[index-gcPublicSlotLimit]
}

func (s *gcPublicState) setResultToken(index uint32, token uint64) {
	if index < gcPublicSlotLimit {
		s.resultTokens[index] = token
		return
	}
	s.resultTokensExtra[index-gcPublicSlotLimit] = token
}

func (s *gcPublicState) resultRootSlot(index uint32) uint32 {
	if index < gcPublicSlotLimit {
		return s.resultRootSlots[index]
	}
	return s.resultRootSlotsExtra[index-gcPublicSlotLimit]
}

func (s *gcPublicState) appendResultRootSlot(slot uint32) uint32 {
	index := s.resultRootsMade
	if index < gcPublicSlotLimit {
		s.resultRootSlots[index] = slot
	} else {
		s.resultRootSlotsExtra = append(s.resultRootSlotsExtra, slot)
		s.resultTokensExtra = append(s.resultTokensExtra, 0)
	}
	s.resultRootsMade++
	return index
}

func (s *gcPublicState) nextResultSlot() uint32 {
	for index := uint32(0); index < s.resultRootsMade; index++ {
		if s.resultToken(index) == 0 {
			return index
		}
	}
	return s.resultRootsMade
}

func (s *gcPublicState) constructorValues(count uint32) ([]gc.Value, error) {
	if count <= uint32(len(s.values)) {
		return s.values[:count], nil
	}
	if uint64(count) > uint64(maxInt()) {
		return nil, fmt.Errorf("GC constructor value count %d overflows int", count)
	}
	if cap(s.valuesExtra) < int(count) {
		s.valuesExtra = make([]gc.Value, count)
	} else {
		s.valuesExtra = s.valuesExtra[:count]
		clear(s.valuesExtra)
	}
	return s.valuesExtra, nil
}

func (s *gcPublicState) argumentRootSlot(index uint32) uint32 {
	if index < gcPublicSlotLimit {
		return s.argumentRootSlots[index]
	}
	return s.argumentRootSlotsExtra[index-gcPublicSlotLimit]
}

func (s *gcPublicState) appendArgumentRootSlot(slot uint32) {
	if s.argumentRootsMade < gcPublicSlotLimit {
		s.argumentRootSlots[s.argumentRootsMade] = slot
	} else {
		s.argumentRootSlotsExtra = append(s.argumentRootSlotsExtra, slot)
	}
	s.argumentRootsMade++
}

type externrefSlot struct {
	value      any
	generation uint32
	// nextFree is a pin count for a live public slot, a free-list link for a
	// released public slot, or externrefInternalSlot for an internal owner.
	nextFree uint32
}

// A converted collector value can own one public root through its extern slot.
// The root receipt is released after store.mu, like an ordinary GC token.
type rootedExternrefValue interface {
	externrefGCRoot() gcRefTokenEntry
	externrefPublicValue() any
}

// A host resource can issue a collector value after every importer closes.
// Its token holds a domain claim directly and releases outside store.mu.
type directRootedExternrefValue interface {
	externrefPublicValue() any
	releaseExternrefRoot()
}

func releaseRootedExternref(root gcRefTokenEntry) {
	unlockNative := lockNativeExecutionForHostAccess()
	domain := root.owner.lockGCCollector()
	var cleanup resourceCleanup
	cleanup.run(func() { releaseGCRefTokenMetadata(root) })
	cleanup.run(func() { unlockGCCollector(domain) })
	cleanup.run(unlockNative)
	cleanup.run(root.owner.releaseResourceRoot)
	cleanup.finish()
}

const externrefInternalSlot = ^uint32(0)

func newReferenceStore(private bool) *referenceStore {
	return &referenceStore{private: private, runtimeClosed: private}
}

func (s *referenceStore) ensureGCTopology() *gcDomainTopology {
	if s == nil {
		return nil
	}
	s.mu.Lock()
	if s.gcDomains == nil {
		s.gcDomains = new(gcDomainTopology)
	}
	topology := s.gcDomains
	s.mu.Unlock()
	return topology
}

func (topology *gcDomainTopology) bindFuncrefTables(store *referenceStore) error {
	for table := range topology.funcrefTables {
		if table == nil || table.owner == nil {
			continue
		}
		o := table.owner
		o.mu.Lock()
		foreign := o.hasForeignFuncrefStoreLocked(store)
		bound := o.funcrefGCStore
		if !foreign && (bound == nil || bound == store) {
			o.funcrefGCStore = store
		}
		o.mu.Unlock()
		if foreign || bound != nil && bound != store {
			return fmt.Errorf("wago: Runtime GC domains cannot share a mutable funcref table across reference stores")
		}
	}
	return nil
}

func (s *referenceStore) bindFuncrefGCStore() error {
	topology := s.ensureGCTopology()
	topology.funcrefMu.Lock()
	defer topology.funcrefMu.Unlock()
	if err := topology.bindFuncrefTables(s); err != nil {
		return err
	}
	topology.funcrefGCActive = true
	return nil
}

func (s *referenceStore) ownsGCCollector(collector *gc.Collector) bool {
	if s == nil || collector == nil {
		return false
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	domain := s.gcDomains.domainForCollectorLocked(collector)
	return domain != nil && !domain.conversionOwned
}

func (s *referenceStore) gcDomainForCollector(collector *gc.Collector) *gcStoreDomain {
	if s == nil || collector == nil {
		return nil
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.gcDomains.domainForCollectorLocked(collector)
}

func (s *referenceStore) lockGCCollector(collector *gc.Collector) *gcStoreDomain {
	if s == nil || collector == nil {
		return nil
	}
	s.mu.Lock()
	found := s.gcDomains.domainForCollectorLocked(collector)
	s.mu.Unlock()
	if found != nil {
		found.mu.Lock()
	}
	return found
}

func (in *Instance) lockGCCollector() *gcStoreDomain {
	if in == nil || in.refStore == nil {
		return nil
	}
	return in.refStore.lockGCCollector(in.gc)
}

func unlockGCCollector(domain *gcStoreDomain) {
	if domain != nil {
		domain.mu.Unlock()
		drainExceptionReclaims(domain.collector)
	}
}

// A conversion-only lease owns a stable sorted view, not the mutable topology.
// claims pin registered collectors even while admission waits or a callback is
// suspended. The store mutex protects the registry; the public invocation gate
// serializes active/suspended transitions for a particular root.
type gcInvocationSnapshot struct {
	in       *Instance
	owner    invocationID
	domains  gcInvocationDomainView
	previous *gcInvocationSnapshot
	active   bool
	pinned   bool
}

func (in *Instance) conversionInvocationSnapshot(owner invocationID) *gcInvocationSnapshot {
	if in == nil || in.refStore == nil || owner == 0 {
		return nil
	}
	s := in.refStore
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.gcDomains == nil {
		return nil
	}
	for snapshot := s.gcDomains.invocations[owner]; snapshot != nil; snapshot = snapshot.previous {
		if snapshot.in == in && snapshot.active {
			return snapshot
		}
	}
	return nil
}

// A native nested entry cannot acquire a wider set while the root owns domain
// gates. Inspect only store-protected metadata; never wait for another topology
// reader, nor acquire a missing domain out of order. A callback's suspended
// snapshots are excluded, so ordinary callback reentry still admits afresh.
func (in *Instance) borrowConversionInvocation(owner invocationID) (gcInvocationLease, bool, error) {
	if in == nil || in.refStore == nil {
		return gcInvocationLease{}, false, nil
	}
	s := in.refStore
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.gcDomains == nil {
		return gcInvocationLease{}, false, nil
	}
	var root *gcInvocationSnapshot
	for p := s.gcDomains.invocations[owner]; p != nil; p = p.previous {
		if p.active {
			root = p
			break
		}
	}
	if root == nil {
		return gcInvocationLease{}, false, nil
	}
	contains := func(d *gcStoreDomain) bool {
		if d == nil {
			return true
		}
		for i := 0; i < root.domains.len(); i++ {
			if root.domains.at(i) == d {
				return true
			}
		}
		return false
	}
	entry := s.instances[in]
	if entry == nil || entry.dynamicInvocationDomains && !entry.conversionOnlyInvocationDomains {
		return gcInvocationLease{}, true, fmt.Errorf("nested invocation exceeds conversion snapshot authority")
	}
	complete := contains(entry.gcDomain)
	for i := 0; i < entry.invocationDomains.len(); i++ {
		complete = complete && contains(entry.invocationDomains.at(i))
	}
	if entry.conversionOnlyInvocationDomains {
		for d := s.gcDomains.first; d != nil; d = d.next {
			if d.conversionPublishers != 0 || d.conversionClaims != 0 {
				complete = complete && contains(d)
			}
		}
	}
	if !complete {
		return gcInvocationLease{}, true, fmt.Errorf("nested invocation requires domains absent from the active root snapshot")
	}
	return gcInvocationLease{in: in, domains: root.domains, owner: owner}, true, nil
}

func (snapshot *gcInvocationSnapshot) setActive(active bool) {
	s := snapshot.in.refStore
	s.mu.Lock()
	snapshot.active = active
	s.mu.Unlock()
}

// Called with the topology reader, before waiting for any domain or native gate.
func (in *Instance) pinConversionInvocation(domains gcInvocationDomainView, owner invocationID) (*gcInvocationSnapshot, error) {
	s := in.refStore
	s.mu.Lock()
	defer s.mu.Unlock()
	for i := 0; i < domains.len(); i++ {
		d := domains.at(i)
		if !d.private && (s.gcDomains.domainForCollectorLocked(d.collector) != d || d.claims == ^uint32(0)) {
			return nil, fmt.Errorf("conversion invocation domain retired or claim overflow")
		}
	}
	for i := 0; i < domains.len(); i++ {
		if d := domains.at(i); !d.private {
			d.claims++
		}
	}
	snapshot := &gcInvocationSnapshot{in: in, owner: owner, domains: domains, pinned: true, previous: s.gcDomains.invocations[owner]}
	if s.gcDomains.invocations == nil {
		s.gcDomains.invocations = make(map[invocationID]*gcInvocationSnapshot)
	}
	s.gcDomains.invocations[owner] = snapshot
	return snapshot, nil
}

// Pin release never waits for topology. Readers may continue using registered
// zero-claim domains until the deferred writer atomically claims retirement.
func (snapshot *gcInvocationSnapshot) unpin() {
	if !snapshot.pinned {
		return
	}
	s := snapshot.in.refStore
	s.mu.Lock()
	topology := s.gcDomains
	if topology.invocations[snapshot.owner] != snapshot {
		panic("wago: conversion invocation release order")
	}
	if snapshot.previous == nil {
		delete(topology.invocations, snapshot.owner)
	} else {
		topology.invocations[snapshot.owner] = snapshot.previous
	}
	var retire []*gcStoreDomain
	for i := 0; i < snapshot.domains.len(); i++ {
		d := snapshot.domains.at(i)
		if d.private {
			continue
		}
		if topology.domainForCollectorLocked(d.collector) != d || d.claims == 0 {
			panic("wago: conversion invocation pin lost")
		}
		d.claims--
		if d.refs == 0 && d.claims == 0 {
			retire = append(retire, d)
		}
	}
	snapshot.pinned = false
	start := s.queueInvocationRetirementLocked(retire, s.runtimeClosed)
	s.mu.Unlock()
	if start {
		s.driveInvocationRetirement()
	}
}

type gcInvocationLease struct {
	snapshot *gcInvocationSnapshot
	in       *Instance
	topology *gcDomainTopology
	domains  gcInvocationDomainView
	owner    invocationID
	acquired bool
	dynamic  bool
}

func (in *Instance) gcInvocationDomainsForInspection() (gcInvocationDomainView, *gcDomainTopology) {
	if in == nil || in.refStore == nil || in.executionFlags.Load()&executionFlagDynamicGCDomain == 0 {
		return in.gcInvocationDomains(), nil
	}
	in.refStore.mu.Lock()
	topology := in.refStore.gcDomains
	in.refStore.mu.Unlock()
	if topology != nil {
		topology.RLock()
	}
	return in.gcInvocationDomains(), topology
}

func (in *Instance) reachesPrivateGCInvocationDomain() bool {
	domains, topology := in.gcInvocationDomainsForInspection()
	if topology != nil {
		defer topology.RUnlock()
	}
	for i := 0; i < domains.len(); i++ {
		if domains.at(i).private {
			return true
		}
	}
	return false
}

func (in *Instance) gcInvocationDomain() *gcStoreDomain {
	if in == nil || in.refStore == nil || in.gc == nil {
		return nil
	}
	in.refStore.mu.Lock()
	entry := in.refStore.instances[in]
	var domain *gcStoreDomain
	if entry != nil {
		domain = entry.gcDomain
	}
	in.refStore.mu.Unlock()
	return domain
}

func (in *Instance) gcInvocationDomains() gcInvocationDomainView {
	if in == nil || in.refStore == nil || in.gc == nil && in.executionFlags.Load()&executionFlagImportedGCDomain == 0 {
		return gcInvocationDomainView{}
	}
	store := in.refStore
	store.mu.Lock()
	entry := store.instances[in]
	var domains gcInvocationDomainView
	if entry != nil {
		if entry.dynamicInvocationDomains && entry.conversionOnlyInvocationDomains {
			set := new(gcInvocationDomainSet)
			set.add(entry.gcDomain)
			for i := 0; i < entry.invocationDomains.len(); i++ {
				set.add(entry.invocationDomains.at(i))
			}
			if topology := store.gcDomains; topology != nil {
				for domain := topology.first; domain != nil; domain = domain.next {
					if domain.conversionPublishers != 0 || domain.conversionClaims != 0 {
						set.add(domain)
					}
				}
			}
			set.sort()
			domains.set = set
		} else if entry.dynamicInvocationDomains {
			if entry.gcDomain != nil && entry.gcDomain.private {
				domains.local = entry.gcDomain
			}
			if topology := store.gcDomains; topology != nil {
				domains.first, domains.last, domains.n = topology.first, topology.last, topology.n
			}
			domains.dynamic = true
		} else {
			domains = gcInvocationDomainView{local: entry.gcDomain, set: entry.invocationDomains}
		}
	}
	store.mu.Unlock()
	return domains
}

// mayNeedGCInvocationLease reads current ownership: a reference store or
// dynamic GC domain can be published after a prepared handle is created.
func (in *Instance) mayNeedGCInvocationLease() bool {
	return in != nil && in.refStore != nil && (in.gc != nil || in.executionFlags.Load()&(executionFlagImportedGCDomain|executionFlagDynamicGCDomain) != 0)
}

func (in *Instance) lockGCInvocation(owner invocationID) gcInvocationLease {
	// Ordinary scalar calls still acquire the invocation gate, but modules with
	// no collector or imported/dynamic GC domain have nothing to lock here.
	if !in.mayNeedGCInvocationLease() {
		return gcInvocationLease{}
	}
	lease, _ := in.lockGCInvocationContext(context.Background(), owner)
	return lease
}

func (in *Instance) lockGCInvocationContext(ctx context.Context, owner invocationID) (gcInvocationLease, error) {
	if ctx != nil && ctx.Done() == nil {
		ctx = nil
	}
	if ctx != nil {
		if err := ctx.Err(); err != nil {
			return gcInvocationLease{}, err
		}
	}
	if owner == 0 {
		owner = newInvocationID()
	}
	// Borrowing existing authority must not wait behind a topology writer while
	// the caller already holds native/domain gates.
	if existing := in.conversionInvocationSnapshot(owner); existing != nil {
		if !existing.domains.ownedBy(owner) {
			panic("wago: partial conversion invocation ownership")
		}
		return gcInvocationLease{in: in, domains: existing.domains, owner: owner}, nil
	}
	if lease, borrowed, err := in.borrowConversionInvocation(owner); borrowed {
		return lease, err
	}
	dynamic := in != nil && in.refStore != nil && in.executionFlags.Load()&executionFlagDynamicGCDomain != 0
	var topology *gcDomainTopology
	conversionOnly := false
	if dynamic {
		in.refStore.mu.Lock()
		if entry := in.refStore.instances[in]; entry != nil {
			conversionOnly = entry.conversionOnlyInvocationDomains
		}
		topology = in.refStore.gcDomains
		in.refStore.mu.Unlock()
		if topology == nil {
			panic("wago: dynamic Runtime GC invocation has no topology")
		}
		if err := topology.lockContext(ctx, false); err != nil {
			return gcInvocationLease{}, err
		}
	}
	domains := in.gcInvocationDomains()
	if dynamic && conversionOnly {
		// A nested native entry can borrow its caller's authenticated owner ID.
		// The caller's complete view supplies lifetime pins (or its dynamic reader).
		if domains.len() != 0 && domains.ownedBy(owner) {
			topology.RUnlock()
			return gcInvocationLease{in: in, domains: domains, owner: owner}, nil
		}
		snapshot, err := in.pinConversionInvocation(domains, owner)
		topology.RUnlock()
		if err != nil {
			return gcInvocationLease{}, err
		}
		if err = domains.lockContext(ctx); err != nil {
			snapshot.unpin()
			return gcInvocationLease{}, err
		}
		domains.claim(owner)
		snapshot.setActive(true)
		return gcInvocationLease{in: in, topology: topology, domains: domains, owner: owner, acquired: true, snapshot: snapshot}, nil
	}
	if domains.len() == 0 {
		if dynamic {
			return gcInvocationLease{in: in, topology: topology, owner: owner, acquired: true, dynamic: true}, nil
		}
		return gcInvocationLease{}, nil
	}
	// A native cross-instance call reuses the public root's invocation identity.
	// The root pre-acquires the transitive, globally ordered domain set, so a
	// target reached through its retained imports borrows the already-held lease
	// instead of recursively locking the same non-reentrant mutexes.
	first := domains.at(0)
	first.invocationState.Lock()
	borrowed := first.invocationOwner == owner
	first.invocationState.Unlock()
	if borrowed {
		if !domains.ownedBy(owner) {
			panic("wago: partial Runtime GC invocation lease ownership")
		}
		if dynamic {
			topology.RUnlock()
		}
		return gcInvocationLease{in: in, topology: topology, domains: domains, owner: owner}, nil
	}
	if ctx == nil {
		domains.lock()
	} else if err := domains.lockContext(ctx); err != nil {
		if dynamic {
			topology.RUnlock()
		}
		return gcInvocationLease{}, err
	}
	domains.claim(owner)
	return gcInvocationLease{in: in, topology: topology, domains: domains, owner: owner, acquired: true, dynamic: dynamic}, nil
}

func (l gcInvocationLease) unlock() {
	if !l.acquired {
		return
	}
	if l.snapshot != nil {
		snapshot := l.snapshot
		if snapshot.active {
			snapshot.setActive(false)
			snapshot.domains.release(l.owner)
			snapshot.domains.unlock()
		}
		snapshot.unpin()
		return
	}
	domains := l.domains
	if l.dynamic && l.in != nil {
		domains = l.in.gcInvocationDomains()
	}
	domains.release(l.owner)
	domains.unlock()
	if l.dynamic {
		l.topology.RUnlock()
	}
}

func (in *Instance) ownsGCInvocation(owner invocationID) bool {
	domain := in.gcInvocationDomain()
	if domain == nil || owner == 0 {
		return false
	}
	domain.invocationState.Lock()
	owned := domain.invocationOwner == owner
	domain.invocationState.Unlock()
	return owned
}

type gcInvocationSuspension struct {
	snapshot *gcInvocationSnapshot
	in       *Instance
	topology *gcDomainTopology
	domains  gcInvocationDomainView
	owner    invocationID
	dynamic  bool
	active   bool
}

// hostCallNeedsGCSuspension is checked on the actual lease owner under native
// ownership. Collector identity and domain-admission flags are established
// before invocation. Dynamic topology always falls back, even when empty now.
// No signature-based test can replace this predicate: a scalar relay can own
// imported domains without having a local collector.
func (in *Instance) hostCallNeedsGCSuspension() bool {
	return in != nil && (in.gc != nil || in.executionFlags.Load()&
		(executionFlagImportedGCDomain|executionFlagDynamicGCDomain|executionFlagStoreOwnedGCCollector) != 0)
}

func (in *Instance) suspendGCInvocation(owner invocationID) gcInvocationSuspension {
	if snapshot := in.conversionInvocationSnapshot(owner); snapshot != nil {
		if !snapshot.domains.ownedBy(owner) {
			panic("wago: partial conversion invocation suspension")
		}
		snapshot.setActive(false)
		snapshot.domains.release(owner)
		snapshot.domains.unlock()
		return gcInvocationSuspension{in: in, owner: owner, snapshot: snapshot, active: true}
	}
	dynamic := in != nil && in.refStore != nil && in.executionFlags.Load()&executionFlagDynamicGCDomain != 0
	var topology *gcDomainTopology
	if dynamic {
		in.refStore.mu.Lock()
		topology = in.refStore.gcDomains
		in.refStore.mu.Unlock()
		if topology == nil {
			panic("wago: dynamic Runtime GC invocation has no topology")
		}
	}
	domains := in.gcInvocationDomains()
	if owner == 0 || domains.len() == 0 && !dynamic {
		return gcInvocationSuspension{}
	}
	if !domains.ownedBy(owner) {
		if !domains.dynamic && domains.set == nil {
			// Start-function and construction callbacks can run before a public
			// invocation lease exists. Their native entry is already serialized, so
			// there is no complete-call lease to suspend or restore.
			return gcInvocationSuspension{}
		}
		panic("wago: partial Runtime GC invocation lease ownership")
	}
	domains.release(owner)
	domains.unlock()
	if dynamic {
		topology.RUnlock()
	}
	return gcInvocationSuspension{in: in, topology: topology, domains: domains, owner: owner, dynamic: dynamic, active: true}
}

func (s *gcInvocationSuspension) resume() {
	if s == nil || !s.active {
		return
	}
	s.active = false
	if s.snapshot != nil {
		// Keep the outer lease object stable, but replace its pins and view before
		// reacquiring native execution. No old domain lock survives this refresh.
		old := s.snapshot
		old.unpin()
		lease := s.in.lockGCInvocation(s.owner)
		if lease.snapshot == nil {
			panic("wago: conversion invocation classification changed")
		}
		next := lease.snapshot
		store := s.in.refStore
		store.mu.Lock()
		*old = *next
		store.gcDomains.invocations[s.owner] = old
		store.mu.Unlock()
		return
	}
	domains := s.domains
	if s.dynamic {
		s.topology.RLock()
		domains = s.in.gcInvocationDomains()
	}
	domains.lock()
	domains.claim(s.owner)
}

func (s *referenceStore) rangeGCDomainPersistentRoots(collector *gc.Collector, fn func(gc.RootSlot) bool, sink gc.RootRefSink) bool {
	if s == nil || collector == nil {
		return true
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	for candidate, state := range s.instances {
		if state == nil || state.resourcesReleased || candidate == nil || candidate.gc != collector || candidate.c == nil || !managedFunctionOwnerRootsStrong(candidate, collector) {
			continue
		}
		for i, global := range candidate.globalCells {
			if global == nil || i >= len(candidate.c.Globals) || !isGCRefValType(candidate.c.Globals[i].Type) || len(global.cell) < 8 {
				continue
			}
			bits := binary.LittleEndian.Uint64(global.cell)
			ref := gc.Ref(uint32(bits))
			if bits != uint64(ref) {
				panic(gcHelperFailuref("Runtime GC-domain global %d contains non-compact reference %#x", i, bits))
			}
			slot := (*gc.Root)(unsafe.Pointer(&global.cell[0]))
			if sink != nil {
				if !sink.VisitRootRef(slot.GetRef()) {
					return false
				}
			} else if !fn(slot) {
				return false
			}
		}
		if !candidate.rangeLocalGCTableRoots(fn, sink) {
			return false
		}
	}
	return true
}

// The native entry lease and collector-domain invocation lease keep parked
// activations stable. Snapshot owners under the store lock, then release it
// before walking chains: a foreign return can look up another owner in this store.
func (s *referenceStore) rangeGCDomainSuspendedRoots(collector *gc.Collector, exclude *gcPublicState, roots *gcNativeFrameRoots, fn func(gc.RootSlot) bool, sink gc.RootRefSink) bool {
	var owners [gcHostActivationLimit]gcSuspendedRootOwner
	var extra []gcSuspendedRootOwner
	if roots.suspended != nil {
		extra = roots.suspended.suspendedOwnerScratch()
	}
	n := 0
	s.mu.Lock()
	appendOwner := func(owner *Instance) bool {
		if compiledArchitecture == 4 && owner.gc != collector {
			return true
		}
		state := owner.existingPublicGCState()
		if state == nil || state == exclude || state.hostActivationCount == 0 {
			return true
		}
		if n < len(owners) {
			owners[n] = gcSuspendedRootOwner{owner, state}
		} else {
			extra = append(extra, gcSuspendedRootOwner{owner, state})
		}
		n++
		return true
	}
	if compiledArchitecture == 4 {
		for owner, registration := range s.instances {
			if registration != nil && !registration.resourcesReleased && owner != nil {
				appendOwner(owner)
			}
		}
	} else {
		s.rangeRetainedFrameOwnersLocked(appendOwner)
	}
	s.mu.Unlock()
	if roots.suspended != nil {
		roots.suspended.retainSuspendedOwnerScratch(extra)
	}
	defer clear(extra)
	for i := 0; i < min(n, len(owners)); i++ {
		if !roots.rangeSuspendedRoots(owners[i].owner, owners[i].state, fn, sink) {
			return false
		}
	}
	for _, item := range extra {
		if !roots.rangeSuspendedRoots(item.owner, item.state, fn, sink) {
			return false
		}
	}
	return true
}

func (s *referenceStore) rangeGCDomainPersistentRootsClassified(collector *gc.Collector, sink gc.ClassifiedRootRefSink) bool {
	if s == nil || collector == nil || sink == nil {
		return true
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	for candidate, state := range s.instances {
		if state == nil || state.resourcesReleased || candidate == nil || candidate.gc != collector || candidate.c == nil || !managedFunctionOwnerRootsStrong(candidate, collector) {
			continue
		}
		for i, global := range candidate.globalCells {
			if global == nil || i >= len(candidate.c.Globals) || !isGCRefValType(candidate.c.Globals[i].Type) || len(global.cell) < 8 {
				continue
			}
			bits := binary.LittleEndian.Uint64(global.cell)
			ref := gc.Ref(uint32(bits))
			if bits != uint64(ref) {
				panic(gcHelperFailuref("Runtime GC-domain global %d contains non-compact reference %#x", i, bits))
			}
			if !sink.VisitClassifiedRootRef(gc.RootGlobal, ref) {
				return false
			}
		}
		if !candidate.rangeLocalGCTableRoots(nil, classifiedRootSink{sink: sink, class: gc.RootTable}) {
			return false
		}
	}
	return true
}

func (s *referenceStore) gcFrameOwner(pc uintptr, collector *gc.Collector) *Instance {
	return s.gcFrameContextOwner(pc, collector, 0)
}

// gcAnyFrameOwner selects an immutable return plan across collector domains.
// Shared code alone is not instance identity: the caller's saved context is
// authenticated below before any frame slots are visited.
func (s *referenceStore) gcAnyFrameOwner(pc, context uintptr) *Instance {
	if s == nil {
		return nil
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	matches := func(candidate *Instance) bool {
		return candidate != nil && candidate.c != nil && (context == 0 || candidate.nativeContext == context) && pc >= candidate.base && pc-candidate.base < uintptr(len(candidate.c.code))
	}
	for candidate, state := range s.instances {
		if state != nil && !state.resourcesReleased && candidate != nil && candidate.refStore == s && matches(candidate) {
			return candidate
		}
	}
	var found *Instance
	s.rangeRetainedFrameOwnersLocked(func(candidate *Instance) bool {
		if matches(candidate) {
			found = candidate
			return false
		}
		return true
	})
	return found
}

// rangeRetainedFrameOwnersLocked visits each retained local/import owner once.
// Callers hold s.mu and must not take a foreign store lock in visit.
func (s *referenceStore) rangeRetainedFrameOwnersLocked(visit func(*Instance) bool) bool {
	// Scalar imports may leave and reenter a store through an immutable native
	// relay. The local registration announces ResourcesReleased under s.mu
	// BEFORE detaching imports. Holding s.mu therefore retains its entire
	// transitive imported-code/context graph; no foreign store lock is needed.
	// Owner lookup uses this graph only after its fast local scan fails.
	// Parked-host discovery also uses it when a GC-capable callback is active.
	var inlinePending, inlineSeen [32]*Instance
	pending, seen := inlinePending[:0], inlineSeen[:0]
	var wideSeen map[*Instance]struct{}
	add := func(candidate *Instance) {
		if candidate == nil {
			return
		}
		if wideSeen != nil {
			if _, exists := wideSeen[candidate]; exists {
				return
			}
			wideSeen[candidate] = struct{}{}
		} else {
			for _, previous := range seen {
				if previous == candidate {
					return
				}
			}
			if len(seen) < len(inlineSeen) {
				seen = append(seen, candidate)
			} else {
				wideSeen = make(map[*Instance]struct{}, 64)
				for _, previous := range seen {
					wideSeen[previous] = struct{}{}
				}
				wideSeen[candidate] = struct{}{}
			}
		}
		pending = append(pending, candidate)
	}
	for candidate, state := range s.instances {
		if state != nil && !state.resourcesReleased && candidate != nil && candidate.refStore == s {
			add(candidate)
		}
	}
	for len(pending) != 0 {
		last := len(pending) - 1
		candidate := pending[last]
		pending = pending[:last]
		if !visit(candidate) {
			return false
		}
		for _, binding := range candidate.imports {
			if imported, ok := binding.(*InstanceExport); ok && imported != nil {
				add(imported.inst)
			}
		}
	}
	return true
}

func (s *referenceStore) gcFrameContextOwner(pc uintptr, collector *gc.Collector, context uintptr) *Instance {
	if s == nil || collector == nil {
		return nil
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if topology := s.gcDomains; topology != nil && topology.singleCodeOwner != nil {
		owner := topology.singleCodeOwner
		if owner.gc == collector && (context == 0 || owner.nativeContext == context) && pc >= owner.base && pc-owner.base < uintptr(len(owner.c.code)) {
			return owner
		}
		return nil
	}
	if topology := s.gcDomains; topology != nil && topology.codeRanges != nil {
		if ranges := topology.codeRanges.byCollector[collector]; ranges != nil {
			for _, image := range ranges.byPage[pc>>gcFrameCodeRangePageShift] {
				if pc >= image.key.base && pc-image.key.base < image.bytes {
					if context == 0 {
						return image.owner
					}
					for link := image.owners; link != nil; link = link.next {
						if candidate := link.instance; candidate.nativeContext == context {
							return candidate
						}
					}
				}
			}
		}
		return nil
	}
	for candidate, state := range s.instances {
		if state == nil || state.resourcesReleased || candidate == nil || candidate.gc != collector || candidate.c == nil || candidate.c.genericGCFrameRoots() == nil {
			continue
		}
		if (context == 0 || candidate.nativeContext == context) && pc >= candidate.base && pc-candidate.base < uintptr(len(candidate.c.code)) {
			return candidate
		}
	}
	return nil
}

func (s *referenceStore) gcNativeCallerOwner(pc, home, context uintptr) *Instance {
	s.mu.Lock()
	defer s.mu.Unlock()
	for candidate, registration := range s.instances {
		if registration != nil && !registration.resourcesReleased && candidate != nil && candidate.c != nil && candidate.jm != nil && candidate.nativeContext == context && candidate.jm.LinMemBase() == home && pc >= candidate.base && pc-candidate.base < uintptr(len(candidate.c.code)) {
			return candidate
		}
	}
	return nil
}

func (s *referenceStore) releaseUnclaimedGCCollector(collector *gc.Collector) {
	if s == nil || collector == nil {
		return
	}
	s.mu.Lock()
	topology := s.gcDomains
	if topology == nil {
		s.mu.Unlock()
		return
	}
	// A failed construction can drop its claim without waiting for live readers.
	domain := topology.domainForCollectorLocked(collector)
	if domain != nil {
		if domain.claims > 0 {
			domain.claims--
		}
		if domain.refs != 0 || domain.claims != 0 {
			s.mu.Unlock()
			return
		}
	}
	s.mu.Unlock()
	if domain == nil {
		return
	}
	topology.Lock()
	s.mu.Lock()
	domain = topology.domainForCollectorLocked(collector)
	if domain == nil || domain.refs != 0 || domain.claims != 0 || !topology.unlinkDomainLocked(domain) {
		s.mu.Unlock()
		topology.Unlock()
		return
	}
	s.mu.Unlock()
	topology.Unlock()
	collector.Close()
}

func equalGCConfigs(a, b gc.Config) bool {
	return a == b
}

func (s *referenceStore) acquireGCCollector(ctx context.Context, config gc.Config, c *Compiled, preferred *gc.Collector) (*gc.Collector, *gcTypeMapping, error) {
	if s == nil || s.private {
		return nil, nil, fmt.Errorf("wago: shared WasmGC ownership requires an explicit Runtime")
	}
	topology := s.ensureGCTopology()
	if err := topology.lockContext(ctx, true); err != nil {
		return nil, nil, err
	}
	topologyLocked := true
	defer func() {
		if topologyLocked {
			topology.Unlock()
		}
	}()
	if err := s.bindFuncrefGCStore(); err != nil {
		return nil, nil, err
	}
	s.mu.Lock()
	if s.runtimeClosed {
		s.mu.Unlock()
		return nil, nil, fmt.Errorf("wago: reference store is closed")
	}
	var selected *gcStoreDomain
	if preferred != nil {
		selected = topology.domainForCollectorLocked(preferred)
		if selected == nil {
			s.mu.Unlock()
			return nil, nil, fmt.Errorf("wago: imported WasmGC collector is not a live Runtime domain")
		}
		if selected.conversionOwned {
			s.mu.Unlock()
			return nil, nil, fmt.Errorf("wago: receipt-owned conversion collector is not a shared type domain")
		}
		if !equalGCConfigs(selected.config, config) {
			s.mu.Unlock()
			return nil, nil, fmt.Errorf("wago: WasmGC collector configuration is incompatible with the imported Runtime GC domain")
		}
	} else {
		for domain := topology.first; domain != nil; domain = domain.next {
			if domain.conversionOwned {
				continue
			}
			if !gcModuleFitsDomain(c, domain) {
				continue
			}
			if !equalGCConfigs(domain.config, config) {
				s.mu.Unlock()
				return nil, nil, fmt.Errorf("wago: WasmGC collector configuration is incompatible with the matching Runtime GC domain")
			}
			selected = domain
			break
		}
	}
	if selected == nil {
		mapping, types, reps, err := gcCanonicalTypePlan(c, nil, nil, true)
		if err != nil {
			s.mu.Unlock()
			return nil, nil, err
		}
		collector, err := gc.NewCollector(config, types)
		if err != nil {
			s.mu.Unlock()
			return nil, nil, err
		}
		selected = &gcStoreDomain{id: newGCDomainIdentity(), collector: collector, config: config, types: types, typeReps: reps, claims: 1}
		topology.appendDomainLocked(selected)
		s.mu.Unlock()
		c.rememberGCTypeMapping(selected.id, len(selected.typeReps), mapping)
		return collector, mapping, nil
	}
	if selected.claims == ^uint32(0) {
		s.mu.Unlock()
		return nil, nil, fmt.Errorf("wago: Runtime GC domain has too many pending instances")
	}
	selected.claims++
	s.mu.Unlock()
	topology.Unlock()
	topologyLocked = false

	// Native subtype readers hold invocationMu but do not enter Go or selected.mu.
	// Quiesce the whole domain before replacing and republishing the interval
	// backing, then follow the ordinary invocationMu -> mu lock order.
	if err := selected.invocationMu.lockContext(ctx); err != nil {
		s.releaseUnclaimedGCCollector(selected.collector)
		return nil, nil, err
	}
	selected.mu.Lock()
	domainTypeCount := len(selected.typeReps)
	mapping := c.cachedGCTypeMapping(selected.id, domainTypeCount)
	types, reps := selected.types, selected.typeReps
	var err error
	if mapping == nil {
		mapping, types, reps, err = gcCanonicalTypePlan(c, selected.typeReps, selected.types, preferred != nil)
	}
	if err == nil && len(types) > len(selected.types) {
		err = selected.collector.AddTypes(types[len(selected.types):])
	}
	if err == nil {
		// Compatibility probes read these slices under the store lock. Keep
		// publication in that lock as well as the collector's mutation lock.
		s.mu.Lock()
		selected.types, selected.typeReps = types, reps
		domainTypeCount = len(selected.typeReps)
		s.mu.Unlock()
	}
	selected.mu.Unlock()
	selected.invocationMu.Unlock()
	if err != nil {
		s.releaseUnclaimedGCCollector(selected.collector)
		return nil, nil, err
	}
	c.rememberGCTypeMapping(selected.id, domainTypeCount, mapping)
	return selected.collector, mapping, nil
}

func (s *referenceStore) registerInstance(in *Instance) error {
	managedFunctionPrepareRegistration(s, in)
	var importedInvocationDomains gcInvocationDomainSet
	fullDynamic := in != nil && (compiledManagedFunctionReachability(in.c) || !s.private && compiledHasDynamicFuncrefReachability(in.c))
	dynamicInvocationDomains := fullDynamic || in != nil && compiledConversionStoreHooks(in.c)
	importsPrivateInvocationDomain := false
	if in != nil && in.c != nil {
		for i, displayKey := range in.c.Imports {
			export, ok := in.imports[in.c.functionImportBindingKey(i)].(*InstanceExport)
			if !ok || export == nil || export.inst == nil {
				continue
			}
			if export.inst.executionFlags.Load()&executionFlagDynamicGCDomain != 0 || compiledManagedFunctionReachability(export.inst.c) {
				if export.inst.refStore != s {
					if export.inst.requiresSameRuntimeInvocation() {
						return fmt.Errorf("wago: dynamic funcref import %q requires the same Runtime", displayKey)
					}
					export.inst.refStore.mu.Lock()
					producer := export.inst.refStore.instances[export.inst]
					if producer != nil {
						importedInvocationDomains.add(producer.gcDomain)
						for j := 0; j < producer.invocationDomains.len(); j++ {
							importedInvocationDomains.add(producer.invocationDomains.at(j))
						}
					}
					export.inst.refStore.mu.Unlock()
					continue
				} else {
					dynamicInvocationDomains = true
					export.inst.refStore.mu.Lock()
					producer := export.inst.refStore.instances[export.inst]
					fullDynamic = fullDynamic || producer == nil || !producer.conversionOnlyInvocationDomains
					if producer != nil && producer.conversionOnlyInvocationDomains {
						importedInvocationDomains.add(producer.gcDomain)
						for j := 0; j < producer.invocationDomains.len(); j++ {
							importedInvocationDomains.add(producer.invocationDomains.at(j))
						}
					}
					export.inst.refStore.mu.Unlock()
					continue
				}
			}
			domains := export.inst.gcInvocationDomains()
			for i := 0; i < domains.len(); i++ {
				domain := domains.at(i)
				if domain.private {
					importsPrivateInvocationDomain = true
				}
				importedInvocationDomains.add(domain)
			}
		}
	}
	if fullDynamic && importsPrivateInvocationDomain {
		return fmt.Errorf("wago: dynamic funcref imports cannot reach a private GC invocation domain")
	}
	if in != nil && in.c != nil {
		if err := in.c.prepareStructuralCallIdentities(); err != nil {
			return fmt.Errorf("wago: prepare structural call identities: %w", err)
		}
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.runtimeClosed && !s.private {
		return fmt.Errorf("wago: reference store is closed")
	}
	if in == nil || in.c == nil {
		return fmt.Errorf("wago: reference store instance has no compiled metadata")
	}
	if s.instances == nil {
		s.instances = make(map[*Instance]*referenceStoreInstance)
	}
	if dynamicInvocationDomains && s.gcDomains == nil {
		s.gcDomains = new(gcDomainTopology)
	}
	if _, exists := s.instances[in]; exists {
		return nil
	}
	if s.liveInstances == ^uint32(0) {
		return fmt.Errorf("wago: reference store has too many live instances")
	}

	// Resolve every fast-key equality against exact structural descriptors before
	// publishing any descriptor from this instance. Native calls may then compare
	// the compact key authoritatively: the store invariant guarantees that one key
	// never denotes two distinct live structural types.
	candidate := make(map[uint64]structuralTypeRegistration)
	keyCapacity := len(in.c.FuncTypeID)
	if types := len(in.c.Types); types > 0 && types < keyCapacity {
		// Most functions reuse declared types. This is only an allocation hint:
		// append still accepts every distinct key, including legacy metadata.
		keyCapacity = types
	}
	keys := make([]uint64, 0, keyCapacity)
	var identitiesByType map[uint32][]byte
	var typeGroups map[uint32]structuralTypeGroupBounds
	identityBytes := 0
	for i, key := range in.c.FuncTypeID {
		canonical, cached := in.c.cachedStructuralCallIdentity(i)
		if !cached {
			sig, sigOK := compiledFunctionSignature(in.c, i)
			if sigOK && sig.HasTypeIndex {
				canonical = identitiesByType[sig.TypeIndex]
			}
			if canonical == nil {
				if typeGroups == nil && sigOK && sig.HasTypeIndex {
					typeGroups = compiledStructuralTypeGroups(in.c.Types)
				}
				var err error
				canonical, err = compiledStructuralCallIdentityWithGroups(in.c, i, typeGroups)
				if err != nil {
					return fmt.Errorf("wago: function %d exact type: %w", i, err)
				}
				if sigOK && sig.HasTypeIndex && len(in.c.FuncTypeID) > 1 {
					if identitiesByType == nil {
						identitiesByType = make(map[uint32][]byte, min(keyCapacity, len(in.c.Types)))
					}
					identitiesByType[sig.TypeIndex] = canonical
				}
			}
		}
		exact := structuralTypeRegistration{canonical: canonical}
		if prior, ok := candidate[key]; ok {
			if !bytes.Equal(prior.canonical, exact.canonical) {
				return fmt.Errorf("wago: native structural type key %#x collides within module", key)
			}
			continue
		}
		if len(canonical) > maxStructuralCallIdentityRegistrationBytes-identityBytes {
			return fmt.Errorf("wago: structural call identities exceed the %d-byte per-registration budget", maxStructuralCallIdentityRegistrationBytes)
		}
		identityBytes += len(canonical)
		candidate[key] = exact
		keys = append(keys, key)
		if registered, ok := s.typeKeys[key]; ok && !bytes.Equal(registered.canonical, exact.canonical) {
			return fmt.Errorf("wago: native structural type key %#x collides with a distinct store type", key)
		}
	}
	for _, key := range keys {
		if registered, ok := s.typeKeys[key]; ok && registered.refs == ^uint32(0) {
			return fmt.Errorf("wago: native structural type key %#x has too many owners", key)
		}
	}
	if s.typeKeys == nil {
		s.typeKeys = make(map[uint64]structuralTypeRegistration)
		s.instanceTypes = make(map[*Instance][]uint64)
	}
	for _, key := range keys {
		registered, ok := s.typeKeys[key]
		if !ok {
			registered = candidate[key]
		}
		registered.refs++
		s.typeKeys[key] = registered
	}
	var domain *gcStoreDomain
	if topology := s.gcDomains; topology != nil {
		domain = topology.domainForCollectorLocked(in.gc)
		if domain != nil {
			if domain.refs == ^uint32(0) {
				return fmt.Errorf("wago: Runtime GC domain has too many instances")
			}
			if domain.claims == 0 {
				return fmt.Errorf("wago: Runtime GC domain registration has no prepared claim")
			}
			domain.claims--
			domain.refs++
		}
	}
	if domain == nil && in.gc != nil {
		// Private collectors still need complete-call ownership through public
		// result tokenization. Keep their invocation domain out of the Runtime
		// topology so ownership, root scanning, and collector lifetime remain local.
		domain = &gcStoreDomain{id: newGCDomainIdentity(), collector: in.gc, private: true}
	}
	invocationDomains := importedInvocationDomains
	invocationDomains.add(domain)
	invocationDomains.sort()
	var storedInvocationDomains *gcInvocationDomainSet
	if !fullDynamic && invocationDomains.len() != 0 && (invocationDomains.len() != 1 || invocationDomains.at(0) != domain) {
		storedInvocationDomains = new(gcInvocationDomainSet)
		*storedInvocationDomains = invocationDomains
	}
	flagsToAdd := uint32(0)
	if domain != nil && !domain.private {
		flagsToAdd |= executionFlagStoreOwnedGCCollector
	}
	if dynamicInvocationDomains || storedInvocationDomains != nil {
		flagsToAdd |= executionFlagImportedGCDomain
		if dynamicInvocationDomains {
			flagsToAdd |= executionFlagDynamicGCDomain
		}
	}
	for flagsToAdd != 0 {
		flags := in.executionFlags.Load()
		if flags&flagsToAdd == flagsToAdd || in.executionFlags.CompareAndSwap(flags, flags|flagsToAdd) {
			break
		}
	}
	s.instanceTypes[in] = keys
	s.instances[in] = &referenceStoreInstance{
		gcDomain: domain, invocationDomains: storedInvocationDomains,
		dynamicInvocationDomains:        dynamicInvocationDomains,
		conversionOnlyInvocationDomains: dynamicInvocationDomains && !fullDynamic,
	}
	s.registerGCFrameCodeRangeLocked(in)
	s.liveInstances++
	managedFunctionRegisteredLocked(s, in)
	return nil
}

func compiledHasDynamicFuncrefReachability(c *Compiled) bool {
	if c == nil {
		return false
	}
	if compiledManagedFunctionReachability(c) {
		return true
	}
	// A funcref table or global can acquire a cross-instance descriptor after
	// instantiation. Conservatively lease every live Runtime GC domain for these
	// container-bearing modules; ordinary ref.func and direct-import modules keep
	// their compact statically discovered domain sets.
	if c.hasFuncrefTable() {
		return true
	}
	for i := range c.Globals {
		if c.Globals[i].Type == ValFuncRef {
			return true
		}
	}
	if c.requiredFeatures.IsEnabled(CoreFeatureTypedFunctionReferences) {
		for i := range c.importFuncSigs {
			if funcSigHasFuncref(c.importFuncSigs[i]) {
				return true
			}
		}
		for i := range c.Funcs {
			if funcSigHasFuncref(c.Funcs[i]) {
				return true
			}
		}
	}
	return false
}

func funcSigHasFuncref(sig FuncSig) bool {
	for _, typ := range sig.Params {
		if typ == ValFuncRef {
			return true
		}
	}
	for _, typ := range sig.Results {
		if typ == ValFuncRef {
			return true
		}
	}
	return false
}

func compiledFunctionSignature(c *Compiled, index int) (FuncSig, bool) {
	if c == nil || index < 0 {
		return FuncSig{}, false
	}
	if index < c.NumImports {
		if index >= len(c.importFuncSigs) {
			return FuncSig{}, false
		}
		return c.importFuncSigs[index], true
	}
	local := index - c.NumImports
	if local < 0 || local >= len(c.Funcs) {
		return FuncSig{}, false
	}
	return c.Funcs[local], true
}

func (s *referenceStore) releaseGCDomainLocked(entry *referenceStoreInstance) *gc.Collector {
	if entry == nil || entry.gcDomain == nil {
		return nil
	}
	domain := entry.gcDomain
	entry.gcDomain = nil
	if domain.private {
		return nil
	}
	if domain.refs > 0 {
		domain.refs--
	}
	if domain.refs != 0 || domain.claims != 0 {
		return nil
	}
	topology := s.gcDomains
	if topology == nil {
		return nil
	}
	if topology.unlinkDomainLocked(domain) {
		return domain.collector
	}
	return nil
}

func (s *referenceStore) lockGCDomainTopology() *gcDomainTopology {
	if s == nil {
		return nil
	}
	s.mu.Lock()
	topology := s.gcDomains
	s.mu.Unlock()
	if topology != nil {
		topology.Lock()
	}
	return topology
}

func (s *referenceStore) lockGCDomainTopologyForInstance(in *Instance) *gcDomainTopology {
	if in == nil {
		return nil
	}
	if in.gc == nil {
		s.mu.Lock()
		receipts := s.gcDomains != nil && len(s.gcDomains.conversionContainers) != 0
		s.mu.Unlock()
		if !receipts {
			return nil
		}
	}
	return s.lockGCDomainTopology()
}

// abortRegisteredInstance terminates store membership for an instance whose
// instantiation failed after registration but before publication.
func (s *referenceStore) abortRegisteredInstance(in *Instance) {
	var release referenceTokenEntries
	var collector *gc.Collector
	topology := s.lockGCDomainTopologyForInstance(in)
	s.mu.Lock()
	if entry := s.instances[in]; entry != nil {
		managedFunctionLifetimeLocked(s, in, true)
		if !entry.closeAccounted && s.liveInstances > 0 {
			s.liveInstances--
		}
		collector = s.releaseGCDomainLocked(entry)
		s.unregisterInstanceTypesLocked(in)
		delete(s.instances, in)
	}
	release = s.maybeReleaseEntriesLocked()
	s.mu.Unlock()
	if topology != nil {
		topology.Unlock()
	}
	releaseLifetimeEntries(collector, release)
}

func (s *referenceStore) advanceInstanceLifetime(in *Instance, event referenceLifetimeEvent) {
	var release referenceTokenEntries
	var collector *gc.Collector
	topology := s.lockGCDomainTopologyForInstance(in)
	s.mu.Lock()
	if entry := s.instances[in]; entry != nil {
		managedFunctionLifetimeLocked(s, in, event == referenceLifetimeResourcesReleased)
		switch event {
		case referenceLifetimeClosed:
			if !entry.closeAccounted {
				entry.closeAccounted = true
				if s.liveInstances > 0 {
					s.liveInstances--
				}
			}
		case referenceLifetimeQuiesced:
			entry.quiesced = true
		case referenceLifetimeResourcesReleased:
			if !entry.resourcesReleased {
				entry.resourcesReleased = true
				collector = s.releaseGCDomainLocked(entry)
			}
		}
		if entry.closeAccounted && entry.quiesced && entry.resourcesReleased {
			s.unregisterInstanceTypesLocked(in)
			delete(s.instances, in)
		}
	}
	release = s.maybeReleaseEntriesLocked()
	s.mu.Unlock()
	if topology != nil {
		topology.Unlock()
	}
	releaseLifetimeEntries(collector, release)
}

func (s *referenceStore) allClosedInstancesQuiescedLocked() bool {
	for _, entry := range s.instances {
		if entry.closeAccounted && !entry.quiesced {
			return false
		}
	}
	return true
}

func (s *referenceStore) canReleaseEntriesLocked() bool {
	return (s.gcDomains == nil || len(s.gcDomains.invocations) == 0) && s.runtimeClosed && s.liveInstances == 0 && s.liveObjects == 0 && len(s.gcByToken) == 0 && s.allClosedInstancesQuiescedLocked()
}

func (s *referenceStore) maybeReleaseEntriesLocked() referenceTokenEntries {
	if s.canReleaseEntriesLocked() {
		return s.releaseEntriesLocked()
	}
	// A logically closed host cell can remain physically attached to an
	// instance kept alive by one of these public tokens. Retire only public
	// roots here; native pins, domain claims and physical owners must survive
	// until the ordinary final-detach path consumes them.
	return s.closedHostPublicTokenEntriesLocked()
}

func (s *referenceStore) closedHostPublicTokenEntriesLocked() referenceTokenEntries {
	if !s.runtimeClosed || s.liveInstances != 0 || len(s.gcByToken) != 0 ||
		!s.allClosedInstancesQuiescedLocked() || !railshotClosedCompactExternHostObjectsLocked(s, s.liveObjects) {
		return referenceTokenEntries{}
	}
	return s.releaseClosedHostPublicTokensLocked()
}

func (s *referenceStore) releaseClosedHostPublicTokensLocked() referenceTokenEntries {
	var entries referenceTokenEntries
	for token, entry := range s.byToken {
		if entry.resultClaims != 0 {
			continue
		}
		delete(s.byToken, token)
		entries.funcrefs = append(entries.funcrefs, entry)
	}
	for identity, entry := range s.byIdentity {
		if s.byToken[entry.token] == nil {
			delete(s.byIdentity, identity)
		}
	}
	for i := range s.externrefs {
		slot := &s.externrefs[i]
		if slot.nextFree != 0 {
			continue
		}
		if value, ok := slot.value.(directRootedExternrefValue); ok {
			entries.directExternrefs = append(entries.directExternrefs, value)
		} else if value, ok := slot.value.(rootedExternrefValue); ok {
			entries.gcRefs = append(entries.gcRefs, value.externrefGCRoot())
		} else {
			continue
		}
		slot.value = releasedExternrefValue
		slot.generation = nextExternrefGeneration(slot.generation)
		slot.nextFree = s.externFree
		s.externFree = uint32(i) + 1
	}
	return entries
}

func (s *referenceStore) unregisterInstanceTypesLocked(in *Instance) {
	s.unregisterGCFrameCodeRangeLocked(in)
	for _, key := range s.instanceTypes[in] {
		registered, ok := s.typeKeys[key]
		if !ok {
			continue
		}
		if registered.refs <= 1 {
			delete(s.typeKeys, key)
		} else {
			registered.refs--
			s.typeKeys[key] = registered
		}
	}
	delete(s.instanceTypes, in)
}

func (s *referenceStore) registerStoreObject() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.runtimeClosed {
		return fmt.Errorf("wago: reference store is closed")
	}
	if s.liveObjects == ^uint32(0) {
		return fmt.Errorf("wago: reference store has too many live objects")
	}
	s.liveObjects++
	return nil
}

const hostFuncRefDispatchBit = uint32(1 << 31)

func (s *referenceStore) registerHostFuncRef(owner *HostFuncRef) (uint32, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.runtimeClosed {
		return 0, fmt.Errorf("wago: reference store is closed")
	}
	if s.liveObjects == ^uint32(0) || len(s.externrefs) >= int(hostFuncRefDispatchBit-1) {
		return 0, fmt.Errorf("wago: reference store has too many live objects")
	}
	s.liveObjects++
	s.externrefs = append(s.externrefs, externrefSlot{value: owner, nextFree: externrefInternalSlot})
	return uint32(len(s.externrefs)), nil
}

func nextExternrefGeneration(generation uint32) uint32 {
	generation++
	if generation == 0 {
		generation = 1
	}
	return generation
}

var retiredHostFuncRefDispatchBinding = &hostFuncRefDispatchBinding{}

func (s *referenceStore) registerHostFuncRefBindingLocked(binding *hostFuncRefDispatchBinding) (uint32, error) {
	if s.runtimeClosed {
		return 0, fmt.Errorf("wago: reference store is closed")
	}
	for i := range s.externrefs {
		if s.externrefs[i].value == retiredHostFuncRefDispatchBinding {
			s.externrefs[i].generation = nextExternrefGeneration(s.externrefs[i].generation)
			s.externrefs[i].value = binding
			return uint32(i + 1), nil
		}
	}
	if len(s.externrefs) >= int(hostFuncRefDispatchBit-1) {
		return 0, fmt.Errorf("wago: reference store has too many host dispatch bindings")
	}
	s.externrefs = append(s.externrefs, externrefSlot{value: binding, generation: 1, nextFree: externrefInternalSlot})
	return uint32(len(s.externrefs)), nil
}

func (s *referenceStore) unregisterHostFuncRefBindingLocked(binding *hostFuncRefDispatchBinding) {
	if binding == nil || binding.dispatchIndex == 0 || uint64(binding.dispatchIndex) > uint64(len(s.externrefs)) {
		return
	}
	slot := &s.externrefs[binding.dispatchIndex-1]
	if slot.value != binding {
		return
	}
	slot.value = retiredHostFuncRefDispatchBinding
	slot.generation = nextExternrefGeneration(slot.generation)
}

func (s *referenceStore) hostFuncRefDispatch(dispatch uint32) (*HostFuncRef, *hostFuncRefDispatchBinding) {
	index := dispatch &^ hostFuncRefDispatchBit
	if dispatch&hostFuncRefDispatchBit == 0 || index == 0 {
		return nil, nil
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if uint64(index) > uint64(len(s.externrefs)) {
		return nil, nil
	}
	switch value := s.externrefs[index-1].value.(type) {
	case *HostFuncRef:
		return value, nil
	case *hostFuncRefDispatchBinding:
		return value.owner, value
	default:
		return nil, nil
	}
}

func (s *referenceStore) hostFuncRef(dispatch uint32) *HostFuncRef {
	owner, _ := s.hostFuncRefDispatch(dispatch)
	return owner
}

func (s *referenceStore) storeObjectClosed() {
	defer drainManagedFunctionStoreReclaims(s)
	var release referenceTokenEntries
	topology := s.lockGCDomainTopology()
	s.mu.Lock()
	if s.liveObjects > 0 {
		s.liveObjects--
	}
	release = s.maybeReleaseEntriesLocked()
	s.mu.Unlock()
	if topology != nil {
		topology.Unlock()
	}
	releaseReferenceEntries(release)
}

func (s *referenceStore) closeRuntime() {
	defer drainManagedFunctionStoreReclaims(s)
	var release referenceTokenEntries
	topology := s.lockGCDomainTopology()
	s.mu.Lock()
	s.runtimeClosed = true
	release = s.maybeReleaseEntriesLocked()
	s.mu.Unlock()
	if topology != nil {
		topology.Unlock()
	}
	releaseReferenceEntries(release)
}

// emptyForInlineClose reports whether closing the store has constant work. The
// caller has already published Runtime shutdown, so no new entries can arrive.
func (s *referenceStore) emptyForInlineClose() bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.liveInstances == 0 && s.liveObjects == 0 && len(s.instances) == 0 &&
		len(s.instanceTypes) == 0 && len(s.byIdentity) == 0 && len(s.byToken) == 0 &&
		len(s.gcByToken) == 0 && len(s.externrefs) == 0 && s.gcDomains == nil
}

func (s *referenceStore) issue(source *Instance, descriptor uint64) (uint64, error) {
	return s.issueMode(source, descriptor, false)
}

// issueAttachedResult is restricted to result egress from a function import
// attachment. The caller's live attachment proves that a logically closed
// producer is still physically retained, so first-time token issuance may take
// over that lifetime with a finalization root.
func (s *referenceStore) issueAttachedResult(source *Instance, descriptor uint64) (uint64, error) {
	return s.issueMode(source, descriptor, true)
}

func (s *referenceStore) issueMode(source *Instance, descriptor uint64, attachedResult bool) (uint64, error) {
	token, _, err := s.issueResultMode(source, descriptor, attachedResult, nil, false)
	return token, err
}

func (s *referenceStore) issueResultMode(source *Instance, descriptor uint64, attachedResult bool, journal []publicResultToken, provisional bool) (uint64, *funcrefTokenEntry, error) {
	if descriptor == 0 {
		return 0, nil, nil
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	existing := func(entry *funcrefTokenEntry) (uint64, *funcrefTokenEntry, error) {
		if !railshotValidFuncrefPublication(s, entry.owner, entry.descriptor) {
			return 0, nil, fmt.Errorf("invalid funcref result descriptor")
		}
		if !provisional {
			entry.published = true
			return entry.token, nil, nil
		}
		if entry.published {
			return entry.token, nil, nil
		}
		for _, issued := range journal {
			if issued.funcref == entry {
				return entry.token, nil, nil
			}
		}
		if entry.resultClaims == ^uint32(0) {
			return 0, nil, fmt.Errorf("funcref result claim limit")
		}
		entry.resultClaims++
		return entry.token, entry, nil
	}
	// RV64's imported descriptors are importer-owned wrappers. Authenticate
	// their frozen publication metadata even when a token was already issued.
	if railshotNativeContextTrapABI() && source != nil {
		if index, own := source.funcrefDescriptorIndex(descriptor); own && index < source.c.NumImports {
			if _, _, valid := s.canonicalFuncrefOwnerLocked(source, descriptor); !valid {
				return 0, nil, fmt.Errorf("invalid funcref result descriptor")
			}
		}
	}
	if entry := s.byIdentity[funcrefIdentity{descriptor: descriptor}]; entry != nil {
		if entry.owner != nil && entry.owner.hostEvents != nil {
			return 0, nil, deferredHostEventCalleeError()
		}
		return existing(entry)
	}
	if source == nil {
		return 0, nil, fmt.Errorf("invalid funcref result descriptor")
	}
	owner, canonical, ok := s.canonicalFuncrefOwnerLocked(source, descriptor)
	if !ok {
		return 0, nil, fmt.Errorf("invalid funcref result descriptor")
	}
	if owner.hostEvents != nil {
		return 0, nil, deferredHostEventCalleeError()
	}
	identity, hasIdentity := source.funcrefFunctionIdentity(descriptor)
	if hasIdentity {
		if entry := s.byIdentity[identity]; entry != nil {
			if entry.owner != nil && entry.owner.hostEvents != nil {
				return 0, nil, deferredHostEventCalleeError()
			}
			return existing(entry)
		}
	}
	if entry := s.byIdentity[funcrefIdentity{descriptor: canonical}]; entry != nil {
		if entry.owner != nil && entry.owner.hostEvents != nil {
			return 0, nil, deferredHostEventCalleeError()
		}
		return existing(entry)
	}
	var retained bool
	// RV64 canonicalization authenticates foreign rows against retained
	// attachments before returning their owner. A local wrapper can return
	// such a row after the producer closes, just as an imported export can.
	// Only result conversion may transfer this already-held physical lifetime.
	retainedForeignResult := provisional && railshotNativeContextTrapABI() && owner != source && s.hasInstanceResourcesLocked(owner)
	if attachedResult || retainedForeignResult {
		retained = owner.retainResourceRootForFinalization()
	} else {
		retained = owner.retainResourceRoot()
	}
	if !retained {
		return 0, nil, fmt.Errorf("funcref producer is closed")
	}
	token, err := s.newTokenLocked()
	if err != nil {
		owner.releaseResourceRoot()
		return 0, nil, err
	}
	entry := &funcrefTokenEntry{token: token, descriptor: canonical, owner: owner, published: !provisional}
	if provisional {
		entry.resultClaims = 1
	}
	if s.byIdentity == nil {
		s.byIdentity = make(map[funcrefIdentity]*funcrefTokenEntry)
		s.byToken = make(map[uint64]*funcrefTokenEntry)
	}
	s.byIdentity[funcrefIdentity{descriptor: canonical}] = entry
	if hasIdentity {
		s.byIdentity[identity] = entry
	}
	s.byToken[token] = entry
	if hostOwner := owner.hostFuncRefForDescriptor(canonical); hostOwner != nil && !hostOwner.markTokenLive(owner, canonical) {
		delete(s.byIdentity, funcrefIdentity{descriptor: canonical})
		if hasIdentity {
			delete(s.byIdentity, identity)
		}
		delete(s.byToken, token)
		owner.releaseResourceRoot()
		return 0, nil, fmt.Errorf("host funcref owner closed during token issue")
	}
	return token, entry, nil
}

// finishFuncrefResult commits a successful boundary or rolls back an unpublished
// token. Existing tokens and tokens observed by another boundary are preserved.
func (s *referenceStore) finishFuncrefResult(entry *funcrefTokenEntry, success bool) {
	s.mu.Lock()
	if s.byToken[entry.token] != entry {
		s.mu.Unlock()
		return
	}
	if entry.resultClaims == 0 {
		s.mu.Unlock()
		panic("funcref result claim underflow")
	}
	entry.resultClaims--
	entry.published = entry.published || success
	if entry.published || entry.resultClaims != 0 {
		s.mu.Unlock()
		return
	}
	delete(s.byToken, entry.token)
	for key, alias := range s.byIdentity {
		if alias == entry {
			delete(s.byIdentity, key)
		}
	}
	s.mu.Unlock()
	var cleanup resourceCleanup
	cleanup.run(func() { releaseFuncrefTokenMetadata(entry) })
	cleanup.run(entry.owner.releaseResourceRoot)
	cleanup.finish()
}

func (in *Instance) publicGCState() *gcPublicState {
	plugin := in.ensurePluginState()
	state := plugin.gcPublic.Load()
	if state == nil {
		candidate := &gcPublicState{}
		if plugin.gcPublic.CompareAndSwap(nil, candidate) {
			state = candidate
		} else {
			state = plugin.gcPublic.Load()
		}
	}
	return state
}

func (in *Instance) existingPublicGCState() *gcPublicState {
	if in == nil {
		return nil
	}
	plugin := in.pluginState.Load()
	if plugin == nil {
		return nil
	}
	return plugin.gcPublic.Load()
}

func (s *referenceStore) issueGCRef(source *Instance, ref gc.Ref, required ValueTypeDescriptor) (uint64, error) {
	return s.issueGCRefMode(source, ref, required, false)
}

// Callback arguments may originate in a logically closed native producer held
// by the current invocation. The callback generation and physical root retain
// keep this narrow publication path separate from public result publication.
func (s *referenceStore) issueCallbackGCRef(caller instanceHostModule, ref gc.Ref, required ValueTypeDescriptor) (uint64, error) {
	if caller.scope == nil || caller.generation == 0 || !caller.valid() || caller.in == nil || caller.in.refStore != s {
		return 0, fmt.Errorf("GC callback reference is outside its active host scope")
	}
	return s.issueGCRefMode(caller.in, ref, required, true)
}

func (s *referenceStore) issueGCRefMode(source *Instance, ref gc.Ref, required ValueTypeDescriptor, retained bool) (uint64, error) {
	if source == nil || ref.IsNull() || !ref.IsObj() {
		return 0, fmt.Errorf("invalid non-null GC result")
	}
	if source.c == nil {
		return 0, fmt.Errorf("public GC result ownership is outside exact collector execution")
	}
	unlockNative := lockNativeExecutionForHostAccess()
	defer unlockNative()
	lockedDomain := source.lockGCCollector()
	defer unlockGCCollector(lockedDomain)
	state := source.publicGCState()
	state.mu.Lock()
	defer state.mu.Unlock()
	return s.issueGCRefLockedMode(source, state, ref, required, retained)
}

// issueGCRefLocked publishes a retained public token while the caller holds
// native execution, the collector domain, and state.mu, in that order.
func (s *referenceStore) issueGCRefLocked(source *Instance, state *gcPublicState, ref gc.Ref, required ValueTypeDescriptor) (uint64, error) {
	return s.issueGCRefLockedMode(source, state, ref, required, false)
}

func (s *referenceStore) issueGCRefLockedMode(source *Instance, state *gcPublicState, ref gc.Ref, required ValueTypeDescriptor, retained bool) (uint64, error) {
	if source == nil || ref.IsNull() || !ref.IsObj() {
		return 0, fmt.Errorf("invalid non-null GC result")
	}
	if source.c == nil {
		return 0, fmt.Errorf("public GC result ownership is outside exact collector execution")
	}
	arrayProduct := source.c.stagedGCArrayProduct()
	admittedArray := arrayProduct == stagedGCArrayProductNumericDefault || arrayProduct == stagedGCArrayProductNumericFixed || arrayProduct == stagedGCArrayProductPackedData || arrayProduct == stagedGCArrayProductReferenceElements || arrayProduct == stagedGCArrayProductNewData || arrayProduct == stagedGCArrayProductNewElem || rv64GCArrayFixedOfficial(source.c) || rv64GCArrayDefaultOfficial(source.c) || rv64GCArrayPackedData(source.c) || rv64GCArrayReference(source.c)
	legacyStruct := source.c.stagedGCStructProduct() == stagedGCStructBasic || rv64GCStructBasic(source.c)
	generic := source.c.needsExactNativeGCRoots() && source.c.genericGCFrameRoots() != nil
	if !legacyStruct && !admittedArray && !generic {
		return 0, fmt.Errorf("public GC result ownership is outside exact collector execution")
	}
	ownerIndex := state.nextResultSlot()
	if source.gc == nil {
		return 0, fmt.Errorf("public GC result has no live collector")
	}
	typeID, err := source.gc.ObjectType(ref)
	if err != nil {
		return 0, fmt.Errorf("public GC result object %#x: %w", uint32(ref), err)
	}
	localType, ok := source.gcLocalType(typeID)
	exact, ownedException := ownedExceptionExactValueType(source.gc, ref, typeID)
	if !ownedException {
		if !ok || int(localType) >= len(source.c.Types) {
			return 0, fmt.Errorf("public GC result canonical type %d has no producer-local identity", typeID)
		}
		kind := source.c.Types[localType].Kind
		if legacyStruct && kind != CompositeTypeStruct {
			return 0, fmt.Errorf("public GC result type %d is not a struct", typeID)
		}
		if admittedArray && !generic && kind != CompositeTypeArray {
			return 0, fmt.Errorf("public GC result type %d is not an array", typeID)
		}
		if generic && kind != CompositeTypeStruct && kind != CompositeTypeArray {
			return 0, fmt.Errorf("public GC result type %d is not a struct or array", typeID)
		}
		exact = ValueTypeDescriptor{Kind: ValueTypeReference, Ref: ReferenceTypeDescriptor{Exact: true, Heap: HeapTypeDescriptor{Defined: true, TypeIndex: localType}}}
	}
	if required.Kind != ValueTypeReference || !source.gcRefMatchesValueType(ref, required) {
		return 0, fmt.Errorf("public GC result type %d does not match its exact structural result type", localType)
	}

	s.mu.Lock()
	_, registered := s.instances[source]
	s.mu.Unlock()
	if !registered || !source.retainResourceRootMode(retained) {
		return 0, fmt.Errorf("public GC result producer is closed")
	}
	rollbackRoot := true
	defer func() {
		if rollbackRoot {
			source.releaseResourceRoot()
		}
	}()

	var slot uint32
	if ownerIndex == state.resultRootsMade {
		var slotErr error
		slot, slotErr = source.gc.NewCheckedClassifiedGlobalSlot(ref, gc.RootPublicToken)
		if slotErr != nil {
			return 0, fmt.Errorf("root public GC result: %w", slotErr)
		}
		state.appendResultRootSlot(slot)
	} else {
		slot = state.resultRootSlot(ownerIndex)
		if err := source.gc.SetGlobalSlot(slot, ref); err != nil {
			return 0, fmt.Errorf("root public GC result: %w", err)
		}
	}

	s.mu.Lock()
	if _, registered = s.instances[source]; !registered {
		s.mu.Unlock()
		_ = source.gc.SetGlobalSlot(slot, gc.Null())
		return 0, fmt.Errorf("public GC result producer is closed")
	}
	token, err := s.newTokenLocked()
	if err == nil {
		if s.gcByToken == nil {
			s.gcByToken = make(map[uint64]gcRefTokenEntry)
		}
		s.gcByToken[token] = gcRefTokenEntry{token: token, ref: ref, slot: slot, ownerIndex: ownerIndex, exact: exact, domainType: typeID, owner: source}
		state.setResultToken(ownerIndex, token)
		state.resultTokenCount++
	}
	s.mu.Unlock()
	if err != nil {
		_ = source.gc.SetGlobalSlot(slot, gc.Null())
		return 0, err
	}
	rollbackRoot = false
	return token, nil
}

func (s *referenceStore) releaseGCRef(source *Instance, token uint64) error {
	if token == 0 {
		return nil
	}
	s.mu.Lock()
	entry, ok := s.gcByToken[token]
	s.mu.Unlock()
	if !ok {
		return fmt.Errorf("invalid or stale GC reference token")
	}
	if source == nil || entry.owner != source {
		return fmt.Errorf("GC reference token belongs to a different producer or store")
	}
	state := source.existingPublicGCState()
	if state == nil {
		return fmt.Errorf("GC reference token owner state is unavailable")
	}
	unlockNative := lockNativeExecutionForHostAccess()
	lockedDomain := source.lockGCCollector()
	state.mu.Lock()
	s.mu.Lock()
	entry, ok = s.gcByToken[token]
	ownerIndex := entry.ownerIndex
	if !ok || entry.owner != source || state.resultTokenCount == 0 || ownerIndex >= state.resultRootsMade || state.resultToken(ownerIndex) != token || state.resultRootSlot(ownerIndex) != entry.slot {
		s.mu.Unlock()
		state.mu.Unlock()
		unlockGCCollector(lockedDomain)
		unlockNative()
		return fmt.Errorf("invalid or stale GC reference token")
	}
	if source.gc == nil {
		s.mu.Unlock()
		state.mu.Unlock()
		unlockGCCollector(lockedDomain)
		unlockNative()
		return fmt.Errorf("GC reference token collector is unavailable")
	}
	if err := source.gc.SetGlobalSlot(entry.slot, gc.Null()); err != nil {
		s.mu.Unlock()
		state.mu.Unlock()
		unlockGCCollector(lockedDomain)
		unlockNative()
		return fmt.Errorf("release GC reference token: %w", err)
	}
	delete(s.gcByToken, token)
	state.setResultToken(ownerIndex, 0)
	state.resultTokenCount--
	s.mu.Unlock()
	state.mu.Unlock()
	unlockGCCollector(lockedDomain)
	unlockNative()
	source.releaseResourceRoot()
	var release referenceTokenEntries
	topology := s.lockGCDomainTopology()
	s.mu.Lock()
	if s.canReleaseEntriesLocked() {
		release = s.releaseEntriesLocked()
	}
	s.mu.Unlock()
	if topology != nil {
		topology.Unlock()
	}
	releaseReferenceEntries(release)
	return nil
}

func (s *referenceStore) gcRefExactType(token uint64) (ValueTypeDescriptor, *Instance, uint32, bool) {
	s.mu.Lock()
	entry, ok := s.gcByToken[token]
	s.mu.Unlock()
	if !ok {
		return ValueTypeDescriptor{}, nil, 0, false
	}
	return entry.exact, entry.owner, entry.slot, true
}

func lockGCPublicStates(a, b *gcPublicState) (first, second *gcPublicState) {
	if a == b {
		a.mu.Lock()
		return a, nil
	}
	first, second = a, b
	if uintptr(unsafe.Pointer(first)) > uintptr(unsafe.Pointer(second)) {
		first, second = second, first
	}
	first.mu.Lock()
	second.mu.Lock()
	return first, second
}

func unlockGCPublicStates(first, second *gcPublicState) {
	if second != nil {
		second.mu.Unlock()
	}
	first.mu.Unlock()
}

func (s *referenceStore) stageGCRefArgument(target *Instance, token uint64, required ValueTypeDescriptor) (gc.Ref, error) {
	if s == nil || target == nil || target.gc == nil || target.c == nil || token == 0 {
		return gc.Null(), fmt.Errorf("invalid GC reference token")
	}
	unlockNative := lockNativeExecutionForHostAccess()
	defer unlockNative()
	lockedDomain := target.lockGCCollector()
	defer unlockGCCollector(lockedDomain)
	s.mu.Lock()
	entry, ok := s.gcByToken[token]
	s.mu.Unlock()
	if !ok || entry.owner == nil {
		return gc.Null(), fmt.Errorf("invalid or stale GC reference token")
	}
	owner := entry.owner
	ownerState := owner.existingPublicGCState()
	if ownerState == nil {
		return gc.Null(), fmt.Errorf("GC reference token owner state is unavailable")
	}
	targetState := target.publicGCState()
	firstState, secondState := lockGCPublicStates(ownerState, targetState)
	defer unlockGCPublicStates(firstState, secondState)

	s.mu.Lock()
	current, ok := s.gcByToken[token]
	ownerRecord := s.instances[owner]
	targetRecord := s.instances[target]
	s.mu.Unlock()
	ownerIndex := current.ownerIndex
	if !ok || current.owner != owner || current.ref != entry.ref || current.slot != entry.slot || ownerIndex >= ownerState.resultRootsMade || ownerState.resultToken(ownerIndex) != token || ownerState.resultRootSlot(ownerIndex) != entry.slot {
		return gc.Null(), fmt.Errorf("invalid or stale GC reference token")
	}
	if ownerRecord == nil || ownerRecord.resourcesReleased || targetRecord == nil || targetRecord.resourcesReleased || owner.refStore != s || target.refStore != s || owner.gc == nil || owner.gc != target.gc {
		return gc.Null(), fmt.Errorf("GC reference token belongs to a different collector domain")
	}
	if required.Kind != ValueTypeReference || !target.gcRefMatchesValueType(current.ref, required) {
		return gc.Null(), fmt.Errorf("GC reference token does not match the required structural argument type")
	}
	rootIndex := targetState.argumentRootCount
	if rootIndex == targetState.argumentRootsMade {
		slot, err := target.gc.NewCheckedClassifiedGlobalSlot(current.ref, gc.RootForeignInstance)
		if err != nil {
			return gc.Null(), fmt.Errorf("root GC reference argument: %w", err)
		}
		targetState.appendArgumentRootSlot(slot)
	} else if err := target.gc.SetGlobalSlot(targetState.argumentRootSlot(rootIndex), current.ref); err != nil {
		return gc.Null(), fmt.Errorf("root GC reference argument: %w", err)
	}
	targetState.argumentRootCount++
	return current.ref, nil
}

// publishGCRefGlobal authenticates one public token and installs its compact
// reference into an existing checked global-root slot. The caller holds native
// execution, which prevents token retirement between authentication and the
// subsequent native-cell write.
func (s *referenceStore) publishGCRefGlobal(target *Instance, token uint64, required ValueTypeDescriptor, slot uint32) (gc.Ref, error) {
	if s == nil || target == nil || target.gc == nil || target.c == nil || token == 0 {
		return gc.Null(), fmt.Errorf("invalid GC reference token")
	}
	lockedDomain := target.lockGCCollector()
	defer unlockGCCollector(lockedDomain)
	s.mu.Lock()
	entry, ok := s.gcByToken[token]
	s.mu.Unlock()
	if !ok || entry.owner == nil {
		return gc.Null(), fmt.Errorf("invalid or stale GC reference token")
	}
	owner := entry.owner
	ownerState := owner.existingPublicGCState()
	if ownerState == nil {
		return gc.Null(), fmt.Errorf("GC reference token owner state is unavailable")
	}
	targetState := target.publicGCState()
	firstState, secondState := lockGCPublicStates(ownerState, targetState)
	defer unlockGCPublicStates(firstState, secondState)

	s.mu.Lock()
	current, ok := s.gcByToken[token]
	ownerRecord := s.instances[owner]
	targetRecord := s.instances[target]
	s.mu.Unlock()
	ownerIndex := current.ownerIndex
	if !ok || current.owner != owner || current.ref != entry.ref || current.slot != entry.slot || ownerIndex >= ownerState.resultRootsMade || ownerState.resultToken(ownerIndex) != token || ownerState.resultRootSlot(ownerIndex) != entry.slot {
		return gc.Null(), fmt.Errorf("invalid or stale GC reference token")
	}
	if ownerRecord == nil || ownerRecord.resourcesReleased || targetRecord == nil || targetRecord.resourcesReleased || owner.refStore != s || target.refStore != s || owner.gc == nil || owner.gc != target.gc {
		return gc.Null(), fmt.Errorf("GC reference token belongs to a different collector domain")
	}
	if required.Kind != ValueTypeReference || !target.gcRefMatchesValueType(current.ref, required) {
		return gc.Null(), fmt.Errorf("GC reference token does not match the required structural global type")
	}
	if err := target.gc.SetGlobalSlot(slot, current.ref); err != nil {
		return gc.Null(), fmt.Errorf("root GC reference global: %w", err)
	}
	return current.ref, nil
}

func (in *Instance) rootGCHostArguments(token gcHostActivationToken, dispatch uint32, args []uint64) error {
	state := token.state
	if in == nil || state == nil || in.gc == nil || in.refStore == nil {
		return nil
	}
	var types []ValType
	if dispatch&hostFuncRefDispatchBit != 0 {
		binding, ok := in.boundHostFuncRef(dispatch)
		if !ok {
			return fmt.Errorf("GC host argument owner is unavailable")
		}
		owner := binding.owner
		owner.mu.Lock()
		if !owner.gcCapable || owner.gc == nil || owner.closed || owner.gc.collector != in.gc || owner.gc.domainID == 0 {
			owner.mu.Unlock()
			return fmt.Errorf("GC host argument owner is outside the active collector domain")
		}
		owner.mu.Unlock()
		types = binding.sig.Params
	} else {
		pluginSig, ok := in.pluginGCHostSignature(dispatch)
		if !ok {
			return nil
		}
		if !in.refStore.ownsGCCollector(in.gc) {
			return fmt.Errorf("Runtime plugin GC host import is outside the calling instance's Runtime collector domain")
		}
		types = pluginSig.Params
	}

	lockedDomain := in.lockGCCollector()
	defer unlockGCCollector(lockedDomain)
	state.mu.Lock()
	defer state.mu.Unlock()
	slot := 0
	for i, typ := range types {
		if typ == ValV128 {
			slot += 2
			continue
		}
		if slot >= len(args) {
			return fmt.Errorf("missing GC host argument slot %d", slot)
		}
		if typ == ValAnyRef || typ == ValI31Ref {
			bits := args[slot]
			ref := gc.Ref(uint32(bits))
			if bits != 0 && (uint64(ref) != bits || (!ref.IsObj() && !ref.IsI31())) {
				return fmt.Errorf("invalid compact GC host argument %d", i)
			}
			if ref.IsObj() {
				index := token.index
				count := state.hostArgumentRootCount[index]
				if int(count) >= len(state.hostArgumentRootSlots[index]) {
					return fmt.Errorf("GC host object argument count exceeds %d", len(state.hostArgumentRootSlots[index]))
				}
				if count == state.hostArgumentRootsMade[index] {
					root, err := in.gc.NewCheckedClassifiedGlobalSlot(ref, gc.RootPublicToken)
					if err != nil {
						return fmt.Errorf("root GC host argument %d: %w", i, err)
					}
					state.hostArgumentRootSlots[index][count] = root
					state.hostArgumentRootsMade[index]++
				} else if err := in.gc.SetGlobalSlot(state.hostArgumentRootSlots[index][count], ref); err != nil {
					return fmt.Errorf("root GC host argument %d: %w", i, err)
				}
				state.hostArgumentRootCount[index]++
			}
		}
		slot++
	}
	return nil
}

func (s *referenceStore) stageGCHostResult(target *Instance, parked gcHostActivationToken, token uint64, required ValueTypeDescriptor) (gc.Ref, error) {
	if s == nil || target == nil || target.gc == nil || target.c == nil || parked.state == nil || token == 0 {
		return gc.Null(), fmt.Errorf("invalid GC host result token")
	}
	unlockNative := lockNativeExecutionForHostAccess()
	defer unlockNative()
	lockedDomain := target.lockGCCollector()
	defer unlockGCCollector(lockedDomain)
	s.mu.Lock()
	entry, ok := s.gcByToken[token]
	s.mu.Unlock()
	if !ok || entry.owner == nil {
		return gc.Null(), fmt.Errorf("invalid or stale GC host result token")
	}
	owner := entry.owner
	ownerState := owner.existingPublicGCState()
	if ownerState == nil {
		return gc.Null(), fmt.Errorf("GC host result token owner state is unavailable")
	}
	targetState := target.publicGCState()
	firstState, secondState := lockGCPublicStates(ownerState, targetState)
	defer unlockGCPublicStates(firstState, secondState)

	s.mu.Lock()
	current, ok := s.gcByToken[token]
	ownerRecord := s.instances[owner]
	targetRecord := s.instances[target]
	s.mu.Unlock()
	ownerIndex := current.ownerIndex
	if !ok || current.owner != owner || current.ref != entry.ref || current.slot != entry.slot || ownerIndex >= ownerState.resultRootsMade || ownerState.resultToken(ownerIndex) != token || ownerState.resultRootSlot(ownerIndex) != entry.slot {
		return gc.Null(), fmt.Errorf("invalid or stale GC host result token")
	}
	if ownerRecord == nil || ownerRecord.resourcesReleased || targetRecord == nil || targetRecord.resourcesReleased || owner.refStore != s || target.refStore != s || owner.gc == nil || owner.gc != target.gc {
		return gc.Null(), fmt.Errorf("GC host result token belongs to a different collector domain")
	}
	if required.Kind != ValueTypeReference || !target.gcRefMatchesValueType(current.ref, required) {
		return gc.Null(), fmt.Errorf("GC host result token does not match the required structural result type")
	}
	// Multiple public roots can park on the same producer control frame. The
	// dispatch token identifies this callback's exact slot, including holes
	// reused after another root resumes out of suspension order.
	activation := parked.index
	if parked.state != targetState || activation >= targetState.hostActivationCount || targetState.hostActivations[activation].stack == nil {
		return gc.Null(), fmt.Errorf("GC host result has no active parked frame")
	}
	count := targetState.hostResultRootCount[activation]
	if int(count) >= len(targetState.hostResultRootSlots[activation]) {
		return gc.Null(), fmt.Errorf("GC host result count exceeds %d", len(targetState.hostResultRootSlots[activation]))
	}
	if count == targetState.hostResultRootsMade[activation] {
		slot, err := target.gc.NewCheckedClassifiedGlobalSlot(current.ref, gc.RootForeignInstance)
		if err != nil {
			return gc.Null(), fmt.Errorf("root GC host result: %w", err)
		}
		targetState.hostResultRootSlots[activation][count] = slot
		targetState.hostResultRootsMade[activation]++
	} else if err := target.gc.SetGlobalSlot(targetState.hostResultRootSlots[activation][count], current.ref); err != nil {
		return gc.Null(), fmt.Errorf("root GC host result: %w", err)
	}
	targetState.hostResultRootCount[activation]++
	return current.ref, nil
}

func (in *Instance) clearGCHostResultRoots(token gcHostActivationToken) {
	state := token.state
	if in == nil || state == nil || in.gc == nil || int(token.index) >= len(state.hostResultRootSlots) {
		return
	}
	lockedDomain := in.lockGCCollector()
	defer unlockGCCollector(lockedDomain)
	state.mu.Lock()
	defer state.mu.Unlock()
	argumentCount := state.hostArgumentRootCount[token.index]
	for i := uint8(0); i < argumentCount; i++ {
		if err := in.gc.SetGlobalSlot(state.hostArgumentRootSlots[token.index][i], gc.Null()); err != nil {
			panic(gcHelperFailuref("clear GC host argument root %d: %w", i, err))
		}
	}
	state.hostArgumentRootCount[token.index] = 0
	resultCount := state.hostResultRootCount[token.index]
	for i := uint8(0); i < resultCount; i++ {
		if err := in.gc.SetGlobalSlot(state.hostResultRootSlots[token.index][i], gc.Null()); err != nil {
			panic(gcHelperFailuref("clear GC host result root %d: %w", i, err))
		}
	}
	state.hostResultRootCount[token.index] = 0
}

func (in *Instance) clearGCRefArgumentRoots() {
	state := in.existingPublicGCState()
	if state == nil || in.gc == nil {
		return
	}
	unlockNative := lockNativeExecutionForHostAccess()
	defer unlockNative()
	lockedDomain := in.lockGCCollector()
	defer unlockGCCollector(lockedDomain)
	state.mu.Lock()
	defer state.mu.Unlock()
	for i := uint32(0); i < state.argumentRootCount; i++ {
		if err := in.gc.SetGlobalSlot(state.argumentRootSlot(i), gc.Null()); err != nil {
			panic(gcHelperFailuref("clear GC reference argument root %d: %w", i, err))
		}
	}
	state.argumentRootCount = 0
}

// ReleaseGCRef releases one non-null GC result token issued by this producer.
// It is valid after Instance.Close while the token retains the producer's
// collector; null releases are no-ops. Non-null releases fail with
// ErrPermissionDenied while callback-scoped guest storage is borrowed. Stale,
// foreign-store, and cross-producer tokens reject without changing either owner.
func (in *Instance) ReleaseGCRef(ref GCRef) error {
	if ref.token == 0 {
		return nil
	}
	if in == nil {
		return fmt.Errorf("release GC reference token on nil instance")
	}
	if in.guestStorageBorrowed() {
		return fmt.Errorf("release GC reference token is unavailable while guest storage is borrowed: %w", ErrPermissionDenied)
	}
	in.lifeMu.Lock()
	store := in.refStore
	in.lifeMu.Unlock()
	if store == nil {
		return fmt.Errorf("instance has no GC reference token store")
	}
	defer drainManagedFunctionStoreReclaims(store)
	return store.releaseGCRef(in, ref.token)
}

// ReleaseExnRef releases an owned exception token issued by this instance.
// It has the same lifetime and ownership checks as ReleaseGCRef.
func (in *Instance) ReleaseExnRef(ref ExnRef) error {
	return in.ReleaseGCRef(GCRef{token: ref.token})
}

func (s *referenceStore) resolveFuncrefTokenOwner(token uint64) (uint64, *Instance, bool) {
	if token == 0 {
		return 0, nil, true
	}
	s.mu.Lock()
	entry := s.byToken[token]
	s.mu.Unlock()
	if entry == nil || entry.owner == nil || !entry.owner.retainResourceRootForFinalization() {
		return 0, nil, false
	}
	return entry.descriptor, entry.owner, true
}

func (s *referenceStore) resolve(token uint64) (uint64, bool) {
	if token == 0 {
		return 0, true
	}
	s.mu.Lock()
	entry := s.byToken[token]
	s.mu.Unlock()
	if entry == nil {
		return 0, false
	}
	return entry.descriptor, true
}

func (s *referenceStore) tokenFuncrefExactType(token uint64) (ValueTypeDescriptor, []DefinedTypeDescriptor, bool) {
	if token == 0 {
		return ValueTypeDescriptor{}, nil, false
	}
	s.mu.Lock()
	entry := s.byToken[token]
	var owner *Instance
	var descriptor uint64
	if entry != nil {
		owner, descriptor = entry.owner, entry.descriptor
	}
	s.mu.Unlock()
	return instanceFuncrefExactType(owner, descriptor)
}

func (s *referenceStore) descriptorFuncrefExactType(source *Instance, descriptor uint64) (ValueTypeDescriptor, []DefinedTypeDescriptor, bool) {
	if source == nil || descriptor == 0 {
		return ValueTypeDescriptor{}, nil, false
	}
	s.mu.Lock()
	var owner *Instance
	canonical := descriptor
	ok := false
	if entry := s.byIdentity[funcrefIdentity{descriptor: descriptor}]; entry != nil {
		owner, canonical, ok = entry.owner, entry.descriptor, true
	} else {
		owner, canonical, ok = s.canonicalFuncrefOwnerLocked(source, descriptor)
	}
	s.mu.Unlock()
	if !ok {
		return ValueTypeDescriptor{}, nil, false
	}
	return instanceFuncrefExactType(owner, canonical)
}

func instanceFuncrefExactType(owner *Instance, descriptor uint64) (ValueTypeDescriptor, []DefinedTypeDescriptor, bool) {
	if owner == nil || owner.c == nil || descriptor == 0 {
		return ValueTypeDescriptor{}, nil, false
	}
	index, ok := owner.funcrefDescriptorIndex(descriptor)
	if !ok {
		return ValueTypeDescriptor{}, nil, false
	}
	return owner.attachedFunctionIndexExactType(index)
}

// attachedFuncrefExactType resolves function identities that are physically
// reachable from this instance without requiring a public reference store.
// This covers local descriptors and direct function imports, including imports
// whose refSlot points at a provider-owned canonical descriptor.
func (in *Instance) attachedFuncrefExactType(descriptor uint64) (ValueTypeDescriptor, []DefinedTypeDescriptor, bool) {
	if in == nil || in.c == nil || descriptor == 0 {
		return ValueTypeDescriptor{}, nil, false
	}
	if index, ok := in.funcrefDescriptorIndex(descriptor); ok {
		return in.attachedFunctionIndexExactType(index)
	}
	for index := 0; index < in.c.NumImports && index < len(in.c.Imports); index++ {
		off := (index + 1) * coreruntime.FuncRefDescBytes
		if off+coreruntime.FuncRefDescBytes > len(in.funcRefDescs) || binary.LittleEndian.Uint64(in.funcRefDescs[off+coreruntime.TableEntryRefSlotOffset:]) != descriptor {
			continue
		}
		return in.attachedFunctionIndexExactType(index)
	}
	return ValueTypeDescriptor{}, nil, false
}

func (in *Instance) attachedFunctionIndexExactType(index int) (ValueTypeDescriptor, []DefinedTypeDescriptor, bool) {
	if index < 0 || index >= len(in.c.FuncTypeID) {
		return ValueTypeDescriptor{}, nil, false
	}
	if index >= in.c.NumImports {
		exact, err := in.c.functionRefExactType(uint32(index))
		return exact, in.c.Types, err == nil
	}
	if index >= len(in.c.Imports) {
		return ValueTypeDescriptor{}, nil, false
	}
	var export *InstanceExport
	if railshotNativeContextTrapABI() {
		entries := in.importReferenceEntries()
		if index < len(entries) {
			export = entries[index].native
		}
	} else {
		export, _ = in.imports[in.c.functionImportBindingKey(index)].(*InstanceExport)
	}
	if export != nil && export.inst != nil && export.inst.c != nil && export.localIdx >= 0 {
		providerIndex := export.inst.c.NumImports + export.localIdx
		exact, err := export.inst.c.functionRefExactType(uint32(providerIndex))
		return exact, export.inst.c.Types, err == nil
	}
	exact, err := in.c.functionRefExactType(uint32(index))
	return exact, in.c.Types, err == nil
}

func (s *referenceStore) issueExternref(value any) (uint64, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.runtimeClosed && !s.private {
		return 0, fmt.Errorf("wago: reference store is closed")
	}
	if s.externFree == 0 && uint64(len(s.externrefs)) >= uint64(^uint32(0)) {
		return 0, fmt.Errorf("wago: externref store is full")
	}
	if s.externKey == 0 {
		key, err := randomNonzeroUint64()
		if err != nil {
			return 0, fmt.Errorf("create externref store key: %w", err)
		}
		s.externKey = key
		s.externSeed = uint32(key>>32) | 1
	}
	var index uint32
	if s.externFree != 0 {
		index = s.externFree
		slot := &s.externrefs[index-1]
		s.externFree = slot.nextFree
		slot.nextFree = 0
		slot.value = value
	} else {
		index = uint32(len(s.externrefs)) + 1
		generation := s.externSeed + index - 1
		if generation == 0 {
			generation = 1
		}
		s.externrefs = append(s.externrefs, externrefSlot{value: value, generation: generation})
	}
	slot := &s.externrefs[index-1]
	for {
		raw := uint64(slot.generation)<<32 | uint64(index)
		token := bits.RotateLeft64(raw^s.externKey, 17)
		if token != 0 && !compactExternWordReserved(s, token) {
			return token, nil
		}
		slot.generation = nextExternrefGeneration(slot.generation)
	}
}

type releasedExternrefMarker struct{ reserved byte }

var releasedExternrefValue = &releasedExternrefMarker{}

func (s *referenceStore) releaseExternref(token uint64) bool {
	if token == 0 {
		return true
	}
	s.mu.Lock()
	var root gcRefTokenEntry
	var direct directRootedExternrefValue
	defer func() {
		s.mu.Unlock()
		if direct != nil {
			direct.releaseExternrefRoot()
		} else if root.owner != nil {
			releaseRootedExternref(root)
		}
	}()
	if s.externKey == 0 {
		return false
	}
	raw := bits.RotateLeft64(token, -17) ^ s.externKey
	index, generation := uint32(raw), uint32(raw>>32)
	if index == 0 || uint64(index) > uint64(len(s.externrefs)) {
		return false
	}
	slot := &s.externrefs[index-1]
	if slot.generation != generation || slot.value == releasedExternrefValue || slot.nextFree != 0 {
		return false
	}
	if value, ok := slot.value.(directRootedExternrefValue); ok {
		direct = value
	} else if value, ok := slot.value.(rootedExternrefValue); ok {
		root = value.externrefGCRoot()
	}
	slot.value = releasedExternrefValue
	slot.generation = nextExternrefGeneration(slot.generation)
	slot.nextFree = s.externFree
	s.externFree = index
	return true
}

// pinExternref closes the validation-to-execution window for a public
// argument. Release fails while any invocation owns a pin, so the slot cannot
// be recycled under native code carrying the authenticated token.
func (s *referenceStore) pinExternref(token uint64) bool {
	if token == 0 {
		return true
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.externKey == 0 {
		return false
	}
	raw := bits.RotateLeft64(token, -17) ^ s.externKey
	index, generation := uint32(raw), uint32(raw>>32)
	if index == 0 || uint64(index) > uint64(len(s.externrefs)) {
		return false
	}
	slot := &s.externrefs[index-1]
	if slot.generation != generation || slot.value == releasedExternrefValue || slot.nextFree >= externrefInternalSlot-1 {
		return false
	}
	slot.nextFree++
	return true
}

func (s *referenceStore) unpinExternref(token uint64) bool {
	if token == 0 {
		return true
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.externKey == 0 {
		return false
	}
	raw := bits.RotateLeft64(token, -17) ^ s.externKey
	index, generation := uint32(raw), uint32(raw>>32)
	if index == 0 || uint64(index) > uint64(len(s.externrefs)) {
		return false
	}
	slot := &s.externrefs[index-1]
	if slot.generation != generation || slot.value == releasedExternrefValue || slot.nextFree == 0 || slot.nextFree == externrefInternalSlot {
		return false
	}
	slot.nextFree--
	if s.runtimeClosed && slot.nextFree == 0 {
		railshotCompactExternUnpinnedAfterClose(s)
	}
	return true
}

func (s *referenceStore) resolveExternref(token uint64) (any, bool) {
	if token == 0 {
		return nil, true
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.externKey == 0 {
		return nil, false
	}
	raw := bits.RotateLeft64(token, -17) ^ s.externKey
	index := uint32(raw)
	generation := uint32(raw >> 32)
	if index == 0 || uint64(index) > uint64(len(s.externrefs)) {
		return nil, false
	}
	slot := &s.externrefs[index-1]
	if slot.generation != generation {
		return nil, false
	}
	if value, ok := slot.value.(interface{ externrefPublicValue() any }); ok {
		return value.externrefPublicValue(), true
	}
	return slot.value, true
}

func (s *referenceStore) newTokenLocked() (uint64, error) {
	for {
		token, err := randomNonzeroUint64()
		if err != nil {
			return 0, fmt.Errorf("create reference token: %w", err)
		}
		_, gcExists := s.gcByToken[token]
		if token>>32 != 0 && s.byToken[token] == nil && !gcExists && !compactExternWordReserved(s, token) {
			return token, nil
		}
	}
}

func randomNonzeroUint64() (uint64, error) {
	var buf [8]byte
	for {
		if _, err := rand.Read(buf[:]); err != nil {
			return 0, err
		}
		if token := binary.LittleEndian.Uint64(buf[:]); token != 0 {
			return token, nil
		}
	}
}

type referenceTokenEntries struct {
	directExternrefs []directRootedExternrefValue
	funcrefs         []*funcrefTokenEntry
	gcRefs           []gcRefTokenEntry
	collectors       []*gc.Collector
}

func (s *referenceStore) releaseEntriesLocked() referenceTokenEntries {
	retireGCConversionStoreLocked(s)
	var entries referenceTokenEntries
	if len(s.byToken) != 0 {
		entries.funcrefs = make([]*funcrefTokenEntry, 0, len(s.byToken))
		for _, entry := range s.byToken {
			entries.funcrefs = append(entries.funcrefs, entry)
		}
	}
	if len(s.gcByToken) != 0 {
		entries.gcRefs = make([]gcRefTokenEntry, 0, len(s.gcByToken))
		for _, entry := range s.gcByToken {
			entries.gcRefs = append(entries.gcRefs, entry)
		}
	}
	s.byIdentity = nil
	s.byToken = nil
	s.gcByToken = nil
	for _, slot := range s.externrefs {
		if value, ok := slot.value.(directRootedExternrefValue); ok {
			entries.directExternrefs = append(entries.directExternrefs, value)
		} else if value, ok := slot.value.(rootedExternrefValue); ok {
			entries.gcRefs = append(entries.gcRefs, value.externrefGCRoot())
		}
	}
	clear(s.externrefs)
	s.externrefs = nil
	s.externKey = 0
	s.externSeed = 0
	s.externFree = 0
	if topology := s.gcDomains; topology != nil {
		for domain := topology.first; domain != nil; domain = domain.next {
			entries.collectors = append(entries.collectors, domain.collector)
		}
		topology.first = nil
		topology.last = nil
		topology.n = 0
		topology.byCollector = nil
		topology.codeRanges = nil
		topology.singleCodeOwner = nil
		// Table attachments can outlive logical closure and token/GC retirement.
		// Their physical owners consume these exact counts at final detach.
	}
	return entries
}

// releaseLifetimeEntries receives already-claimed cleanup units after the
// store and topology locks have been dropped. A collector callback panic must
// not strand the separate token batch removed from the store maps.
func releaseLifetimeEntries(collector *gc.Collector, entries referenceTokenEntries) {
	releaseLifetimeEntriesWith(collector, entries, (*gc.Collector).Close)
}

func releaseLifetimeEntriesWith(collector *gc.Collector, entries referenceTokenEntries, closeCollector func(*gc.Collector)) {
	var cleanup resourceCleanup
	if collector != nil {
		cleanup.run(func() { closeCollector(collector) })
	}
	cleanup.run(func() {
		releaseReferenceEntriesWith(entries, releaseFuncrefTokenMetadata, releaseGCRefTokenMetadata, closeCollector)
	})
	cleanup.finish()
}

func releaseReferenceEntries(entries referenceTokenEntries) {
	releaseReferenceEntriesWith(entries, releaseFuncrefTokenMetadata, releaseGCRefTokenMetadata, (*gc.Collector).Close)
}

// The caller has removed these exact token units from its maps. Distinct tokens
// may own separate roots on the same Instance: never deduplicate by owner. The
// per-call operations expose only metadata/collector phases for failure-ordering
// tests; the actual root decrement remains mandatory and noninjectable.
func releaseReferenceEntriesWith(entries referenceTokenEntries, notifyFuncref func(*funcrefTokenEntry), clearGC func(gcRefTokenEntry), closeCollector func(*gc.Collector)) {
	var cleanup resourceCleanup
	for i, entry := range entries.funcrefs {
		entries.funcrefs[i] = nil
		owner := entry.owner
		cleanup.run(func() { notifyFuncref(entry) })
		cleanup.run(owner.releaseResourceRoot)
	}
	for i, entry := range entries.gcRefs {
		entries.gcRefs[i] = gcRefTokenEntry{}
		owner := entry.owner
		cleanup.run(func() { clearGC(entry) })
		cleanup.run(owner.releaseResourceRoot)
	}
	for i, value := range entries.directExternrefs {
		entries.directExternrefs[i] = nil
		cleanup.run(value.releaseExternrefRoot)
	}
	for i, collector := range entries.collectors {
		entries.collectors[i] = nil
		cleanup.run(func() { closeCollector(collector) })
	}
	cleanup.finish()
}

func releaseFuncrefTokenMetadata(entry *funcrefTokenEntry) {
	if hostOwner := entry.owner.hostFuncRefForDescriptor(entry.descriptor); hostOwner != nil {
		hostOwner.tokenReleased(entry.owner, entry.descriptor)
	}
}

func releaseGCRefTokenMetadata(entry gcRefTokenEntry) {
	releaseGCRefTokenMetadataWith(entry, clearGCRefTokenSlot)
}

func clearGCRefTokenSlot(owner *Instance, slot uint32) error {
	if owner.gc != nil {
		return owner.gc.SetGlobalSlot(slot, gc.Null())
	}
	return nil
}

func releaseGCRefTokenMetadataWith(entry gcRefTokenEntry, clearSlot func(*Instance, uint32) error) {
	state := entry.owner.existingPublicGCState()
	if state == nil {
		return
	}
	state.mu.Lock()
	defer state.mu.Unlock()
	ownerIndex := entry.ownerIndex
	if ownerIndex < state.resultRootsMade && state.resultToken(ownerIndex) == entry.token && state.resultRootSlot(ownerIndex) == entry.slot {
		_ = clearSlot(entry.owner, entry.slot)
		state.setResultToken(ownerIndex, 0)
		if state.resultTokenCount != 0 {
			state.resultTokenCount--
		}
	}
}

func (s *referenceStore) hasInstanceResourcesLocked(in *Instance) bool {
	entry := s.instances[in]
	return entry != nil && !entry.resourcesReleased
}

// retainDescriptorOwnerForFinalization resolves a live descriptor owner and
// acquires one root while the store still proves its physical resources exist.
func (s *referenceStore) retainDescriptorOwnerForFinalization(descriptor uint64) *Instance {
	if s == nil || descriptor == 0 {
		return nil
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if entry := s.byIdentity[funcrefIdentity{descriptor: descriptor}]; entry != nil {
		if s.hasInstanceResourcesLocked(entry.owner) && entry.owner.retainResourceRootForFinalization() {
			return entry.owner
		}
	}
	for candidate, state := range s.instances {
		if state.resourcesReleased || !candidate.reachesFuncrefDescriptor(descriptor) {
			continue
		}
		owner, canonical, ok := s.canonicalFuncrefOwnerLocked(candidate, descriptor)
		if !ok || canonical != descriptor || !s.hasInstanceResourcesLocked(owner) {
			continue
		}
		if owner.retainResourceRootForFinalization() {
			return owner
		}
	}
	return nil
}

func (s *referenceStore) canonicalFuncrefOwnerLocked(source *Instance, descriptor uint64) (*Instance, uint64, bool) {
	if fidx, ok := source.funcrefDescriptorIndex(descriptor); ok {
		if fidx >= source.c.NumImports {
			if !railshotValidFuncrefPublication(s, source, descriptor) {
				return nil, 0, false
			}
			_, registered := s.instances[source]
			return source, descriptor, registered
		}
		if fidx >= len(source.c.Imports) || fidx >= len(source.c.importFuncSigs) {
			return nil, 0, false
		}
		var binding any
		if railshotNativeContextTrapABI() {
			if native := source.importReferenceNative(fidx); native != nil {
				binding = native
			} else if host := source.importReferenceHost(fidx); host != nil {
				binding = host
			}
		}
		if binding == nil {
			binding = source.imports[source.c.functionImportBindingKey(fidx)]
		}
		off := (fidx + 1) * coreruntime.FuncRefDescBytes
		refSlot := binary.LittleEndian.Uint64(source.funcRefDescs[off+coreruntime.TableEntryRefSlotOffset:])
		if ex, ok := binding.(*InstanceExport); ok {
			if ex == nil || ex.inst == nil || ex.localIdx < 0 || ex.localIdx >= len(ex.inst.c.Entry) {
				return nil, 0, false
			}
			if railshotNativeContextTrapABI() {
				return source, descriptor, railshotCanonicalImportedFuncref(s, source, ex, fidx, descriptor)
			}
			if ex.inst.refStore != s {
				return nil, 0, false
			}
			entry := source.funcRefDescs[off : off+coreruntime.FuncRefDescBytes]
			expectedCode := uint64(ex.inst.base) + uint64(ex.inst.c.Entry[ex.localIdx])
			home := binary.LittleEndian.Uint64(entry[coreruntime.TableEntryHomeLinMemOffset:])
			home &^= abi.FuncRefInternalHomeTag | abi.FuncRefCrossInstanceHomeTag | abi.FuncRefLocalWrapperHomeTag
			if binary.LittleEndian.Uint64(entry[coreruntime.TableEntryCodePtrOffset:]) != expectedCode ||
				home != uint64(ex.inst.jm.LinMemBase()) ||
				binary.LittleEndian.Uint64(entry[coreruntime.TableEntrySigKeyOffset:]) != source.c.funcTypeKey(fidx) ||
				binary.LittleEndian.Uint64(entry[coreruntime.FuncRefContextOffset:]) != uint64(ex.inst.nativeContext) {
				return nil, 0, false
			}
			canonical, hasCanonical := ex.inst.localFuncrefDescriptor(ex.localIdx)
			if !hasCanonical {
				// The producer never needed a descriptor arena itself. The importer's
				// exact proxy becomes the store identity; token retention keeps this
				// importer physically live, and its function attachment retains the
				// producer code/context until the token is released.
				if refSlot != descriptor {
					return nil, 0, false
				}
				_, registered := s.instances[source]
				return source, descriptor, registered
			}
			if refSlot != canonical {
				return nil, 0, false
			}
			if s.byIdentity[funcrefIdentity{descriptor: canonical}] != nil {
				return ex.inst, canonical, true
			}
			_, registered := s.instances[ex.inst]
			return ex.inst, canonical, registered
		}
		hostOwner, ok := binding.(*HostFuncRef)
		if !ok && railshotCanonicalPlainHostFuncref(s, source, fidx, descriptor) {
			return source, descriptor, true
		}
		if !ok || hostOwner == nil || hostOwner.store != s || refSlot != descriptor {
			return nil, 0, false
		}
		if railshotNativeContextTrapABI() {
			return railshotCanonicalHostFuncref(s, source, hostOwner, fidx, descriptor)
		}
		entry := source.funcRefDescs[off : off+coreruntime.TableEntryBytes]
		home := binary.LittleEndian.Uint64(entry[coreruntime.TableEntryHomeLinMemOffset:])
		home &^= abi.FuncRefHomeTagMask
		if binary.LittleEndian.Uint64(entry[coreruntime.TableEntryCodePtrOffset:]) == 0 ||
			home != uint64(source.jm.LinMemBase()) ||
			binary.LittleEndian.Uint64(entry[coreruntime.TableEntrySigKeyOffset:]) != source.c.funcTypeKey(fidx) {
			return nil, 0, false
		}
		return hostOwner.canonicalDescriptor(source, descriptor, source.c.importFuncSigs[fidx])
	}
	if railshotNativeContextTrapABI() {
		return railshotCanonicalGlobalFuncref(s, source, descriptor)
	}
	for candidate := range s.instances {
		if candidate.ownsLocalFuncrefDescriptor(descriptor) {
			return candidate, descriptor, true
		}
	}
	return nil, 0, false
}

func (in *Instance) funcrefDescriptorIndex(descriptor uint64) (int, bool) {
	if len(in.funcRefDescs) < 2*coreruntime.FuncRefDescBytes {
		return 0, false
	}
	base := uint64(uintptr(unsafe.Pointer(&in.funcRefDescs[0])))
	if descriptor < base+coreruntime.FuncRefDescBytes || descriptor >= base+uint64(len(in.funcRefDescs)) {
		return 0, false
	}
	delta := descriptor - base
	if delta%coreruntime.FuncRefDescBytes != 0 {
		return 0, false
	}
	funcIndex := int(delta/coreruntime.FuncRefDescBytes) - 1
	return funcIndex, funcIndex >= 0 && funcIndex < len(in.c.FuncTypeID) && !railshotNonCallableFunction(in.c, funcIndex)
}

func (in *Instance) funcrefFunctionIdentity(descriptor uint64) (funcrefIdentity, bool) {
	fidx, ok := in.funcrefDescriptorIndex(descriptor)
	if !ok {
		return funcrefIdentity{}, false
	}
	if fidx >= in.c.NumImports {
		return funcrefIdentity{instance: in, localIdx: fidx - in.c.NumImports}, true
	}
	if fidx >= len(in.c.Imports) {
		return funcrefIdentity{}, false
	}
	var export *InstanceExport
	if railshotNativeContextTrapABI() {
		export = in.importReferenceNative(fidx)
	} else {
		export, _ = in.imports[in.c.functionImportBindingKey(fidx)].(*InstanceExport)
	}
	if export == nil || export.inst == nil || export.localIdx < 0 {
		return funcrefIdentity{}, false
	}
	return funcrefIdentity{instance: export.inst, localIdx: export.localIdx}, true
}

func (in *Instance) ownsLocalFuncrefDescriptor(descriptor uint64) bool {
	funcIndex, ok := in.funcrefDescriptorIndex(descriptor)
	return ok && funcIndex >= in.c.NumImports
}

// reachesFuncrefDescriptor reports whether descriptor is represented in this
// instance's function-index descriptor space. Imported InstanceExport entries
// may reuse a producer's canonical refSlot, while bare producers and HostFuncRef
// bindings use importer-owned proxy slots. Retaining this instance preserves the
// already-established function/host attachment chain for every form.
func (in *Instance) reachesFuncrefDescriptor(descriptor uint64) bool {
	if in == nil || descriptor == 0 || len(in.funcRefDescs) < 2*coreruntime.FuncRefDescBytes {
		return false
	}
	for fidx := 0; fidx < len(in.c.FuncTypeID); fidx++ {
		off := (fidx + 1) * coreruntime.FuncRefDescBytes
		if off+coreruntime.FuncRefDescBytes > len(in.funcRefDescs) {
			return false
		}
		if binary.LittleEndian.Uint64(in.funcRefDescs[off+coreruntime.TableEntryRefSlotOffset:]) == descriptor {
			return true
		}
	}
	return false
}

func (in *Instance) hostFuncRefForDescriptor(descriptor uint64) *HostFuncRef {
	funcIndex, ok := in.funcrefDescriptorIndex(descriptor)
	if !ok || funcIndex < 0 || funcIndex >= in.c.NumImports || funcIndex >= len(in.c.Imports) {
		return nil
	}
	if railshotNativeContextTrapABI() {
		return in.importReferenceHost(funcIndex)
	}
	owner, _ := in.imports[in.c.functionImportBindingKey(funcIndex)].(*HostFuncRef)
	return owner
}

func (in *Instance) localFuncrefDescriptor(localIdx int) (uint64, bool) {
	fidx := in.c.NumImports + localIdx
	if localIdx < 0 || fidx < in.c.NumImports || fidx >= len(in.c.FuncTypeID) || len(in.funcRefDescs) == 0 || railshotNonCallableFunction(in.c, fidx) {
		return 0, false
	}
	off := (fidx + 1) * coreruntime.FuncRefDescBytes
	if off+coreruntime.FuncRefDescBytes > len(in.funcRefDescs) {
		return 0, false
	}
	return uint64(uintptr(unsafe.Pointer(&in.funcRefDescs[off]))), true
}

func (in *Instance) funcrefStoreForEgress() (*referenceStore, error) {
	return in.referenceStoreForBoundary()
}

// funcrefStoreForAttachedEgress returns the already-established store of a
// producer reached through a live function import attachment. It never creates
// a store after logical close: the attachment may preserve physical resources,
// but it cannot establish a new cross-instance token domain retroactively.
func (in *Instance) funcrefStoreForAttachedEgress() (*referenceStore, error) {
	if in == nil {
		return nil, fmt.Errorf("instance is nil")
	}
	in.lifeMu.Lock()
	defer in.lifeMu.Unlock()
	if in.resourcesClosed {
		return nil, fmt.Errorf("instance resources are closed")
	}
	if in.refStore == nil {
		return nil, fmt.Errorf("attached funcref producer has no compatible reference store")
	}
	return in.refStore, nil
}

// FuncRefMatchesFunction reports whether ref has the canonical identity of the
// function at index in this instance's Wasm function index space. It compares
// canonical function identity rather than opaque public token bits, so imported aliases
// and cross-instance references remain stable across store tokenization.
func (in *Instance) FuncRefMatchesFunction(ref FuncRef, index uint32) bool {
	if in == nil || ref.token == 0 {
		return false
	}
	if railshotNativeContextTrapABI() {
		return railshotFuncRefMatchesFunction(in, ref, index)
	}
	in.lifeMu.Lock()
	defer in.lifeMu.Unlock()
	if in.closed || in.resourcesClosed || in.refStore == nil || int(index) >= len(in.c.FuncTypeID) {
		return false
	}
	descriptor, ok := in.refStore.resolve(ref.token)
	if !ok || descriptor == 0 {
		return false
	}
	actual := unsafe.Slice((*byte)(offHeapPtr(uintptr(descriptor))), coreruntime.TableEntryBytes)
	identity := binary.LittleEndian.Uint64(actual[coreruntime.TableEntryRefSlotOffset:])
	off := (int(index) + 1) * coreruntime.FuncRefDescBytes
	if identity == 0 || off < coreruntime.FuncRefDescBytes || off+coreruntime.FuncRefDescBytes > len(in.funcRefDescs) {
		return false
	}
	expected := binary.LittleEndian.Uint64(in.funcRefDescs[off+coreruntime.TableEntryRefSlotOffset:])
	return expected != 0 && identity == expected
}

func (in *Instance) referenceStoreForBoundary() (*referenceStore, error) {
	in.revokePrivateGCEntry()
	in.lifeMu.Lock()
	defer in.lifeMu.Unlock()
	if in.closed {
		return nil, fmt.Errorf("instance is closed")
	}
	if in.refStore == nil {
		store := newReferenceStore(true)
		if err := store.registerInstance(in); err != nil {
			return nil, err
		}
		in.refStore = store
	}
	return in.refStore, nil
}

func (in *Instance) retainResourceRoot() bool {
	return in.retainResourceRootMode(false)
}

func (in *Instance) retainResourceRootForFinalization() bool {
	return in.retainResourceRootMode(true)
}

func (in *Instance) retainResourceRootMode(finalization bool) bool {
	if in == nil {
		return false
	}
	in.lifeMu.Lock()
	defer in.lifeMu.Unlock()
	if in.resourcesClosed || !railshotResourceRootRetainAllowedLocked(in) || (!finalization && in.invocationState.Load()&instanceInvocationClosed != 0) || in.resourceRefs == maxInt() {
		return false
	}
	in.resourceRefs++
	railshotResourceRootAcquiredLocked(in)
	return true
}

func (in *Instance) releaseResourceRoot() {
	if in == nil {
		return
	}
	in.lifeMu.Lock()
	if in.resourceRefs == 0 {
		in.lifeMu.Unlock()
		return
	}
	in.resourceRefs--
	railshotResourceRootReleasedLocked(in)
	closed := in.closed
	reconcile := closed && in.resourceRefs == 1 && !in.proxyReconciliation && !in.proxyReconciled
	in.lifeMu.Unlock()
	if closed {
		if managedFunctionDeferFinalization(in) {
			return
		}
		if reconcile {
			railshotReconcileClosedReferenceProxies(in)
		}
		in.tryFinalize()
	}
}

func (in *Instance) hasResourceRoots() bool {
	in.lifeMu.Lock()
	defer in.lifeMu.Unlock()
	return in.resourceRefs != 0
}

func (in *Instance) hasPhysicalResources() bool {
	in.lifeMu.Lock()
	defer in.lifeMu.Unlock()
	return !in.resourcesClosed
}

// Storage alone is not cross-Runtime conversion authority. A scalar-only
// collector-free producer remains importable; converted publications still
// require the complete current invocation's authority before changing storage.
func (in *Instance) requiresSameRuntimeInvocation() bool {
	if in.executionFlags.Load()&executionFlagDynamicGCDomain == 0 {
		return false
	}
	in.refStore.mu.Lock()
	defer in.refStore.mu.Unlock()
	entry := in.refStore.instances[in]
	if entry == nil || !entry.conversionOnlyInvocationDomains {
		return true
	}
	hasConversionAuthority := func(d *gcStoreDomain) bool {
		return d != nil && (d.conversionPublishers != 0 || d.conversionClaims != 0)
	}
	if hasConversionAuthority(entry.gcDomain) {
		return true
	}
	for i := 0; i < entry.invocationDomains.len(); i++ {
		if hasConversionAuthority(entry.invocationDomains.at(i)) {
			return true
		}
	}
	return false
}

