		// Prefer X27 when explicit bounds do not own it. Otherwise spend only an
		// extended local-pin register that residency left unused; the poll cache
		// must never evict a hot local merely to save one metadata load.
		if candidate := selectLoopTrapCellReg(f.memSizeReg, f.reserved, f.pinnedLocalMask); candidate != regNone {
			f.trapCellReg = candidate
			f.reserved = f.reserved.add(candidate)
			f.stats.peep("loop-trap-cell")
		}
	}
	for i := range f.locals {
		if r := f.locals[i].reg; r >= X2 && r <= X7 {
			f.stats.peep("entry-arg-local-pin")
		}
	}
	// A call-free register-ABI leaf can keep its integer parameters in the
	// incoming argument registers.  Unlike the normal X19..X23 local pins, those
	// registers are caller-clobbered, so this leaves the caller's pinned locals
	// intact across a hot direct call.  It also removes the otherwise redundant
	// internal-entry arg-to-local moves.  This is deliberately leaf-only: a
	// callee that itself makes a call must retain the normal callee-saved local
	// model for its own call boundaries.
	if f.preserveCallerPins && !f.scalarSummary.Eligible {
		f.pinLeafRegABIIntParams()
	}
	if f.pinnedLocalMask.has(mergeReg) {
		f.regMerge = false // X15 now holds a pinned local/global, so it can't be the merge register
	}
	// STACK_REG (lazy pinned-local spill) for every call-making function,
	// including memory-touching ones: dirty-only stores before a call, lazy reload
	// on the next read (WARP's model). #68 disabled this for memory functions as a
	// workaround; the actual root cause was the opElse merge edge skipping
	// reconcileLocals (fixed in control.go, TestExecIfElseLocalMerge).
	f.makesCalls = hasCall
	f.scopedConstHints.flags = hints.flags
	if f.opt(optScopedLoopIntConst) && hasCall && hints.loopIntConstCount != 0 {
		f.scopedConstHints = scopedConstHintsFrom(hints)
	}
	f.usesCalls = hasCall && policy.EnabledOption(optStackReg)
	// A call-free leaf extends the deepest checked stack by exactly one frame; the
	// fence's 256 KiB margin (runtime stackFenceMargin) absorbs that when the frame
	// is provably small. frameSize isn't known until after the body, so bound it:
	// spill slots never exceed the body's operand pushes (< one per body byte).
	f.skipFence = shouldSkipStackFence(hasCall, f.nLocalSlots, len(c.BodyBytes))
	// The return-in-register hint helps compute/call-heavy code (recursion,
	// dispatch) but adds register pressure in the deep, memory-bound call graphs
	// (json-as's TLSF/GC) where it measured as a small regression. Gate it on
	// !touchesMemory so it only fires where it's a win.
	f.singleRegResult = regABI && !touchesMemory && len(ft.Results) == 1
	if f.singleRegResult {
		rt := mtOf(ft.Results[0])
		f.resultFloat = rt.isFloat()
		f.resultF64 = rt == mtF64
	}
	f.lazyZero = hints.flags.has(hintCallsSelf) && touchesMemory && len(c.BodyBytes) <= 192 && nLocals-len(ft.Params) <= 8

	// Auto-inlining: reserve each spliced callee's locals past f.nLocals (after all
	// nLocals-dependent setup above, so zeroDeclaredLocals/skipFence/lazyZero see the
	// caller's own locals only). Extends the frame's local arrays with unpinned
	// scratch; the splice at each call site binds/zeroes them.
	f.reserveInlineLocals(inlinedCallees, inlineTargets)
	// Reject an already-oversized locals/header frame before emitting any
	// SP-relative homes whose architecture encoding has a smaller displacement.
	// Operand spills can only grow this frame and remain checked after lowering.
	if err := f.validateFrameSize(f.frameSize()); err != nil {
		return nil, nil, 0, err
	}

	if regallocCheckEnabled {
		checkSourceBegin(f, hostAdapter || !regABI)
	}

	if regABI {
		internalOff, err := f.emitRegABI(c, hostAdapter, hints.localScore, hints.flags.has(hintHasFloatConst), hints)
		if err != nil {
			return nil, nil, 0, err
		}
		if f.gcFrameRoots != nil {
			f.gcFrameRoots.FrameBytes = uint32(f.frameSize())
			if f.gcCallsiteIndex != f.gcFrameRoots.CallMaskCount() {
				f.gcFrameRoots.Exact = false
			}
		}
		f.finalizePeepholes(internalOff)
		if err := f.emitFloatConstPool(); err != nil {
			return nil, nil, 0, err
		}
		if regallocCheckEnabled {
			checkSourceFinishEmission(f)
		}
		internalOff, err = f.finalizeNativeCode(internalOff)
		if err != nil {
			return nil, nil, 0, err
		}
		if regallocCheckEnabled {
			checkSourceVerify(f)
		}
		f.finalizeStats(len(f.a.B))
		return f.a.B, f.relocs, internalOff, nil
	}

	f.prologue(hints.localScore)
	f.preloadLoopIntConsts(hints)
	if hints.flags.has(hintHasFloatConst) {
		f.preloadFloatConsts(c.BodyBytes)
	}
	f.preloadV128Consts(c.BodyBytes)
	if err := f.runBody(c); err != nil {
		return nil, nil, 0, err
	}
	f.epilogue()
	if profileEnabled {
		f.collectProfileSources(0)
	}
	f.emitTrapStubs()
	f.emitPhasePadding()
	if err := f.patchFrameAdjusts(); err != nil {
		return nil, nil, 0, err
	}
	if f.gcFrameRoots != nil {
		f.gcFrameRoots.FrameBytes = uint32(f.frameSize())
		if f.gcCallsiteIndex != f.gcFrameRoots.CallMaskCount() {
			f.gcFrameRoots.Exact = false
		}
	}
	f.finalizePeepholes()
	if err := f.emitFloatConstPool(); err != nil {
		return nil, nil, 0, err
	}
	if _, err := f.finalizeNativeCode(0); err != nil {
		return nil, nil, 0, err
	}
	f.finalizeStats(len(f.a.B))
	return f.a.B, f.relocs, 0, nil
}

// preservesCallerPins identifies the deliberately narrow internal-call ABI
// variant used for hot, simple leaves. Such a function has no declared locals,
// calls, memory access, or global access; its integer parameters can stay in the
// incoming argument registers while every caller-pinned register is reserved.
// Consequently it cannot observe or modify caller state outside X0..X7/X16/X17.
func preservesCallerPins(ft *wasm.CompType, nLocals int, h funcHints) bool {
	if !sigFitsRegABI(ft) || !sigIsIntOnly(ft) || nLocals != len(ft.Params) || h.flags.has(hintHasCall|hintTouchesMemory|hintUsesBulkMem) {
		return false
	}
	if h.globalCount != 0 {
		return false
	}
	return true
}

// finalizeStats fills the per-function size counters from final compiler state
// (no-op when collection is off). Per-event counters are incremented at their
// emission sites during the body.
func (f *fn) finalizeStats(codeLen int) {
	s := f.stats
	if !diagnosticsEnabled || s == nil {
		return
	}
	s.CodeBytes = codeLen
	s.NativeSize.TotalBytes = codeLen
	s.NativeSize.InternalFunctionBytes = codeLen - s.NativeSize.HostAdapterBytes - s.NativeSize.AdapterToInternalPaddingBytes
	s.GCCodeBytes.Total = codeLen
	s.peepN("logical-move-immediate", f.a.LogicalMoveImmediates)
	s.peepN("compact-move-immediate32", f.a.CompactMoveImmediates32)
	s.peepN("single-negative-move32", f.a.SingleNegativeMoves32)
	s.peepN("indexed-base-reuse", f.a.IndexedBaseReuses)
	s.FrameBytes = f.frameSize()
	s.MaxSpillSlots = f.maxSpill
	s.MaxPendingNodes = int(f.s.maxPending)
}

// runBody opens the function control frame, lowers the body, and patches every
// return/br-to-function site to the current epilogue position.
func (f *fn) runBody(c *wasm.Func) error {
	f.innermostLoop = 0
	if f.scalarSummary.Eligible {
		f.ctrl = f.sc.ctrl[:0]
		return f.scalarBody(c)
	}

	sc := f.scratchState()
	resultTypes := lowerFunctionResultTypes(sc, f.ft.Results)
	if len(resultTypes) <= len(sc.functionResultTypeArena) {
		f.controlBaseTypeN = uint8(len(resultTypes))
	}
	f.ctrl = append(sc.ctrl[:0], ctrlFrame{kind: cfFunc, resultN: len(resultTypes), branchN: uint32(len(resultTypes)), types: resultTypes})
	if err := f.body(c.BodyBytes); err != nil {
		return err
	}
	f.patchReturnSites()
	return nil
}

func (f *fn) appendReturnSite(site int) {
	if site < 0 || site&3 != 0 || site/4 >= 1<<26-1 {
		f.setRepresentationLimit(functionRepresentationReturnSite)
		return
	}
	sc := f.scratchState()
	word := rdWord(f.a.B, site)
	wrWord(f.a.B, site, word&0xfc000000|sc.retSiteHead)
	sc.retSiteHead = uint32(site/4 + 1)
}

func (f *fn) patchReturnSites() {
	sc := f.scratchState()
	for head := sc.retSiteHead; head != 0; {
		site := int(head-1) * 4
		word := rdWord(f.a.B, site)
		head = word & 0x03ffffff
		wrWord(f.a.B, site, word&0xfc000000)
		f.patchBranch26(site, f.a.Len())
	}
}

// assignPinnedLocals dedicates registers to the hottest integer locals (by the
// hotness scores). Locals with a zero score (the DecodeModule BodyBytes path or
// unused) are ordered by index, so byte-backed bodies fall back to first-N
// pinning.
// gpPinPool returns the registers available to hold pinned integer locals, in
// priority order (hottest local gets the first). The base is X19-X25; these are
// callee-saved across the native entry boundary, module-global pins are removed
// before assignment, and call-making functions use the STACK_REG spill/lazy-load
// model when a Wasm callee may reuse them. Call-free functions may additionally
// use X8.
//
// The wrapper-arg registers (X0-X3) are deliberately NOT pinned. A call's
// linMem/trap/results setup clobbers them (they are not the reg-ABI internal-entry
// arg registers — intArgRegs is X0-X7, but pins never land there anyway), and in a
// register-heavy function that both touches memory (which reserves X27, pushing
// pins onto the extended pool) and makes multi-arg calls, having a pinned local
// live in a call-clobbered register on top of the arg-register pins over-subscribed
// the file: the call's arg-staging + setup ran out of free scratch and silently
// corrupted a pinned local's value. The observable repro is sqlite's tokenizer —
// every SQL keyword misreads as an identifier ("near \"SELECT\": syntax error").
// Restricting pins to the callee-saved block plus the STACK_REG-managed
// X9/X10/X11 removes the hazard. See TestSyncSQLiteQuery.
//
// X9/X10/X11 are still excluded in reg-ABI functions with >4 params (the internal
// entry's incoming args would collide with the prologue's arg→pinned moves). X15
// costs the block-merge register (the caller drops regMerge). X1/X0 always stay
// free for operand evaluation and the return register; callHost's scratch also
// lives in the caller-saved temporaries.
func gpPinPool(pool []Reg, regABI bool, nParams int, callFree bool) []Reg {
	return gpPinPoolWithPolicy(pool, regABI, nParams, callFree, currentCodegenPolicy())
}

func gpPinPoolWithPolicy(pool []Reg, regABI bool, nParams int, callFree bool, policy CodegenPolicy) []Reg {
	pool = append(pool, pinnedLocalRegs...) // X19-X23
	pool = append(pool, X24, X25)
	if callFree && policy.EnabledOption(optX8Pin) {
		pool = append(pool, X8)
		// X8 is neither an internal integer argument (X0-X7) nor a fixed-role
		// backend scratch.
	}
	if !regABI || nParams <= 4 {
		pool = append(pool, X9, X10, X11)
	}
	pool = append(pool, X15)
	if !callFree {
		pool = append(pool, X27)
	}
	return pool
}

func callSafePinPool(pool []Reg) []Reg {
	safe := pool[:0]
	for _, reg := range pool {
		if reg >= X19 && reg <= X25 {
			safe = append(safe, reg)
		}
	}
	return safe
}

// gpPinLimit leaves enough of the target's unreserved allocatable file for the
// widest ordinary lowering step: three protected inputs/temporaries plus one
// result. Whole-function pins are optional; transient lowering must not retry a
// function merely because module roles made the physical file smaller.
func gpPinLimit(reserved regMask) int {
	const minTransientGP = 4
	available := 0
	for _, r := range gpAlloc {
		if !reserved.has(r) {
			available++
		}
	}
	if available <= minTransientGP {
		return 0
	}
	return available - minTransientGP
}

func selectLoopTrapCellReg(memSize Reg, reserved, pinned regMask) Reg {
	for _, candidate := range [...]Reg{X27, X25, X24} {
		withCandidate := reserved.add(candidate)
		if candidate == memSize || reserved.has(candidate) || pinned.has(candidate) ||
			pinned.count() > gpPinLimit(withCandidate) {
			continue
		}
		return candidate
	}
	return regNone
}

// withoutReg returns pool with r removed (order preserved).
func withoutReg(pool []Reg, r Reg) []Reg {
	out := pool[:0]
	for _, p := range pool {
		if p != r {
			out = append(out, p)
		}
	}
	return out
}

func (f *fn) assignPinnedLocals(scores []uint32, globalHints []shared.GlobalHint, gpPool []Reg, hasCall, pinLocals bool) {
	if cap(f.locals) < f.nLocals {
		f.locals = make([]localDef, f.nLocals)
	} else {
		f.locals = f.locals[:f.nLocals]
	}
	for i := range f.locals {
		facts := valueFacts(0)
		if f.localFactsEnabled && i >= f.nParams && f.localType[i] == mtI32 {
			facts = factUpper32Zero | factBoolean // declared locals start at zero
		}
		f.locals[i] = localDef{reg: regNone, facts: facts, state: lsReg}
	}
	// Module-pinned globals (installModuleGlobals) already occupy globalReg
	// entries; keep them and size for whichever view is larger.
	if len(f.globalReg) < f.m.GlobalCount() {
		f.initGlobalRegs(f.m.GlobalCount())
	}
	// The GP pin pool is shared by hot INT locals and hot globals, both holding their
	// VALUE in the register (WARP's model). A global is a candidate only when it is a
	// mutable int accessed inside a loop (score >= one loop level): WARP pins only int
	// globals as values, and the loop gate ensures the per-iteration memory traffic it
	// removes outweighs the one-time prologue load + epilogue write-back.
	var gpStorage [32]gpCand // no target can dedicate more than its physical register file
	if len(gpPool) > len(gpStorage) {
		panic("arm64: GP pin pool exceeds architectural register file")
	}
	gp := gpStorage[:0]
	if len(gpPool) != 0 {
		if f.nLocals > 64 {
			for i := 0; i < f.nLocals && i < 256; i++ {
				if (f.localType[i] == mtI32 || f.localType[i] == mtI64) && i < len(f.wideReuseScore) && f.wideReuseScore[i] != 0 {
					gp = insertGPCandidate(gp, gpCand{idx: uint32(i), score: f.wideReuseScore[i]}, len(gpPool))
				}
			}
		} else {
			for i := 0; i < f.nLocals; i++ {
				if f.localType[i] == mtI32 || f.localType[i] == mtI64 {
					gp = insertGPCandidate(gp, gpCand{idx: uint32(i), score: localHotness(scores[i])}, len(gpPool))
				}
			}
		}
	}
	loopMin := uint32(loopWeight(1))
	// Wide-table reservations are limited to the analyzed locals.
	for _, gh := range globalHints {
		if f.nLocals > 64 {
			continue
		}
		g := int(gh.Index)
		if gh.Score < loopMin || f.isModuleGlobal(g) || hasCall && !gh.Eligible {
			continue
		}
		gt, ok := f.globalType(gh.Index)
		if !ok || !gt.Mutable || !isIntValType(wasm.GlobalValueType(gt)) {
			continue
		}
		gp = insertGPCandidate(gp, gpCand{global: true, idx: uint32(g), score: gh.Score}, len(gpPool))
	}
	for k, c := range gp {
		if k >= len(gpPool) {
			break
		}
		// The extended pool slots (beyond the X19-X23 base) only take locals that
		// are actually used (score > 0): pinning a cold local there costs prologue
		// and call-spill traffic for nothing. Zero-score candidates still fill the
		// base slots so byte-backed decoded bodies keep the first-N fallback.
		if (k >= len(pinnedLocalRegs) || f.nLocals > 64) && c.score == 0 {
			break
		}
		// X27 is the last, opportunistic call-making pin. Spending it adds one
		// more entry home and call-boundary state transition, so require enough
		// loop-weighted traffic to repay that fixed cost. Twenty loop-level local
		// references (20*loopWeight(1)) separates dense kernels from marginal
		// residents without changing the established X19-X25/X15 assignments.
		if gpPool[k] == X27 && hasCall && c.score < 200 {
			break
		}
		if gpPool[k] == X27 {
			f.stats.peep("cold-call-x27-pin")
		}
		idx := int(c.idx)
		if c.global {
			f.globalReg[idx] = gpPool[k]
			f.stats.addPinnedGlobalValue()
		} else {
			f.locals[idx].reg = gpPool[k]
			f.stats.addPinnedLocal()
			if f.nLocals > 64 {
				f.stats.peep("wide-reuse-local-pin")
				if diagnosticsEnabled && f.stats != nil {
					f.stats.peep(fmt.Sprintf("wide-reuse-local-%d", idx))
				}
			}
		}
		f.pinnedLocalMask = f.pinnedLocalMask.add(gpPool[k])
	}
	// Float locals use the separate V pin pool. Call-free functions also pin hot
	// v128 locals here (same V registers, full 128-bit): a wasm→wasm call would only
	// preserve the low 64 bits, so a v128 pin is confined to the call-free class.
	pinV128 := f.opt(optV128Pins) && !hasCall
	hotV128Candidates := 0
	if pinLocals && f.nLocals <= 64 {
		for i := 0; i < f.nLocals; i++ {
			if pinV128 && f.localType[i] == mtV128 && localHotness(scores[i]) > 0 {
				hotV128Candidates++
			}
		}
	}
	fpPinLimit := len(pinnedFLocalRegs)
	deepV128Pins := false
	if !f.opt(optExtendedFPPins) && fpPinLimit > basePinnedFLocalRegs {
		fpPinLimit = basePinnedFLocalRegs
	} else if !hasCall && hotV128Candidates >= 24 {
		// Wide vector kernels have short expression trees but large named v128
		// state. Keeping that state resident is worth the smaller transient pool;
		// scalar-float kernels retain the measured 15-pin cap below.
		fpPinLimit = len(pinnedFLocalRegs)
		deepV128Pins = true
		f.stats.peep("deep-v128-local-pins")
	} else if !hasCall && fpPinLimit > callFreePinnedFLocalRegs {
		// Call-free numeric loops still need room for wide expression trees. Past
		// this point nbody loses more to transient-register pressure than it gains
		// from another local pin. Call-making raytrace has sparse call sites and a
		// much larger live-local set, so its existing STACK_REG path profitably uses
		// the full pool.
		fpPinLimit = callFreePinnedFLocalRegs
	} else if hasCall && fpPinLimit > 27 {
		fpPinLimit = 27
	}
	if !pinLocals || f.nLocals > 64 {
		// Keep very wide signatures canonical so optional V-register pins cannot
		// consume the transient register floor.
		fpPinLimit = 0
	}
	var fcStorage [32]uint16 // bounded by the 32-register architectural V file
	if fpPinLimit > len(fcStorage) {
		panic("arm64: FP pin limit exceeds architectural register file")
	}
	fc := fcStorage[:0]
	if fpPinLimit != 0 {
		for i := 0; i < f.nLocals; i++ {
			if f.localType[i].isFloat() || (pinV128 && f.localType[i] == mtV128) {
				fc = insertLocalCandidate(fc, uint16(i), scores, fpPinLimit)
			}
		}
	}
	usedFP := 0
	for k, local := range fc {
		if k >= fpPinLimit {
			break
		}
		i := int(local)
		if deepV128Pins && localHotness(scores[i]) == 0 {
			break
		}
		f.locals[i].reg = pinnedFLocalRegs[k]
		f.locals[i].isFloat = true
		f.fpinnedLocalMask = f.fpinnedLocalMask.add(pinnedFLocalRegs[k])
		f.stats.addPinnedLocal()
		usedFP++
	}
	f.assignPinnedFloatGlobals(globalHints, hasCall, loopMin, usedFP, fpPinLimit)
}

// pinLeafRegABIIntParams maps integer parameters of a call-free register-ABI
// function onto X0..X7, their incoming locations at the internal entry.  The
// normal local allocator may already have selected a callee-saved pin for the
// parameter; release that pin before installing the argument register.
func (f *fn) pinLeafRegABIIntParams() {
	gp := 0
	for i := 0; i < f.nParams; i++ {
		if f.localType[i].isFloat() {
			continue
		}
		if gp >= len(intArgRegs) {
			return
		}
		if old := f.locals[i].reg; old != regNone {
			f.pinnedLocalMask = f.pinnedLocalMask.remove(old)
		}
		f.locals[i].reg = intArgRegs[gp]
		f.pinnedLocalMask = f.pinnedLocalMask.add(intArgRegs[gp])
		gp++
	}
}

// derivePinnedGlobals loads each pinned global's cell pointer into its dedicated
// register, once, in the prologue (linMemReg = linMem must already be set). A no-op when
// no globals are pinned. Every later access reads/writes through the register.
func (f *fn) globalIs64(g int) bool {
	gt, _ := f.globalType(uint32(g))
	return wasm.EqualValType(wasm.GlobalValueType(gt), wasm.I64)
}

const (
	globalRegDirty Reg = 1 << 7
	globalRegFloat Reg = 1 << 6
)

func globalRegIsFloat(state Reg) bool { return state != regNone && state&globalRegFloat != 0 }

func globalRegValue(state Reg) Reg {
	if state == regNone {
		return regNone
	}
	return state &^ (globalRegDirty | globalRegFloat)
}

func globalRegIsDirty(state Reg) bool {
	return state != regNone && state&globalRegDirty != 0
}

func (f *fn) initGlobalRegs(n int) {
	if cap(f.globalReg) < n {
		f.globalReg = make([]Reg, n)
	} else {
		f.globalReg = f.globalReg[:n]
	}
	for i := range f.globalReg {
		f.globalReg[i] = regNone
	}
}

// installModuleGlobals records the module-wide global→register pins on this
// function (every function in the module shares the same assignment).
func (f *fn) installModuleGlobals(pins []moduleGlobalPin) {
	if len(pins) == 0 {
		return
	}
	nG := f.m.GlobalCount()
	if len(f.globalReg) < nG {
		f.initGlobalRegs(nG)
	}
	f.moduleGlobals = pins
	for _, p := range pins {
		f.globalReg[p.global] = p.reg
	}
}

func (f *fn) isModuleGlobal(g int) bool {
	for _, p := range f.moduleGlobals {
		if int(p.global) == g {
			return true
		}
	}
	return false
}

// deriveModuleGlobals / storeModuleGlobals sync the module-pinned globals with
// their cells at wasm↔native boundaries (offset-0 prologues and epilogues, the
// adapter's Go exit, trap stubs) and before wrapper-ABI calls (whose callee's
// offset-0 prologue reloads). Register-ABI calls and returns carry nothing.
// scratch must be a register safe to clobber at the call site.
func (f *fn) deriveModuleGlobals() {
	for g, state := range f.globalReg {
		reg := globalRegValue(state)
		if reg == regNone || !f.isModuleGlobal(g) {
			continue
		}
		f.ld64(reg, linMemReg, -int32(abi.GlobalsPtrOffset))
		f.ld64(reg, reg, int32(g*8))
		if f.globalIs64(g) {
			f.ld64(reg, reg, 0)
		} else {
			f.ld32(reg, reg, 0)
		}
	}
}

func (f *fn) storeModuleGlobals(scratch Reg) {
	f.storeGlobalPins(scratch, false)
}

// Trap exits also persist dirty function-local value pins using a fixed scratch.
func (f *fn) storeGlobalPins(scratch Reg, valuePins bool) {
	for g, state := range f.globalReg {
		reg := globalRegValue(state)
		if reg == regNone || (!f.isModuleGlobal(g) && (!valuePins || !globalRegIsDirty(state))) {
			continue
		}
		f.ld64(scratch, linMemReg, -int32(abi.GlobalsPtrOffset))
		f.ld64(scratch, scratch, int32(g*8))
		f.storePinnedGlobalValue(g, state, scratch)
	}
}

// storeDirtyGlobalPins publishes only values changed by this function. An EH
// transfer may rederive every pin in the handler after restoring instance
// context, so direct throws must make deferred global.set values cell-coherent
// first. Filtering on the compile-time dirty bit keeps the cold edge compact.
func (f *fn) storeDirtyGlobalPins(scratch Reg) {
	for g, state := range f.globalReg {
		reg := globalRegValue(state)
		if reg == regNone || !globalRegIsDirty(state) {
			continue
		}
		f.ld64(scratch, linMemReg, -int32(abi.GlobalsPtrOffset))
		f.ld64(scratch, scratch, int32(g*8))
		f.storePinnedGlobalValue(g, state, scratch)
	}
}

// derivePinnedGlobals loads each value-pinned global's current value into its
// register from memory (base → &cell → value, reusing the register for the chain).
// Used in the prologue and to reload after a call (the callee may have changed the
// shared global). A no-op when no globals are pinned.
func (f *fn) derivePinnedGlobals() {
	f.derivePinnedGlobalsIn(^regMask(0))
}

// derivePinnedGlobalsIn reloads only globals assigned to registers in regs.
// Fixed-register sequences use it to restore their narrow scratch bank without
// touching unrelated value pins.
func (f *fn) derivePinnedGlobalsIn(regs regMask) {
	for g, state := range f.globalReg {
		reg := globalRegValue(state)
		if reg == regNone || f.isModuleGlobal(g) {
			continue
		}
		if globalRegIsFloat(state) {
			// Narrow masks describe GP clobbers, not the overlapping V-register bank.
			if regs != ^regMask(0) {
				continue
			}
			cell := f.allocReg(maskOf(X0))
			f.ld64(cell, linMemReg, -int32(abi.GlobalsPtrOffset))
			f.ld64(cell, cell, int32(g*8))
			gt, _ := f.globalType(uint32(g))
			f.a.LdrF(reg, cell, 0, wasm.EqualValType(wasm.GlobalValueType(gt), wasm.F64))
			f.release(cell)
		} else {
			if !regs.has(reg) {
				continue
			}
			f.ld64(reg, linMemReg, -int32(abi.GlobalsPtrOffset))
			f.ld64(reg, reg, int32(g*8))
			if f.globalIs64(g) {
				f.ld64(reg, reg, 0)
			} else {
				f.ld32(reg, reg, 0)
			}
		}
	}
}

// storePinnedGlobals writes value-pinned globals' registers back to their memory
// cells. dirtyOnly (epilogue) writes only the globals this function actually set;
// the call path (dirtyOnly=false) writes all of them before a call so the callee
// observes the current value. Avoids X0 (the int result register) for the
// cell-address scratch.
func (f *fn) storePinnedGlobals(dirtyOnly bool) {
	f.storePinnedGlobalsIn(^regMask(0), dirtyOnly)
}

// storePinnedGlobalsIn writes only globals assigned to registers in regs.
func (f *fn) storePinnedGlobalsIn(regs regMask, dirtyOnly bool) {
	for g, state := range f.globalReg {
		reg := globalRegValue(state)
		if reg == regNone || f.isModuleGlobal(g) || (globalRegIsFloat(state) && regs != ^regMask(0)) || (!globalRegIsFloat(state) && !regs.has(reg)) || (dirtyOnly && !globalRegIsDirty(state)) {
			continue
		}
		t := f.allocReg(maskOf(reg, X0))
		f.ld64(t, linMemReg, -int32(abi.GlobalsPtrOffset))
		f.ld64(t, t, int32(g*8))
		f.storePinnedGlobalValue(g, state, t)
		f.release(t)
	}
}

// prologue: frameless body — pin linMem in linMemReg (moved from X1 per WARP's
// convention), save FP/LR in call-making functions, reserve the frame with one
// `SUB SP,SP,#frameSize`, stash the results ptr in the SP-relative header, load
// params into their register or slot, zero declared locals.
func (f *fn) prologue(localScores []uint32) {
	a := f.a
	if f.makesCalls {
		a.StpPre(FP, LR, SP, -16) // save FP/LR frame record (BL clobbers LR)
		a.AddImm64(FP, SP, 0)     // MOV X29, SP — frame pointer for backtraces
	}
	// Frame reserve: a fixed MOVZ/MOVK X16 + `SUB SP,SP,X16` sequence whose two mov
	// immediates are patched with frameSize after the body (the SUB-imm form is only
	// 12 bits, so we materialize the size in the backend scratch X16 — uniform for
	// any frame size). See CONTRACT §4h option 1.
	f.subRspAt = a.Len()
	a.Movz64(X16, 0, 0)       // frame size lo 16 bits; patched after body
	a.Movk64(X16, 0, 1)       // frame size hi 16 bits
	a.SubSPReg(X16)           // SUB SP, SP, X16
	a.MovReg64(linMemReg, X1) // linMem → linMemReg (pinned for the whole function)
	if f.trapCellReg != regNone {
		f.ld64(f.trapCellReg, linMemReg, -int32(offTrapCellPtr))
	}
	f.st64(SP, frResultsOff, X3) // results ptr (trap cell ptr lives in basedata)
	if f.memSizeReg != regNone {
		// Offset-0 entry: establish the module-wide memBytes cache. Direct wasm→wasm
		// register-ABI calls skip this (the caller's value is valid by construction).
		f.loadMemoryCache()
		if f.memLimitReg != regNone {
			f.a.SubImm64(f.memLimitReg, f.memSizeReg, uint32(f.memLimitExtent))
		}
	}
	f.emitStackFenceCheck(linMemReg, X16)
	f.emitInterruptCheck(false)
	f.entryTrapEnd = a.Len()
	if f.cacheImportDispatch {
		f.ld64(X25, linMemReg, -int32(offImportDispatchPtr))
	}
	if f.cacheNativeImportTarget {
		f.ld64(X24, X25, coreruntime.ImportDispatchCodePtrOffset)
		f.a.AddImm64(X24, X24, coreruntime.NativeScalarLeafRegisterEntryOffset)
	}
	// Copy v128 params through V0 before loading any pinned scalar float params.
	// V0 is only a prologue scratch here; keeping these copies first prevents a
	// future pin-pool change from letting a later v128 copy clobber an already-live
	// scalar param register. X0 is the serArgs base (wrapper-ABI arg 0).
	paramOff := int32(0)
	for i, pt := range f.ft.Params {
		if f.localType[i] == mtV128 {
			if pr, _, ok := f.pinReg(i); ok {
				a.VMovdquLoadDisp(pr, X0, paramOff) // pinned v128 param → its V register
			} else {
				a.VMovdquLoadDisp(0, X0, paramOff)
				a.VMovdquStoreDisp(SP, f.localOff(i), 0)
			}
		}
		paramOff += abiValSize(pt)
	}
	x0ParamOff := int32(-1) // a param pinned in X0 must load LAST: X0 is the args base
	x0ParamI32 := false
	pairParams := f.opt(optEntryParamPairs)
	pendingParam := pendingWrapperParamHome{}
	paramOff = 0
	for i, pt := range f.ft.Params {
		if f.localType[i] != mtV128 {
			if pr, isFloat, ok := f.pinReg(i); ok && !isFloat {
				if pr == X0 {
					x0ParamOff = paramOff
					x0ParamI32 = f.canonicalI32Local(i)
				} else if f.canonicalI32Local(i) {
					f.ld32(pr, X0, paramOff)
					f.stats.peep("entry-i32-param-canonicalize")
				} else {
					f.ld64(pr, X0, paramOff) // pinned int param → its GP register
				}
			} else if ok && isFloat {
				a.FLoadDisp(pr, X0, paramOff, f.localType[i] == mtF64) // pinned float param → V reg
			} else if f.canonicalI32Local(i) {
				if pairParams {
					f.flushWrapperParamHome(pendingParam)
					pendingParam = pendingWrapperParamHome{}
				}
				f.ld32(X16, X0, paramOff)
				f.st64(SP, f.localOff(i), X16)
				f.stats.peep("entry-i32-param-canonicalize")
			} else {
				if pairParams {
					pendingParam = f.queueWrapperParamHome(pendingParam, paramOff, f.localOff(i))
				} else {
					// X16 (backend scratch) is the copy temp: X0 is the serArgs base and
					// must stay live for the remaining param loads (amd64 used RAX here,
					// but on arm64 that role register aliases the args base).
					f.ld64(X16, X0, paramOff)
					f.st64(SP, f.localOff(i), X16)
				}
			}
		}
		paramOff += abiValSize(pt)
	}
	if pairParams {
		f.flushWrapperParamHome(pendingParam)
	}
	if x0ParamOff >= 0 {
		if x0ParamI32 {
			f.ld32(X0, X0, x0ParamOff)
			f.stats.peep("entry-i32-param-canonicalize")
		} else {
			f.ld64(X0, X0, x0ParamOff)
		}
	}
	f.zeroDeclaredLocals(localScores)
	f.derivePinnedGlobals()
	f.deriveModuleGlobals() // offset-0 entry: cells → module-pinned registers
}

type pendingWrapperParamHome struct {
	argOff   int32
	localOff int32
	valid    bool
}

func (f *fn) queueWrapperParamHome(p pendingWrapperParamHome, argOff, localOff int32) pendingWrapperParamHome {
	if p.valid && argOff == p.argOff+8 && localOff == p.localOff+8 && p.argOff <= 504 && p.localOff <= 504 {
		f.a.LdpOffset(X16, X17, X0, p.argOff)
		f.a.StpOffset(X16, X17, SP, p.localOff)
		f.stats.peep("entry-param-pair-wrapper")
		return pendingWrapperParamHome{}
	}
	if p.valid {
		f.ld64(X16, X0, p.argOff)
		f.st64(SP, p.localOff, X16)
	}
	return pendingWrapperParamHome{argOff: argOff, localOff: localOff, valid: true}
}

func (f *fn) flushWrapperParamHome(p pendingWrapperParamHome) {
	if p.valid {
		f.ld64(X16, X0, p.argOff)
		f.st64(SP, p.localOff, X16)
	}
}

// zeroDeclaredLocals initializes non-parameter locals. Most functions keep the
// old eager zeroing path; small call+memory functions use WARP-style lazy zero,
// where reads materialize zero on demand and control-flow reconciliation stores it
// to the frame before paths diverge when required.
func (f *fn) zeroDeclaredLocals(localScores []uint32) {
	if f.scalarSummary.Eligible {
		// ScalarState owns zero values and establishes homes only when needed.
		return
	}
	f.zeroEHGCRootLanes()
	if f.nLocals <= f.nParams {
		return
	}
	if !f.lazyZero {
		a := f.a
		pairZeros := f.opt(optEntryZeroPairs)
		entryInitElision := f.opt(optEntryInitElision) && (f.gcFrameRoots == nil || !f.gcFrameRoots.Candidate)
		pendingZero := int32(-1)
		// AArch64 has a zero register (XZR): store it directly, no scratch to clear.
		for i := f.nParams; i < f.nLocals; i++ {
			if entryInitElision && i < 64 && localScores[i]&localScoreEntryInitialized != 0 {
				if pairZeros {
					pendingZero = f.flushDeclaredZeroSlot(pendingZero)
				}
				f.stats.peep("entry-init-elide")
				continue
			}
			if pr, _, ok := f.pinReg(i); ok && f.localType[i] == mtV128 {
				if pairZeros {
					pendingZero = f.flushDeclaredZeroSlot(pendingZero)
				}
				a.NeonEor16b(pr, pr, pr) // zero the whole 128-bit pin register
			} else if pr, isFloat, ok := f.pinReg(i); ok && !isFloat {
				if pairZeros {
					pendingZero = f.flushDeclaredZeroSlot(pendingZero)
				}
				a.MovImm64(pr, 0)
			} else if ok && isFloat {
				if pairZeros {
					pendingZero = f.flushDeclaredZeroSlot(pendingZero)
				}
				a.FmovFromGpr(pr, ZR, false) // fmov d,xzr → 0.0
			} else if f.localType[i] == mtV128 {
				if pairZeros {
					pendingZero = f.queueDeclaredZeroSlot(pendingZero, f.localOff(i))
					pendingZero = f.queueDeclaredZeroSlot(pendingZero, f.localOff(i)+8)
				} else {
					f.st64(SP, f.localOff(i), ZR)
					f.st64(SP, f.localOff(i)+8, ZR)
				}
			} else {
				if pairZeros {
					pendingZero = f.queueDeclaredZeroSlot(pendingZero, f.localOff(i))
				} else {
					f.st64(SP, f.localOff(i), ZR)
				}
			}
		}
		if pairZeros {
			f.flushDeclaredZeroSlot(pendingZero)
		}
		return
	}
	for i := f.nParams; i < f.nLocals; i++ {
		f.markDeclaredLocalZero(i)
	}
}

func (f *fn) queueDeclaredZeroSlot(pending, off int32) int32 {
	if pending >= 0 && off == pending+8 && pending <= 504 {
		f.a.StpOffset(ZR, ZR, SP, pending)
		f.stats.peep("entry-zero-pair")
		return -1
	}
	if pending >= 0 {
		f.st64(SP, pending, ZR)
	}
	return off
}

func (f *fn) flushDeclaredZeroSlot(pending int32) int32 {
	if pending >= 0 {
		f.st64(SP, pending, ZR)
	}
	return -1
}

// emitStackFenceCheck traps (StackFence → "call stack exhausted") when SP has
// dropped below the fence stored at [linMem-72], turning unbounded recursion into
// a clean trap instead of a fault. A zero fence disables the check (SP > 0).
func (f *fn) emitStackFenceCheck(linMemReg, scratch Reg) {
	if !f.opt(optStackFence) || f.skipFence {
		return
	}
	f.ld64(scratch, linMemReg, -72)
	f.a.CmpSP64(scratch)            // CMP SP, scratch (SP-in-Rn extended-register form)
	f.trapIf(condB, trapStackFence) // SP below the fence → cold stub
}

// emitHostAdapter emits the wrapper-to-register ABI bridge and returns the BL
// site that will be patched to the internal entry after the function body.
func (f *fn) emitHostAdapter(np, rN int) int {
	a := f.a
	a.MovReg64(linMemReg, X1) // linMem → linMemReg: the module-wide invariant the internal entry inherits
	if f.memSizeReg != regNone {
		// Offset-0 entry (from Go, or an indirect call): establish the module-wide
		// memBytes cache before the internal entry runs (which relies on it).
		f.loadMemoryCache()
	}
	f.deriveModuleGlobals()   // offset-0 entry: cells → module-pinned registers
	a.StpPre(LR, X3, SP, -16) // save LR (BL clobbers it) + results ptr; keeps SP 16-aligned
	gp, fp := 0, 0
	x0ArgOff := int32(-1) // the arg targeting X0 aliases the serArgs base: load it LAST
	for i := 0; i < np; i++ {
		mt := f.localType[i]
		if mt.isFloat() {
			a.FLoadDisp(fpArgRegs[fp], X0, int32(8*i), mt == mtF64)
			fp++
		} else {
			if intArgRegs[gp] == X0 {
				x0ArgOff = int32(8 * i)
			} else {
				f.ld64(intArgRegs[gp], X0, int32(8*i))
			}
			gp++
		}
	}
	if x0ArgOff >= 0 {
		f.ld64(X0, X0, x0ArgOff)
	}
	adapterCall := a.Bl()
	f.adapterReturnOff = adapterCall + 4
	if f.gcFrameRoots != nil {
		f.gcFrameRoots.AdapterReturnOffset = uint32(adapterCall + 4)
	}
	if registerQuadResultsSupported && rN > 2 && !sigIsFloatOnly(f.ft) {
		// X3 may be result 3; restore the results pointer into X8 instead.
		a.LdpPost(LR, X8, SP, 16)
		gp, fp := 0, 0
		for i, typ := range f.ft.Results {
			if mtOf(typ).isFloat() {
				a.FStoreDisp(X8, int32(i*8), Reg(fp), mtOf(typ) == mtF64)
				fp++
			} else {
				f.st64(X8, int32(i*8), []Reg{X0, X1, X2, X3, X4, X5, X6, X7}[gp])
				gp++
			}
		}
	} else {
		a.LdpPost(LR, X3, SP, 16) // restore LR + results ptr
	}
	f.storeModuleGlobals(X2) // Go exit: module-pinned registers → cells
	if preparedDirectFloatSupported && rN > 2 && sigIsFloatOnly(f.ft) {
		for i, typ := range f.ft.Results {
			a.FStoreDisp(X3, int32(i*8), Reg(i), mtOf(typ) == mtF64)
		}
	}
	if rN == 1 {
		rt := mtOf(f.ft.Results[0])
		if rt.isFloat() {
			a.FStoreDisp(X3, 0, 0, rt == mtF64)
		} else {
			f.st64(X3, 0, X0)
		}
	} else if rN == 2 {
		if preparedDirectFloatSupported && mtOf(f.ft.Results[0]).isFloat() && !mtOf(f.ft.Results[1]).isFloat() {
			a.FStoreDisp(X3, 0, 0, mtOf(f.ft.Results[0]) == mtF64)
			f.st64(X3, 8, X0)
		} else if preparedDirectFloatSupported && !mtOf(f.ft.Results[0]).isFloat() && mtOf(f.ft.Results[1]).isFloat() {
			f.st64(X3, 0, X0)
			a.FStoreDisp(X3, 8, 0, mtOf(f.ft.Results[1]) == mtF64)
		} else if preparedDirectFloatSupported && mtOf(f.ft.Results[0]).isFloat() {
			for i, typ := range f.ft.Results {
				a.FStoreDisp(X3, int32(i*8), Reg(i), mtOf(typ) == mtF64)
			}
		} else {
			f.st64(X3, 0, X0)
			f.st64(X3, 8, X1)
		}
	}
	a.Ret()
	f.adapterEndOff = a.Len()
	if diagnosticsEnabled && f.stats != nil {
		f.stats.NativeSize.HostAdapterBytes = a.Len()
	}
	return adapterCall
}

// emitRegABI emits a register-ABI function as [host adapter | internal entry].
// The adapter at offset 0 keeps the wrapper ABI working for exports/host calls;
// the internal entry takes args in GP/V registers and returns numeric results
// in independent GP/FP banks.
// Returns the internal entry's offset within the function's code.
func (f *fn) emitRegABI(c *wasm.Func, hostAdapter bool, localScores []uint32, hasFloatConst bool, intConstHints *funcHintView) (int, error) {
	a := f.a
	np, rN := f.nParams, len(f.ft.Results)

	// Host→internal adapter (offset 0): in X0=serArgs, X1=linMem, X2=trap,
	// X3=results; loads args into registers, calls the internal entry, stores the
	// register results.
	gp, fp := 0, 0
	var adapterCall int
	cachedAdapter := false
	if hostAdapter {
		if f.sc != nil {
			if template, returnOff, endOff, ok := f.sc.adapterTemplate.lookup(f.ft, f.memSizeReg); ok {
				a.B = append(a.B, template...)
				f.adapterReturnOff = returnOff
				f.adapterEndOff = endOff
				adapterCall = returnOff - 4
				cachedAdapter = true
				if f.gcFrameRoots != nil {
					f.gcFrameRoots.AdapterReturnOffset = uint32(returnOff)
				}
				if diagnosticsEnabled && f.stats != nil {
					f.stats.NativeSize.HostAdapterBytes = endOff
					f.stats.NativeSize.AdapterToInternalPaddingBytes = len(template) - endOff
				}
			}
		}
		if !cachedAdapter {
			adapterCall = f.emitHostAdapter(np, rN)
		}
	}

	// Internal entry (frameless): linMemReg (linMem) is inherited from the caller —
	// every wasm function keeps it pinned, and the adapter establishes it at the
	// Go boundary — and the trap cell pointer lives in basedata, so the entry
	// carries no environment setup at all (WARP's model). Args in GP/V regs.
	if hostAdapter && !cachedAdapter {
		beforeAlign := a.Len()
		if f.adapterBacklink {
			// A 4-byte backlink directly below the internal entry holds its
			// distance from this function's offset-0 adapter. An internal funcref
			// descriptor names only the internal entry; a wrapper-ABI caller
			// tail-enters such a target through the adapter (see
			// emitTailWrapperToAdapterJump). The adapter ends in RET, so the word
			// is never executed, and cached adapter templates carry it along.
			log2 := f.policy.InternalAlignLog2
			if log2 == 0 {
				log2 = 4
			}
			for range alignmentPadding(a.Len()+4, log2) / 4 {
				a.Nop()
			}
			a.B = binary.LittleEndian.AppendUint32(a.B, uint32(a.Len()+4))
		} else {
			f.alignCode(f.policy.InternalAlignLog2)
		}
		if diagnosticsEnabled && f.stats != nil {
			f.stats.NativeSize.AdapterToInternalPaddingBytes = a.Len() - beforeAlign
		}
	}
	internalOff := a.Len()
	f.beginNativeImportVariant()
	if f.makesCalls {
		a.StpPre(FP, LR, SP, -16) // save FP/LR frame record (BL clobbers LR)
		a.AddImm64(FP, SP, 0)     // MOV X29, SP
	}
	f.subRspAt = a.Len()
	a.Movz64(X16, 0, 0)
	a.Movk64(X16, 0, 1)
	a.SubSPReg(X16)
	// X16 (backend scratch) is the fence scratch: the reg-ABI args occupy X0-X7 at
	// entry, so an arg register cannot double as scratch here (amd64 used RSI, which
	// is not one of its arg registers).
	f.emitStackFenceCheck(linMemReg, X16)
	if f.trapCellReg != regNone {
		f.ld64(f.trapCellReg, linMemReg, -int32(offTrapCellPtr))
	}
	f.emitInterruptCheck(false)
	f.entryTrapEnd = a.Len()
	if f.cacheImportDispatch {
		f.ld64(X25, linMemReg, -int32(offImportDispatchPtr))
	}
	if f.cacheNativeImportTarget {
		f.ld64(X24, X25, coreruntime.ImportDispatchCodePtrOffset)
		f.a.AddImm64(X24, X24, coreruntime.NativeScalarLeafRegisterEntryOffset)
	}
	gp, fp = 0, 0
	moves := f.tmpMoves[:0]
	for i := 0; i < np; i++ {
		mt := f.localType[i]
		if mt.isFloat() {
			src := fpArgRegs[fp]
			if pr, isFloat, ok := f.pinReg(i); ok && isFloat {
				a.FMov(pr, src, mt == mtF64)
			} else {
				a.FStoreDisp(SP, f.localOff(i), src, mt == mtF64)
			}
			fp++
		} else if f.scalarSummary.Eligible {
			// Transfer the untouched incoming register to shared ownership. There
			// is no valid frame copy until the shared state explicitly stores one.
			if f.canonicalI32Local(i) {
				a.MovReg32(intArgRegs[gp], intArgRegs[gp])
				f.stats.peep("entry-i32-param-canonicalize")
			}
		} else if pr, isFloat, ok := f.pinReg(i); ok && !isFloat {
			if f.canonicalI32Local(i) {
				a.MovReg32(intArgRegs[gp], intArgRegs[gp])
				f.stats.peep("entry-i32-param-canonicalize")
			}
			if pr != intArgRegs[gp] {
				moves = append(moves, regMove{dst: pr, src: intArgRegs[gp]})
			}
		} else {
			if f.canonicalI32Local(i) {
				a.MovReg32(intArgRegs[gp], intArgRegs[gp])
				f.stats.peep("entry-i32-param-canonicalize")
			}
			f.st64(SP, f.localOff(i), intArgRegs[gp])
		}
		if !mt.isFloat() {
			gp++
		}
	}
	var checkMoves func()
	if regallocCheckEnabled {
		checkMoves = f.checkBeginRegMoves(moves, false)
		defer checkMoves()
	}
	swapChains := resolveRegMovesWindow(moves,
		func(dst, src Reg) { a.MovReg64(dst, src) },
		func(x, y Reg) {
			a.MovReg64(X16, x)
			a.MovReg64(x, y)
			a.MovReg64(y, X16)
		},
		func(a, b, c Reg) {
			f.a.MovReg64(X16, a)
			f.a.MovReg64(a, b)
			f.a.MovReg64(b, c)
			f.a.MovReg64(c, X16)
		})
	if regallocCheckEnabled {
		checkMoves()
	}
	f.stats.peepN("machine-swap-chain", swapChains)
	f.tmpMoves = moves[:0]
	f.zeroDeclaredLocals(localScores)
	if hasFloatConst {
		f.preloadFloatConsts(c.BodyBytes)
	}
	f.preloadV128Consts(c.BodyBytes)
	f.derivePinnedGlobals()
	f.preloadLoopIntConsts(intConstHints)
	if f.memSizeReg == X17 {
		// X17 is caller-clobbered backend scratch, so establish this leaf-local
		// cache after entry setup and immediately before the body that consumes it.
		f.ld64(X17, linMemReg, -bdCurBytes)
	}
	if f.memLimitReg != regNone {
		// The register-ABI internal entry can be reached directly from another Wasm
		// function, so derive the function-local adjusted limit here rather than in
		// the host adapter alone.
		f.a.SubImm64(f.memLimitReg, f.memSizeReg, uint32(f.memLimitExtent))
	}
	if err := f.runBody(c); err != nil {
		return 0, err
	}
	// Body results are canonical; terminal reloads may reuse cache registers.
	// Attempt cleanup owns observer restoration if return emission panics.
	var returnWrites regallocWriteMask
	if regallocCheckEnabled {
		returnWrites = f.checkTerminalWrites()
	}
	f.storePinnedGlobals(true) // write dirty value-pinned globals back to their cells (all returns land here)
	if rN == 1 && !f.singleRegResult {
		rt := mtOf(f.ft.Results[0])
		if rt.isFloat() {
			a.FLoadDisp(0, SP, f.spillOff(0), rt == mtF64) // result -> V0
		} else {
			f.ld64(X0, SP, f.spillOff(0)) // result -> X0
		}
	} else if rN == 2 {
		if preparedDirectFloatSupported && mtOf(f.ft.Results[0]).isFloat() && !mtOf(f.ft.Results[1]).isFloat() {
			a.FLoadDisp(0, SP, f.spillOff(0), mtOf(f.ft.Results[0]) == mtF64)
			f.ld64(X0, SP, f.spillOff(1))
		} else if preparedDirectFloatSupported && !mtOf(f.ft.Results[0]).isFloat() && mtOf(f.ft.Results[1]).isFloat() {
			f.ld64(X0, SP, f.spillOff(0))
			a.FLoadDisp(0, SP, f.spillOff(1), mtOf(f.ft.Results[1]) == mtF64)
		} else if preparedDirectFloatSupported && mtOf(f.ft.Results[0]).isFloat() {
			for i, typ := range f.ft.Results {
				a.FLoadDisp(Reg(i), SP, f.spillOff(i), mtOf(typ) == mtF64)
			}
		} else {
			f.ld64(X0, SP, f.spillOff(0))
			f.ld64(X1, SP, f.spillOff(1))
		}
	}
	if preparedDirectFloatSupported && rN > 2 && sigIsFloatOnly(f.ft) {
		for i, typ := range f.ft.Results {
			a.FLoadDisp(Reg(i), SP, f.spillOff(i), mtOf(typ) == mtF64)
		}
	} else if registerQuadResultsSupported && rN > 2 {
		gp, fp := 0, 0
		for i, typ := range f.ft.Results {
			if mtOf(typ).isFloat() {
				a.FLoadDisp(Reg(fp), SP, f.spillOff(i), mtOf(typ) == mtF64)
				fp++
			} else {
				f.ld64([]Reg{X0, X1, X2, X3, X4, X5, X6, X7}[gp], SP, f.spillOff(i))
				gp++
			}
		}
	}
	// singleRegResult: every exit already produced the result in X0/V0.
	// No trap-slot protocol on return: the runtime zeroes the trap cell before
	// entry, and a trap never returns through here (handler-jump).
	if f.memSizeReg == X17 {
		// Regional leaves can reuse X27. Restore the module bound for direct
		// callers, including when this leaf grew an alias of primary memory.
		f.ld64(X27, linMemReg, -bdCurBytes)
	}
	f.addRspAt = a.Len()
	a.Movz64(X16, 0, 0) // undo the frame; imm patched after body
	a.Movk64(X16, 0, 1)
	a.AddSPReg(X16)
	if f.makesCalls {
		a.LdpPost(FP, LR, SP, 16) // restore FP/LR
	}
	a.Ret()
	if regallocCheckEnabled {
		f.checkRestoreWrites(returnWrites)
	}
	if profileEnabled {
		f.collectProfileSources(internalOff)
	}
	f.emitTrapStubs()
	f.emitPhasePadding()

	f.elideRegisterOnlyFrame()
	if err := f.patchFrameAdjusts(); err != nil {
		return 0, err
	}
	if hostAdapter {
		if !cachedAdapter {
			f.patchBranch26(adapterCall, internalOff)
			if f.sc != nil {
				f.sc.adapterTemplate.observe(f.ft, f.memSizeReg, f.a.B[:internalOff], f.adapterReturnOff, f.adapterEndOff)
			}
		}
		if diagnosticsEnabled && f.stats != nil {
			f.stats.NativeSize.HostAdapterShapeHash = shared.AdapterShapeHash(f.a.B[:f.stats.NativeSize.HostAdapterBytes], adapterCall, 4)
			f.stats.NativeSize.HostAdapterTailBytes = f.stats.NativeSize.HostAdapterBytes - f.adapterReturnOff
			f.stats.NativeSize.HostAdapterTailShapeHash = shared.AdapterShapeHash(f.a.B[f.adapterReturnOff:f.stats.NativeSize.HostAdapterBytes], -1, 0)
		}
	}
	return internalOff, nil
}

func (f *fn) emitPhasePadding() {
	for range f.phasePadWords {
		f.a.Nop()
	}
	f.phasePadWords = 0
}

// epilogue: copy results from their canonical slots to the results buffer, restore
// FP/LR (call-making functions), and return. Every reaching path (fallthrough end,
// return, br to the function label) has already placed the results in slots
// [0, resultN).
func (f *fn) epilogue() {
	// Every reaching path has already placed results in canonical slots.
	var returnWrites regallocWriteMask
	if regallocCheckEnabled {
		returnWrites = f.checkTerminalWrites()
	}
	a := f.a
	f.storeModuleGlobals(X2)     // Go exit: module-pinned registers → cells
	f.ld64(X1, SP, frResultsOff) // results ptr (X1 is free at the epilogue)
	resSlot := 0
	out := int32(0)
	for _, rt := range f.ft.Results {
		if mtOf(rt) == mtV128 {
			a.VMovdquLoadDisp(0, SP, f.spillOff(resSlot))
			a.VMovdquStoreDisp(X1, out, 0)
			resSlot += 2
		} else {
			f.ld64(X0, SP, f.spillOff(resSlot))
			f.st64(X1, out, X0)
			resSlot++
		}
		out += abiValSize(rt)
	}
	f.addRspAt = a.Len()
	a.Movz64(X16, 0, 0) // undo the frame; imm patched after body
	a.Movk64(X16, 0, 1)
	a.AddSPReg(X16)
	if f.makesCalls {
		a.LdpPost(FP, LR, SP, 16) // restore FP/LR
	}
	a.Ret()
	if regallocCheckEnabled {
		f.checkRestoreWrites(returnWrites)
	}
}

func abiValOff(ts []wasm.ValType, idx int) int32 {
	off := int32(0)
	for i := 0; i < idx; i++ {
		off += abiValSize(ts[i])
	}
	return off
}

func abiValSize(t wasm.ValType) int32 {
	if wasm.EqualValType(t, wasm.V128) {
		return 16
	}
	return 8
}

func mtOf(t wasm.ValType) machineType {
	switch {
	case wasm.EqualValType(t, wasm.I32):
		return mtI32
	case wasm.EqualValType(t, wasm.I64):
		return mtI64
	case wasm.EqualValType(t, wasm.F32):
		return mtF32
	case wasm.EqualValType(t, wasm.F64):
		return mtF64
	case wasm.EqualValType(t, wasm.V128):
		return mtV128
	case t.Kind() == wasm.ValRef:
		return mtI64
	}
	return mtNone
}

func countLocals(params []wasm.ValType, locals wasm.Locals) (int, error) {
	n := len(params)
	for _, run := range locals.Runs {
		n += int(run.Count)
	}
	return n, nil
}

// ehFrameShape sizes one function's exception records from its body. Modules
// built without body bytes keep the historical fixed reservation.
func ehFrameShape(sc *scratch, body []byte) (shared.EHFrameShape, error) {
	if len(body) == 0 {
		return shared.EHFrameShape{TryRecords: legacyEHTryRecords, RootRecords: legacyEHRootRecords}, nil
	}
	return shared.ScanEHFrameShape(&sc.classifier, body)
}

// zeroEHGCRootLanes clears the GC lanes of every exception root slot at entry.
// Those lanes are fixed collector roots at every safepoint of the frame, before
// any try_table has initialized its slot.
func (f *fn) zeroEHGCRootLanes() {
	if f.ehRootCap == 0 || f.gcFrameRoots == nil || !f.gcFrameRoots.HasFixedOffsets() {
		return
	}
	for root := 0; root < f.ehRootCap; root++ {
		for lane := shared.EHGCLaneBase; lane < shared.EHPayloadLanes; lane++ {
			f.st64(SP, f.ehRootOff(root)+8+int32(lane)*8, ZR)
		}
	}
}

//go:build arm64

package arm64

import (
	"fmt"
	"os"
	"sort"

	railcore "github.com/wago-org/wago/src/core/compiler/backend/railshot"
	"github.com/wago-org/wago/src/core/compiler/backend/railshot/shared"
	"github.com/wago-org/wago/src/core/compiler/wasm"
	a64 "github.com/wago-org/wago/src/core/encoder/arm64"
	"github.com/wago-org/wago/src/core/runtime"
	"github.com/wago-org/wago/src/core/runtime/abi"
)

// refreshCachedMemoryBoundAfterExternalCall reestablishes the memory-zero
// bounds cache after a continuation resumes from code outside this compilation
// context. The external code may have grown an aliased memory, and a
// cross-instance continuation must read from the restored caller basedata.
func (f *fn) refreshCachedMemoryBoundAfterExternalCall() {
	if f.memSizeReg != regNone {
		f.loadMemoryCache()
	}
}

// regABIEnabled turns on the register-based internal-call ABI (default on;
// WAGO_ARM64_NOREGABI=1 forces the wrapper ABI everywhere, for A/B measurement).
var regABIEnabled = os.Getenv("WAGO_ARM64_NOREGABI") != "1"

// noStackFence skips the per-entry stack-overflow fence check (A/B measurement).
var noStackFence = os.Getenv("WAGO_ARM64_NOFENCE") == "1"

// noStackReg disables the WARP STACK_REG lazy local model (reverts to spill-all/
// reload-all around calls, no branch reconcile) — A/B measurement.
var noStackReg = os.Getenv("WAGO_ARM64_NOSTACKREG") == "1"

// Function calls. Internal (wasm→wasm) calls use wago's WasmWrapper ABI: the
// arguments and result slots live in a native-stack buffer at SP; the callee is
// entered with X0=args, X1=linMem, X2=trap, X3=results — exactly what the
// prologue expects. Ported from WARP's call lowering but retargeted to wago's
// ABI/runtime (host imports adapt to wago's re-entry model, not WARP's
// synchronous native calls — the no-cgo constraint).

// callReloc records a Bl (BL) site whose imm26 must be patched to point at the
// target local function's entry once the module is laid out.
type callReloc struct {
	at       uint32 // byte offset of the BL instruction within this function's code
	target   uint32 // target function index; gcObject uses the positive helper-fallback byte delta
	internal bool   // target the callee's register-ABI internal entry (else offset 0)
	gcObject bool   // target the module checked-object leaf (not a local function)
}

// callRelocTable stores every module relocation in source-function order. One
// pointer-free offset per function replaces a retained slice header per
// function; function slices are reconstructed only while finalizing the module.
type callRelocTable struct {
	offsets       []uint32
	data          []callReloc
	next          uint32
	results       []funcResult
	states        []workerState
	gcObjectEntry int // appended checked-object leaf; zero if not emitted
}

func parallelCallRelocTable(results []funcResult, states []workerState) callRelocTable {
	return callRelocTable{results: results, states: states}
}

func newCallRelocTable(functions, capacity int) callRelocTable {
	if functions == 0 {
		return callRelocTable{}
	}
	return callRelocTable{
		offsets: make([]uint32, functions+1),
		data:    make([]callReloc, 0, capacity),
	}
}

func (t *callRelocTable) appendFunction(index int, relocs []callReloc) bool {
	if index < 0 || uint64(index) != uint64(t.next) || index+1 >= len(t.offsets) || uint64(len(t.data))+uint64(len(relocs)) > uint64(^uint32(0)) {
		return false
	}
	t.data = append(t.data, relocs...)
	t.offsets[index+1] = uint32(len(t.data))
	t.next++
	return true
}

// Hot finalization loops intentionally hoist the mode test and call these
// accessors directly. A combined accessor did not inline and cost 2.55% on the
// native many-functions compile benchmark.
func (t callRelocTable) serialFunction(index int) []callReloc {
	if index < 0 || index+1 >= len(t.offsets) {
		return nil
	}
	return t.data[t.offsets[index]:t.offsets[index+1]]
}

func (t callRelocTable) parallelFunction(index int) []callReloc {
	if index < 0 || index >= len(t.results) {
		return nil
	}
	r := t.results[index]
	if r.layoutFlags&layoutOmitted != 0 || int(r.worker) >= len(t.states) {
		return nil
	}
	return t.states[int(r.worker)].relocs[int(r.relocStart):int(r.relocEnd)]
}

func (t callRelocTable) functions() int {
	if t.results != nil {
		return len(t.results)
	}
	if len(t.offsets) == 0 {
		return 0
	}
	return len(t.offsets) - 1
}

const invalidCallRelocField = ^uint32(0)

func (f *fn) compactCallRelocField(value int) uint32 {
	if value < 0 || uint64(value) >= uint64(invalidCallRelocField) {
		f.setRepresentationLimit(functionRepresentationCallReloc)
		return 0
	}
	return uint32(value)
}

func (f *fn) newCallReloc(at, target int, internal bool) callReloc {
	return callReloc{
		at:       f.compactCallRelocField(at),
		target:   f.compactCallRelocField(target),
		internal: internal,
	}
}

// intArgRegs is the integer argument/result register order for the internal
// register-call ABI (our own convention, not the C ABI). X0/X1 carry args/linMem;
// X19-X23 hold pinned locals; linMemReg holds linMem. The single result returns in X0
// (AAPCS64 return register, also arg 0).
var intArgRegs = []Reg{X0, X1, X2, X3, X4, X5, X6, X7}
var fpArgRegs = []Reg{0, 1, 2, 3, 4, 5, 6, 7} // V0..V7; single float result returns in V0.

func isIntValType(t wasm.ValType) bool {
	return wasm.EqualValType(t, wasm.I32) || wasm.EqualValType(t, wasm.I64)
}

func preparedDirectIntSig(ft *wasm.CompType) bool {
	if len(ft.Params) > len(intArgRegs) || len(ft.Results) > len(intArgRegs) || len(ft.Results) > 2 && !registerQuadResultsSupported {
		return false
	}
	for _, typ := range ft.Params {
		if !isIntValType(typ) {
			return false
		}
	}
	for _, typ := range ft.Results {
		if !isIntValType(typ) {
			return false
		}
	}
	return true
}

func preparedDirectFloatSig(ft *wasm.CompType) bool {
	if len(ft.Params) > len(fpArgRegs) || len(ft.Results) > len(fpArgRegs) {
		return false
	}
	for _, typ := range ft.Params {
		if !isFloatValType(typ) {
			return false
		}
	}
	for _, typ := range ft.Results {
		if !isFloatValType(typ) {
			return false
		}
	}
	return true
}

func preparedDirectMixedSig(ft *wasm.CompType) bool {
	if len(ft.Params) > 4 || len(ft.Results) > 4 || len(ft.Results) > 2 && !sigHasMixedWideResults(ft) {
		return false
	}
	for _, typ := range ft.Params {
		if !isIntValType(typ) && !isFloatValType(typ) {
			return false
		}
	}
	for _, typ := range ft.Results {
		if !isIntValType(typ) && !isFloatValType(typ) {
			return false
		}
	}
	return !preparedDirectIntSig(ft) && !preparedDirectFloatSig(ft)
}

func isFloatValType(t wasm.ValType) bool {
	return wasm.EqualValType(t, wasm.F32) || wasm.EqualValType(t, wasm.F64)
}

func sigIsIntOnly(ft *wasm.CompType) bool {
	for _, t := range ft.Params {
		if !isIntValType(t) {
			return false
		}
	}
	for _, t := range ft.Results {
		if !isIntValType(t) {
			return false
		}
	}
	return true
}

func sigIsFloatOnly(ft *wasm.CompType) bool {
	for _, typ := range ft.Params {
		if !isFloatValType(typ) {
			return false
		}
	}
	for _, typ := range ft.Results {
		if !isFloatValType(typ) {
			return false
		}
	}
	return true
}

// sigHasMixedWideResults is the two-GP/two-FP register result shape also used
// by the bounded mixed prepared bridge. Results may interleave in Wasm order.
func sigHasMixedWideResults(ft *wasm.CompType) bool {
	if !preparedDirectFloatSupported || len(ft.Results) < 3 || len(ft.Results) > 4 {
		return false
	}
	gp, fp := 0, 0
	for _, typ := range ft.Results {
		switch {
		case isIntValType(typ):
			gp++
		case isFloatValType(typ):
			fp++
		default:
			return false
		}
	}
	return gp > 0 && fp > 0 && gp <= 2 && fp <= 2
}

// sigFitsRegABI reports whether a signature can use the register ABI: integer-
// and float params are assigned to separate GP/V banks; one result returns in
// X0/V0; two results use independent GP/FP banks, and integer-only signatures
// can return up to eight values in X0..X7; float-only signatures can likewise
// return in V0..V7. Mixed results use up to two registers in each bank.
func sigFitsRegABI(ft *wasm.CompType) bool {
	if len(ft.Results) > len(intArgRegs) && !(preparedDirectFloatSupported && len(ft.Results) <= len(fpArgRegs) && sigIsFloatOnly(ft)) ||
		len(ft.Results) > 2 && !registerQuadResultsSupported {
		return false
	}
	if len(ft.Results) > 2 && !sigIsIntOnly(ft) && !(preparedDirectFloatSupported && sigIsFloatOnly(ft)) && !sigHasMixedWideResults(ft) {
		return false
	}
	if len(ft.Results) == 2 && !((isIntValType(ft.Results[0]) && isIntValType(ft.Results[1])) ||
		(preparedDirectFloatSupported &&
			(isIntValType(ft.Results[0]) || isFloatValType(ft.Results[0])) &&
			(isIntValType(ft.Results[1]) || isFloatValType(ft.Results[1])))) {
		return false
	}
	gp, fp := 0, 0
	for _, t := range ft.Params {
		switch {
		case isIntValType(t):
			gp++
		case isFloatValType(t):
			fp++
		default:
			return false
		}
	}
	if gp > len(intArgRegs) || fp > len(fpArgRegs) {
		return false
	}
	for _, t := range ft.Results {
		if !isIntValType(t) && !isFloatValType(t) {
			return false
		}
	}
	return true
}

// sigFitsReferenceResultRegABI is the staged typed-tail extension of the native
// register ABI. It admits one funcref result in X0 with numeric parameters only.
// The descriptor pointer remains owned by the instance's bounded descriptor arena;
// no GC-managed reference or foreign wrapper result is admitted by this shape.
func sigFitsReferenceResultRegABI(ft *wasm.CompType) bool {
	if ft == nil || len(ft.Results) != 1 || !wasm.EqualValType(ft.Results[0], wasm.FuncRef) || len(ft.Params) > len(intArgRegs)+len(fpArgRegs) {
		return false
	}
	gp, fp := 0, 0
	for _, typ := range ft.Params {
		switch {
		case isIntValType(typ):
			gp++
		case isFloatValType(typ):
			fp++
		default:
			return false
		}
	}
	// Descriptor publication uses the cross-architecture staged classifier,
	// whose GP bank is capped at seven. Keep ARM64 aligned so eight-GP shapes
	// retain the wrapper fallback instead of requiring an unpublished internal tag.
	return gp < len(intArgRegs) && fp <= len(fpArgRegs)
}

func stagedTailRegisterABI(ft *wasm.CompType, staged bool) bool {
	return sigFitsRegABI(ft) || staged && sigFitsReferenceResultRegABI(ft)
}

func (f *fn) tailCallerUsesRegisterABI() bool {
	return f.opt(optRegABI) && stagedTailRegisterABI(f.ft, f.stagedTailDescriptors)
}

func tailResultABICompatible(a, b []wasm.ValType) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		// Validation has already proved result subtyping. Native tail transfer only
		// needs the same physical register/slot class; all references are one i64
		// descriptor word even when their heap type or nullability differs.
		if mtOf(a[i]) != mtOf(b[i]) {
			return false
		}
	}
	return true
}

func sigFitsDirectCrossTailABI(ft *wasm.CompType) bool {
	return sigFitsRegABI(ft) && len(ft.Results) <= 2
}

func (f *fn) callOp(r *wasm.Reader) error {
	idx, err := r.U32()
	if err != nil {
		return err
	}
	ft, ok := f.functionSignature(idx)
	if !ok {
		return fmt.Errorf("call: unknown function %d", idx)
	}
	imported := f.importedFunctionCount()
	if int(idx) < imported && f.customInstructions != nil {
		if custom, ok := f.customInstructions[idx]; ok && (pluginARM64Lowering(custom) != nil || instructionRecipeEligible(custom)) {
			// Native lowering replaces the source call without a return address.
			// Consume its mask so later calls retain their source-site liveness.
			f.consumeGCFrameCallsite()
			return f.emitCustomInstruction(custom, ft)
		}
	}
	// Auto-inlining (WAGO_INLINE): splice a straight-line leaf callee's body here
	// instead of emitting a call. The frame reserved the callee's locals past
	// f.nLocals in this caller; the splice binds params, zeroes declared locals, and
	// runs the body with localBase set. Straight-line callees touch no control frame,
	// so this is a pure operand-stack/local transform.
	if !f.inlineTargets.empty() {
		if t := f.inlineTargets.target(int(idx)); t != nil {
			if _, ok := f.inlineBase[int(idx)]; ok && (!t.recursive() || f.inlineDepth == 0) && !(t.inlineInLoopIsRegressive() && f.inCallSiteLoop()) {
				f.consumeGCFrameCallsite()
				return f.inlineCall(t)
			}
		}
	}
	if int(idx) < imported {
		if f.importBindings != nil && int(idx) < len(f.importBindings) && (f.importBindings[idx].Dynamic || f.importBindings[idx].CrossInstance) {
			return f.emitDynamicHostOrCrossInstance(f.importBindings[idx], ft)
		}
		// A module with any returning host import uses the synchronous control
		// frame for ALL its host calls, so the async log and the control frame
		// never both occupy offCustomCtx. Otherwise void imports keep the cheaper
		// async log-and-replay path.
		if f.syncHostCalls || len(ft.Results) != 0 {
			return f.callHostSync(int(idx), ft) // synchronous re-entry
		}
		return f.callHost(int(idx), ft) // void: async log-and-replay
	}
	// `call f; local.set x` fusion: an int-only register-ABI call whose single
	// int result feeds a pinned local moves X0 straight into the local's
	// register — no intermediate result register, no separate set lowering.
	hint := -1
	if f.opt(optRegABI) && sigFitsRegABI(ft) && sigIsIntOnly(ft) && len(ft.Results) == 1 {
		r2 := *r // peek past the call without committing
		if b, err := r2.Byte(); err == nil && b == 0x21 {
			if x, err := r2.U32(); err == nil {
				if pr, isFloat, ok := f.pinReg(int(x)); ok && !isFloat && pr != regNone {
					// All operand-stack refs to x are flushed to slots by the call
					// sequence itself, so skipping setLocal's realizeLocalRefs is safe.
					f.stats.peep("call-localset-fuse")
					hint = int(x)
					if err := r.JumpTo(r2.Offset()); err != nil {
						return err
					}
				}
			}
		}
	}
	return f.callInternal(int(idx)-imported, ft, hint)
}

// returnCall lowers local proper-tail calls. Register-ABI targets receive their
// arguments directly in X/V registers; wider signatures use the fixed basedata
// tail bank and jump to the target wrapper. Both paths release the current native
// frame before branching, so recursive tail chains remain stack bounded.
func (f *fn) returnCall(r *wasm.Reader) error {
	// Tail transfer discards the operand prefix; preserve its traps first.
	f.materializePendingTraps()
	idx, err := r.U32()
	if err != nil {
		return err
	}
	ft, ok := f.functionSignature(idx)
	if !ok {
		return fmt.Errorf("return_call: unknown function %d", idx)
	}
	if !tailResultABICompatible(f.ft.Results, ft.Results) {
		return fmt.Errorf("return_call: target %d result shape differs from caller", idx)
	}
	imported := f.importedFunctionCount()
	if int(idx) < imported {
		if f.importBindings != nil && int(idx) < len(f.importBindings) {
			binding := f.importBindings[idx]
			if binding.Dynamic || binding.CrossInstance {
				if !sigFitsDirectCrossTailABI(f.ft) || !sigFitsDirectCrossTailABI(ft) {
					return fmt.Errorf("return_call: imported target %d requires unsupported cross-instance tail ABI", idx)
				}
				return f.emitTailDynamicImportJump(ft, binding)
			}
		}
		var callErr error
		if f.syncHostCalls || len(ft.Results) != 0 {
			callErr = f.callHostSync(int(idx), ft)
		} else {
			callErr = f.callHost(int(idx), ft)
		}
		if callErr != nil {
			return callErr
		}
		return f.opReturn()
	}
	f.stats.call("tail-direct")
	target := int(idx) - imported
	callerRegisterABI := stagedTailRegisterABI(f.ft, f.stagedTailDescriptors)
	targetRegisterABI := stagedTailRegisterABI(ft, f.stagedTailDescriptors)
	if f.opt(optRegABI) && targetRegisterABI {
		jump := func() {
			site := f.a.Branch()
			f.relocs = append(f.relocs, f.newCallReloc(site, target, true))
		}
		if callerRegisterABI {
			f.emitTailRegisterJump(ft, jump)
		} else {
			// Every return_call target has an offset-zero adapter, so a wrapper
			// caller enters it with the wrapper ABI and its own results buffer.
			// Unlike a trampoline record, the adapter record is discarded when
			// the target tails back to a wrapper, keeping tail cycles bounded.
			if slots := funcTypeSlots(ft.Params); slots > abi.TailArgsSlots {
				return fmt.Errorf("return_call: target %d requires %d wrapper argument slots, limit %d", idx, slots, abi.TailArgsSlots)
			}
			f.emitTailWrapperJump(ft, func() {
				site := f.a.Branch()
				f.relocs = append(f.relocs, f.newCallReloc(site, target, false))
			})
		}
	} else {
		if slots := funcTypeSlots(ft.Params); slots > abi.TailArgsSlots {
			return fmt.Errorf("return_call: target %d requires %d wrapper argument slots, limit %d", idx, slots, abi.TailArgsSlots)
		}
		f.emitTailWrapperJump(ft, func() {
			site := f.a.Branch()
			f.relocs = append(f.relocs, f.newCallReloc(site, target, false))
		})
	}
	f.unreachable = true
	return nil
}

func (f *fn) discardEHHandlersForTail() {
	if f.ehTryDepth != 0 {
		// A tail transfer discards every record in this frame. Use the shared
		// large-frame-safe restore instead of addressing record zero from SP.
		f.restorePreviousEHHandler(f.ehRecordOff(0))
	}
}

func (f *fn) emitTailFrameRelease() {
	f.discardEHHandlersForTail()
	at := f.a.Len()
	f.tailFrameSites = append(f.tailFrameSites, at)
	f.a.Movz64(X16, 0, 0)
	f.a.Movk64(X16, 0, 1)
	f.a.AddSPReg(X16)
	if f.makesCalls {
		f.a.LdpPost(FP, LR, SP, 16)
	}
}

func (f *fn) emitTailRegisterJump(ft *wasm.CompType, emitJump func()) {
	p := len(ft.Params)
	roots := f.rootsBottomToTop()
	if len(roots) < p {
		panic("arm64 tail call operand underflow")
	}
	types := make([]machineType, len(roots))
	for i, root := range roots {
		types[i] = rootMachineType(root)
	}
	f.flush()
	f.storePinnedGlobals(false)
	f.storeModuleGlobals(X16)
	argBase := len(types) - p
	gp, fp := 0, 0
	for i, typ := range ft.Params {
		slot := slotOfLogicalTypes(types, argBase+i)
		mt := mtOf(typ)
		if mt.isFloat() {
			f.fld(fpArgRegs[fp], SP, f.spillOff(slot), mt == mtF64)
			fp++
		} else {
			f.ld64(intArgRegs[gp], SP, f.spillOff(slot))
			gp++
		}
	}
	f.emitTailFrameRelease()
	emitJump()
}

func (f *fn) emitTailWrapperToRegisterJump(ft *wasm.CompType, emitJump func()) {
	p := len(ft.Params)
	roots := f.rootsBottomToTop()
	if len(roots) < p {
		panic("arm64 tail wrapper-to-register operand underflow")
	}
	types := make([]machineType, len(roots))
	for i, root := range roots {
		types[i] = rootMachineType(root)
	}
	f.flush()
	f.storePinnedGlobals(false)
	f.storeModuleGlobals(X16)
	argBase := len(types) - p
	gp, fp := 0, 0
	for i, typ := range ft.Params {
		slot := slotOfLogicalTypes(types, argBase+i)
		mt := mtOf(typ)
		if mt.isFloat() {
			f.fld(fpArgRegs[fp], SP, f.spillOff(slot), mt == mtF64)
			fp++
		} else {
			f.ld64(intArgRegs[gp], SP, f.spillOff(slot))
			gp++
		}
	}
	f.ld64(X12, SP, frResultsOff)
	f.emitTailFrameRelease()
	f.a.SubSP64(32)
	f.st64(SP, 0, LR)
	f.st64(SP, 8, X12)
	trampolineADR := f.a.Adr(LR)
	f.recordPCRelative(trampolineADR)
	emitJump()

	trampoline := f.a.Len()
	f.a.PatchAdr(trampolineADR, trampoline)
	f.ld64(X3, SP, 8)
	if len(ft.Results) > 0 {
		if isFloatValType(ft.Results[0]) {
			f.a.FStoreDisp(X3, 0, 0, wasm.EqualValType(ft.Results[0], wasm.F64))
		} else {
			f.st64(X3, 0, X0)
		}
	}
	if len(ft.Results) > 1 {
		f.st64(X3, 8, X1)
	}
	// The register-ABI target returns module pins in registers, but this
	// trampoline returns in place of the wrapper-ABI caller's epilogue, whose
	// callers expect coherent cells.
	f.storeModuleGlobals(X16)
	f.ld64(LR, SP, 0)
	f.a.AddSP64(32)
	f.a.Ret()
}

// emitTailWrapperToAdapterJump tail-enters the internal descriptor target in
// X17 from a wrapper-ABI caller. Its register-ABI internal entry would return in
// registers to a caller that expects a results buffer, so the transfer enters
// the target's offset-0 adapter instead, found through the backlink word below
// the internal entry, exactly like a direct wrapper-to-register return_call.
// The target's own later tails discard the adapter's record, so mixed
// register/wrapper tail loops stay stack-bounded.
func (f *fn) emitTailWrapperToAdapterJump(ft *wasm.CompType) {
	f.emitTailWrapperJump(ft, func() {
		f.ld32(X16, X17, -4)
		f.a.Sub64(X17, X17, X16)
		f.a.Br(X17)
	})
}

func (f *fn) emitTailWrapperJump(ft *wasm.CompType, emitJump func()) {
	p := len(ft.Params)
	roots := f.rootsBottomToTop()
	if len(roots) < p {
		panic("arm64 tail wrapper operand underflow")
	}
	types := make([]machineType, len(roots))
	for i, root := range roots {
		types[i] = rootMachineType(root)
	}
	f.flush()
	f.storePinnedGlobals(false)
	f.storeModuleGlobals(X16)
	f.a.MovReg64(X0, linMemReg)
	f.leaDisp(X0, X0, -int32(abi.TailArgsOffset), true)
	argBase := len(types) - p
	dstSlot := 0
	for i, typ := range ft.Params {
		srcSlot := slotOfLogicalTypes(types, argBase+i)
		n := mtOf(typ).stackSlots()
		for j := 0; j < n; j++ {
			f.ld64(X16, SP, f.spillOff(srcSlot+j))
			f.st64(X0, int32((dstSlot+j)*8), X16)
		}
		dstSlot += n
	}
	f.ld64(X2, linMemReg, -int32(abi.TrapCellPtrOffset))
	f.a.MovReg64(X1, linMemReg)
	if !f.tailCallerUsesRegisterABI() {
		f.ld64(X3, SP, frResultsOff)
		f.emitTailFrameRelease()
		emitJump()
		return
	}

	f.emitTailFrameRelease()
	adapterPC := f.a.Adr(X16)
	f.recordPCRelative(adapterPC)
	f.patchAdr(adapterPC, f.adapterReturnOff)
	if f.policy.CompactNative {
		f.adapterReturnReferenced = true
	}
	f.cmpRR(LR, X16, true)
	nested := f.a.Bcond(condNE)
	f.a.LdpPost(LR, X3, SP, 16)
	emitJump()

	f.patchBranch19(nested, f.a.Len())
	f.a.SubSP64(32)
	f.st64(SP, 0, LR)
	f.a.LeaSP(X3, 16)
	trampolineADR := f.a.Adr(LR)
	f.recordPCRelative(trampolineADR)
	emitJump()

	trampoline := f.a.Len()
	f.a.PatchAdr(trampolineADR, trampoline)
	f.ld64(LR, SP, 0)
	if len(ft.Results) > 0 {
		if isFloatValType(ft.Results[0]) {
			f.fld(0, SP, 16, wasm.EqualValType(ft.Results[0], wasm.F64))
		} else {
			f.ld64(X0, SP, 16)
		}
	}
	if len(ft.Results) > 1 {
		f.ld64(X1, SP, 24)
	}
	f.a.AddSP64(32)
	f.a.Ret()
}

// emitTailDynamicImportJump transfers a register-ABI tail call through the
// runtime import-dispatch tuple. A target wrapper entered from another wrapper
// reuses that wrapper's LR/result record; a direct internal caller receives one
// fixed trampoline record that restores its instance context and result
// registers. Repeated cross-instance tails therefore do not accumulate frames.
func (f *fn) emitTailDynamicImportJump(ft *wasm.CompType, b ImportBinding) error {
	if b.Dynamic && b.ImportIndex > uint32((1<<31-1-runtime.ImportDispatchCallerContextOffset)/runtime.ImportDispatchEntryBytes) {
		return fmt.Errorf("return_call: import dispatch index %d overflows displacement", b.ImportIndex)
	}
	p := len(ft.Params)
	roots := f.rootsBottomToTop()
	if len(roots) < p {
		panic("arm64 cross-tail operand underflow")
	}
	types := make([]machineType, len(roots))
	for i, root := range roots {
		types[i] = rootMachineType(root)
	}
	f.flush()
	f.storePinnedGlobals(false)
	f.storeModuleGlobals(X16)

	if b.Dynamic {
		disp := int32(b.ImportIndex * runtime.ImportDispatchEntryBytes)
		f.ld64(X16, linMemReg, -int32(offImportDispatchPtr))
		f.ld64(X10, X16, disp+runtime.ImportDispatchHomeLinMemOffset)
		f.ld64(X11, X16, disp+runtime.ImportDispatchTargetContextOffset)
		f.ld64(X17, X16, disp+runtime.ImportDispatchCodePtrOffset)
		f.ld64(X12, X16, disp+runtime.ImportDispatchCallerContextOffset)
		f.a.AndImm64(X12, X12, ^runtime.ImportDispatchCallerTagMask)
	} else {
		f.a.MovImm64(X10, b.CalleeLinMem)
		f.a.MovImm64(X17, b.CalleeEntry)
		f.ld64(X12, linMemReg, -int32(offFuncRefDescPtr))
		f.ld64(X12, X12, runtime.FuncRefContextOffset)
		f.ld64(X11, X10, -int32(offFuncRefDescPtr))
		f.ld64(X11, X11, runtime.FuncRefContextOffset)
	}
	for _, reg := range []Reg{X10, X11, X12, X17} {
		f.pinned = f.pinned.add(reg)
	}
	// Publish the callee context once before staging and the root/nested split.
	// Its tag-directory cell is immediately outside the wrapper argument bank.
	f.copyInstanceContext(X10, X11)
	f.a.MovReg64(X0, X10)
	f.leaDisp(X0, X0, -int32(abi.TailArgsOffset), true)
	argBase := len(types) - p
	dstSlot := 0
	for i, typ := range ft.Params {
		srcSlot := slotOfLogicalTypes(types, argBase+i)
		n := mtOf(typ).stackSlots()
		for j := 0; j < n; j++ {
			f.ld64(X16, SP, f.spillOff(srcSlot+j))
			f.st64(X0, int32((dstSlot+j)*8), X16)
		}
		dstSlot += n
	}
	for _, reg := range []Reg{X10, X11, X12, X17} {
		f.pinned = f.pinned.remove(reg)
	}
	f.emitTailFrameRelease()

	transfer := func() {
		f.ld64(X9, linMemReg, -int32(offTrapHandlerPtr))
		f.st64(X10, -int32(offTrapHandlerPtr), X9)
		f.ld64(X9, linMemReg, -int32(offTrapStackReentry))
		f.st64(X10, -int32(offTrapStackReentry), X9)
		f.ld64(X9, linMemReg, -int32(offStackFence))
		f.st64(X10, -int32(offStackFence), X9)
		f.ld64(X9, linMemReg, -int32(offTrapCellPtr))
		f.st64(X10, -int32(offTrapCellPtr), X9)
		f.a.MovReg64(X0, X10)
		f.leaDisp(X0, X0, -int32(abi.TailArgsOffset), true)
		f.a.MovReg64(X1, X10)
		f.ld64(X2, X10, -int32(offTrapCellPtr))
		f.a.Br(X17)
	}

	// A register-ABI function entered through its own wrapper can discard the
	// wrapper record as well, preserving the outer LR/results destination.
	adapterPC := f.a.Adr(X16)
	f.recordPCRelative(adapterPC)
	f.patchAdr(adapterPC, f.adapterReturnOff)
	if f.policy.CompactNative {
		f.adapterReturnReferenced = true
	}
	f.cmpRR(LR, X16, true)
	nested := f.a.Bcond(condNE)
	f.a.LdpPost(LR, X3, SP, 16)
	transfer()

	f.patchBranch19(nested, f.a.Len())
	// [LR, caller linMem, caller context, pad, result0, result1, pad, pad].
	f.a.SubSP64(64)
	f.st64(SP, 0, LR)
	f.st64(SP, 8, linMemReg)
	f.st64(SP, 16, X12)
	f.a.LeaSP(X3, 32)
	trampolineADR := f.a.Adr(LR)
	f.recordPCRelative(trampolineADR)
	transfer()

	trampoline := f.a.Len()
	f.a.PatchAdr(trampolineADR, trampoline)
	f.ld64(LR, SP, 0)
	f.ld64(X10, SP, 8)
	f.ld64(X11, SP, 16)
	f.copyInstanceContext(X10, X11)
	f.a.MovReg64(linMemReg, X10)
	f.refreshCachedMemoryBoundAfterExternalCall()
	f.deriveModuleGlobals()
	f.derivePinnedGlobals()
	if len(ft.Results) > 0 {
		if isFloatValType(ft.Results[0]) {
			f.fld(0, SP, 32, wasm.EqualValType(ft.Results[0], wasm.F64))
		} else {
			f.ld64(X0, SP, 32)
		}
	}
	if len(ft.Results) > 1 {
		f.ld64(X1, SP, 40)
	}
	f.a.AddSP64(64)
	f.a.Ret()
	f.unreachable = true
	return nil
}

func arm64FuncTypeCarriesGCRefs(m *wasm.Module, ft *wasm.CompType) bool {
	if ft == nil {
		return false
	}
	for _, typ := range ft.Params {
		if arm64GCFrameRefType(m, typ) {
			return true
		}
	}
	for _, typ := range ft.Results {
		if arm64GCFrameRefType(m, typ) {
			return true
		}
	}
	return false
}

func (f *fn) returnCallRef(r *wasm.Reader) error {
	typeIdx, err := r.U32()
	if err != nil {
		return err
	}
	return f.returnCallRefType(typeIdx)
}

func (f *fn) returnCallRefType(typeIdx uint32) error {
	// The target null/type checks are later observable traps.
	f.materializePendingTraps()
	ft, ok := f.m.TypeFunc(typeIdx)
	if !ok {
		return fmt.Errorf("return_call_ref: bad type %d", typeIdx)
	}
	if !tailResultABICompatible(f.ft.Results, ft.Results) {
		return fmt.Errorf("return_call_ref: type %d result shape differs from caller", typeIdx)
	}
	callerRegABI := stagedTailRegisterABI(f.ft, f.stagedTailDescriptors)
	targetRegABI := stagedTailRegisterABI(ft, f.stagedTailDescriptors)
	canon, ok := f.m.StructuralTypeKeyChecked(typeIdx)
	if !ok {
		return fmt.Errorf("return_call_ref: type %d exceeds bounded native identity", typeIdx)
	}
	refValue := f.popValue()
	if refValue.elemKind() == ekValue && refValue.st.kind == stFuncRef && refValue.st.idx < uint32(f.importedFunctionCount()) {
		importIndex := refValue.st.index()
		if f.importBindings != nil && importIndex < len(f.importBindings) {
			binding := f.importBindings[importIndex]
			if binding.Dynamic || binding.CrossInstance {
				if slots := funcTypeSlots(ft.Params); slots > abi.TailArgsSlots {
					return fmt.Errorf("return_call_ref: type %d requires %d wrapper argument slots, limit %d", typeIdx, slots, abi.TailArgsSlots)
				}
				f.stats.call("tail-ref-foreign")
				return f.emitTailDynamicImportJump(ft, binding)
			}
		}
		var callErr error
		if f.syncHostCalls || len(ft.Results) != 0 {
			callErr = f.callHostSync(importIndex, ft)
		} else {
			callErr = f.callHost(importIndex, ft)
		}
		if callErr != nil {
			return callErr
		}
		return f.opReturn()
	}

	if slots := funcTypeSlots(ft.Params); slots > abi.TailArgsSlots {
		return fmt.Errorf("return_call_ref: type %d requires %d wrapper argument slots, limit %d", typeIdx, slots, abi.TailArgsSlots)
	}
	ref := f.materialize(refValue)
	f.pinned = f.pinned.add(ref)
	f.trapIfZero(ref, true, true, trapIndirectOOB)
	code := f.allocReg(0)
	f.ld64(code, ref, runtime.TableEntryCodePtrOffset)
	f.trapIfZero(code, true, true, trapIndirectOOB)
	f.checkCallType(ref, runtime.TableEntrySigKeyOffset, canon, typeIdx, maskOf(ref, code))
	home := f.allocReg(maskOf(ref, code))
	f.ld64(home, ref, runtime.TableEntryHomeLinMemOffset)
	targetContext := f.allocReg(maskOf(ref, code, home))
	f.ld64(targetContext, ref, runtime.FuncRefContextOffset)
	f.trapIfZero(targetContext, true, true, trapTailUnsupported)
	if arm64FuncTypeCarriesGCRefs(f.m, ft) {
		targetDomain := f.allocReg(maskOf(ref, code, home, targetContext))
		f.ld64(targetDomain, targetContext, runtime.InstanceContextGCDomainOffset)
		f.trapIfZero(targetDomain, true, true, trapTailUnsupported)
		callerDesc := f.allocReg(maskOf(ref, code, home, targetContext, targetDomain))
		f.ld64(callerDesc, linMemReg, -int32(offFuncRefDescPtr))
		f.trapIfZero(callerDesc, true, true, trapTailUnsupported)
		f.ld64(callerDesc, callerDesc, runtime.FuncRefContextOffset)
		f.ld64(callerDesc, callerDesc, runtime.InstanceContextGCDomainOffset)
		f.cmpRR(targetDomain, callerDesc, true)
		f.release(callerDesc)
		f.release(targetDomain)
		f.trapIf(condNE, trapTailUnsupported)
	}
	f.pinned = f.pinned.remove(ref)
	f.release(ref)

	roots := f.rootsBottomToTop()
	types := make([]machineType, len(roots))
	gcRoots := gcRootFlags(roots)
	for i, root := range roots {
		types[i] = rootMachineType(root)
	}
	f.pinned = f.pinned.add(code).add(home).add(targetContext)
	f.flush()
	savedLocals := append([]localDef(nil), f.locals...)
	kind := f.descriptorEntryKind(home, maskOf(code, home, targetContext))
	f.stripDescriptorHomeTags(home)
	f.a.MovReg64(X17, code)
	f.a.MovReg64(X10, home)
	f.a.MovReg64(X11, targetContext)
	f.a.MovReg64(X13, kind)
	f.pinned = f.pinned.remove(code).remove(home).remove(targetContext)
	f.release(code)
	f.release(home)
	f.release(targetContext)
	f.release(kind)

	if f.opt(optRegABI) && targetRegABI {
		f.cmpImm(X13, uint32(abi.FuncRefInternalTagValue), true)
		wrapper := f.a.Bcond(condNE)
		f.cmpRR(X10, linMemReg, true)
		f.trapIf(condNE, trapTailUnsupported)
		if callerRegABI {
			f.emitTailRegisterJump(ft, func() { f.a.Br(X17) })
		} else {
			f.emitTailWrapperToAdapterJump(ft)
		}

		f.patchBranch19(wrapper, f.a.Len())
		f.locals = savedLocals
		f.setDepthTypesWithGCRoots(types, gcRoots)
	}
	f.validateWrapperDescriptor(X13, X10)
	if arm64FuncTypeCarriesGCRefs(f.m, ft) {
		// Runtime-owned GC host thunks use the active caller context and can
		// reuse the ordinary wrapper-tail result pointer without a restoration
		// record. Ordinary host descriptors fail the domain check above.
		f.cmpImm(X13, uint32(abi.FuncRefHostThunkTagValue), true)
		notHost := f.a.Bcond(condNE)
		f.emitTailWrapperJump(ft, func() { f.a.Br(X17) })

		f.patchBranch19(notHost, f.a.Len())
		f.locals = savedLocals
		f.setDepthTypesWithGCRoots(types, gcRoots)
	}
	f.emitTailDescriptorWrapperJump(ft)
	f.unreachable = true
	return nil
}

// emitTailDescriptorWrapperJump transfers the current activation through the
// descriptor target held in X17(code), X10(home linmem), and X11(context). It
// uses one fixed nested return record and therefore remains stack-bounded across
// arbitrary mutable-table and imported-reference tail chains.
func (f *fn) emitTailDescriptorWrapperJump(ft *wasm.CompType) {
	p := len(ft.Params)
	roots := f.rootsBottomToTop()
	types := make([]machineType, len(roots))
	for i, root := range roots {
		types[i] = rootMachineType(root)
	}
	f.flush()
	f.storePinnedGlobals(false)
	f.storeModuleGlobals(X16)

	f.ld64(X12, linMemReg, -int32(offFuncRefDescPtr))
	f.ld64(X12, X12, runtime.FuncRefContextOffset)
	// Publish the callee context once before staging and the root/nested split.
	// Its tag-directory cell is immediately outside the wrapper argument bank.
	f.copyInstanceContext(X10, X11)
	f.a.MovReg64(X0, X10)
	f.leaDisp(X0, X0, -int32(abi.TailArgsOffset), true)
	argBase := len(types) - p
	dstSlot := 0
	for i, typ := range ft.Params {
		srcSlot := slotOfLogicalTypes(types, argBase+i)
		n := mtOf(typ).stackSlots()
		for j := 0; j < n; j++ {
			f.ld64(X16, SP, f.spillOff(srcSlot+j))
			f.st64(X0, int32((dstSlot+j)*8), X16)
		}
		dstSlot += n
	}

	transfer := func() {
		f.ld64(X9, linMemReg, -int32(offTrapHandlerPtr))
		f.st64(X10, -int32(offTrapHandlerPtr), X9)
		f.ld64(X9, linMemReg, -int32(offTrapStackReentry))
		f.st64(X10, -int32(offTrapStackReentry), X9)
		f.ld64(X9, linMemReg, -int32(offStackFence))
		f.st64(X10, -int32(offStackFence), X9)
		f.ld64(X9, linMemReg, -int32(offTrapCellPtr))
		f.st64(X10, -int32(offTrapCellPtr), X9)
		f.a.MovReg64(X0, X10)
		f.leaDisp(X0, X0, -int32(abi.TailArgsOffset), true)
		f.a.MovReg64(X1, X10)
		f.ld64(X2, X10, -int32(offTrapCellPtr))
		f.a.Br(X17)
	}

	// A wrapper-ABI caller has no adapter record below its frame. Preserve its
	// original result destination from the frame header and tail-enter the target
	// wrapper directly. Register-ABI callers still need the run-time adapter/direct
	// distinction below because only adapter entry carries an outer X3 record.
	if !f.tailCallerUsesRegisterABI() {
		f.ld64(X3, SP, frResultsOff)
		f.emitTailFrameRelease()
		f.cmpRR(X10, linMemReg, true)
		foreign := f.a.Bcond(condNE)
		transfer()

		// A foreign target would return to our caller with its instance state
		// installed, and our caller may be same-instance code that relies on its
		// own. One fixed record [LR, caller linmem, caller context, pad] returns
		// through a trampoline that restores it, like a non-tail cross-instance
		// call; the target still writes our caller's results buffer.
		f.patchBranch19(foreign, f.a.Len())
		f.a.SubSP64(32)
		f.st64(SP, 0, LR)
		f.st64(SP, 8, linMemReg)
		f.st64(SP, 16, X12)
		trampolineADR := f.a.Adr(LR)
		f.recordPCRelative(trampolineADR)
		transfer()

		trampoline := f.a.Len()
		f.a.PatchAdr(trampolineADR, trampoline)
		f.ld64(LR, SP, 0)
		f.ld64(X10, SP, 8)
		f.ld64(X11, SP, 16)
		f.copyInstanceContext(X10, X11)
		f.a.MovReg64(linMemReg, X10)
		f.refreshCachedMemoryBoundAfterExternalCall()
		f.deriveModuleGlobals()
		f.derivePinnedGlobals()
		f.a.AddSP64(32)
		f.a.Ret()
		return
	}

	f.emitTailFrameRelease()
	adapterPC := f.a.Adr(X16)
	f.recordPCRelative(adapterPC)
	f.patchAdr(adapterPC, f.adapterReturnOff)
	if f.policy.CompactNative {
		f.adapterReturnReferenced = true
	}
	f.cmpRR(LR, X16, true)
	nested := f.a.Bcond(condNE)
	f.a.LdpPost(LR, X3, SP, 16)
	transfer()

	f.patchBranch19(nested, f.a.Len())
	f.a.SubSP64(64)
	f.st64(SP, 0, LR)
	f.st64(SP, 8, linMemReg)
	f.st64(SP, 16, X12)
	f.a.LeaSP(X3, 32)
	trampolineADR := f.a.Adr(LR)
	f.recordPCRelative(trampolineADR)
	transfer()

	trampoline := f.a.Len()
	f.a.PatchAdr(trampolineADR, trampoline)
	f.ld64(LR, SP, 0)
	f.ld64(X10, SP, 8)
	f.ld64(X11, SP, 16)
	f.copyInstanceContext(X10, X11)
	f.a.MovReg64(linMemReg, X10)
	f.refreshCachedMemoryBoundAfterExternalCall()
	f.deriveModuleGlobals()
	f.derivePinnedGlobals()
	if len(ft.Results) > 0 {
		if isFloatValType(ft.Results[0]) {
			f.fld(0, SP, 32, wasm.EqualValType(ft.Results[0], wasm.F64))
		} else {
			f.ld64(X0, SP, 32)
		}
	}
	if len(ft.Results) > 1 {
		f.ld64(X1, SP, 40)
	}
	f.a.AddSP64(64)
	f.a.Ret()
}

func (f *fn) returnCallIndirect(r *wasm.Reader) error {
	// Earlier operand traps precede table checks as well as callee effects.
	f.materializePendingTraps()
	typeIdx, err := r.U32()
	if err != nil {
		return err
	}
	tableIdx, err := r.U32()
	if err != nil {
		return err
	}
	ft, ok := f.m.TypeFunc(typeIdx)
	if !ok {
		return fmt.Errorf("return_call_indirect: bad type %d", typeIdx)
	}
	if !tailResultABICompatible(f.ft.Results, ft.Results) {
		return fmt.Errorf("return_call_indirect: type %d result shape differs from caller", typeIdx)
	}
	callerRegisterTail := f.opt(optRegABI) && stagedTailRegisterABI(f.ft, f.stagedTailDescriptors)
	targetRegisterTail := f.opt(optRegABI) && stagedTailRegisterABI(ft, f.stagedTailDescriptors)
	if !targetRegisterTail && funcTypeSlots(ft.Params) > abi.TailArgsSlots {
		return fmt.Errorf("return_call_indirect: type %d requires %d wrapper argument slots, limit %d", typeIdx, funcTypeSlots(ft.Params), abi.TailArgsSlots)
	}
	if f.stagedTailDescriptors && f.importBindings != nil {
		idx := f.materialize(f.popValue())
		f.canonicalizeTableOperand(idx, tableIdx)
		f.pinned = f.pinned.add(idx)
		tbl := f.allocReg(0)
		f.loadTableDescriptor(tbl, tableIdx)
		ln := f.allocReg(maskOf(tbl))
		f.ld32(ln, tbl, 0)
		f.cmpRR(idx, ln, f.tableAddr64(tableIdx))
		f.release(ln)
		f.trapIf(condAE, trapIndirectOOB)
		f.a.LslImm64(idx, idx, 5)
		f.a.Add64(idx, idx, tbl)
		f.ld64(idx, idx, 8+runtime.TableEntryRefSlotOffset)
		f.release(tbl)
		f.pinned = f.pinned.remove(idx)
		f.pushReg(idx, mtI64)
		return f.returnCallRefType(typeIdx)
	}
	canon, ok := f.m.StructuralTypeKeyChecked(typeIdx)
	if !ok {
		return fmt.Errorf("return_call_indirect: type %d exceeds bounded native identity", typeIdx)
	}
	idx := f.materialize(f.popValue())
	f.canonicalizeTableOperand(idx, tableIdx)
	f.pinned = f.pinned.add(idx)
	tbl := f.allocReg(0)
	f.loadTableDescriptor(tbl, tableIdx)
	ln := f.allocReg(maskOf(tbl))
	f.ld32(ln, tbl, 0)
	f.cmpRR(idx, ln, f.tableAddr64(tableIdx))
	f.release(ln)
	f.trapIf(condAE, trapIndirectOOB)
	f.a.LslImm64(idx, idx, 5)
	f.a.Add64(idx, idx, tbl)
	f.release(tbl)
	code := f.allocReg(maskOf(idx))
	f.ld64(code, idx, 8)
	f.trapIfZero(code, true, true, trapIndirectOOB)
	if !f.immutableTableTyped || f.immutableTableType != canon {
		f.checkCallType(idx, 8+runtime.TableEntrySigKeyOffset, canon, typeIdx, maskOf(idx, code))
	}
	home := f.allocReg(maskOf(idx, code))
	f.ld64(home, idx, 8+runtime.TableEntryHomeLinMemOffset)
	kind := f.descriptorEntryKind(home, maskOf(idx, code, home))
	f.stripDescriptorHomeTags(home)
	f.cmpRR(home, linMemReg, true)
	f.trapIf(condNE, trapTailUnsupported)
	wantKind := uint32(abi.FuncRefLocalWrapperTagValue)
	if targetRegisterTail {
		wantKind = uint32(abi.FuncRefInternalTagValue)
	}
	f.cmpImm(kind, wantKind, true)
	f.trapIf(condNE, trapTailUnsupported)
	f.release(kind)
	f.release(home)
	f.pinned = f.pinned.remove(idx)
	f.release(idx)
	f.st64(linMemReg, -int32(offSpillRegion), code)
	f.release(code)
	jump := func() {
		f.ld64(X16, linMemReg, -int32(offSpillRegion))
		f.a.Br(X16)
	}
	if targetRegisterTail {
		if callerRegisterTail {
			f.emitTailRegisterJump(ft, jump)
		} else {
			f.emitTailWrapperToRegisterJump(ft, jump)
		}
	} else {
		if slots := funcTypeSlots(ft.Params); slots > abi.TailArgsSlots {
			return fmt.Errorf("return_call_indirect: type %d requires %d wrapper argument slots, limit %d", typeIdx, slots, abi.TailArgsSlots)
		}
		f.emitTailWrapperJump(ft, jump)
	}
	f.unreachable = true
	return nil
}

func (f *fn) emitCustomInstruction(custom railcore.CustomInstruction, ft *wasm.CompType) error {
	if pluginARM64Lowering(custom) == nil {
		return f.emitInstructionRecipe(custom, ft)
	}
	start := f.a.Len()
	err := f.emitPluginARM64(pluginARM64Lowering(custom), custom.InputWidths, custom.ResultWidth, len(ft.Results), custom.CustomInputs, custom.CustomOutput)
	if err == nil {
		f.recordOpaquePlugin(start, f.a.Len())
	}
	return err
}

// inCallSiteLoop reports whether the current call site is nested in a Wasm loop.
func (f *fn) inCallSiteLoop() bool {
	for i := len(f.ctrl) - 1; i >= 0; i-- {
		if f.ctrl[i].kind == cfLoop {
			return true
		}
	}
	return false
}

// callHost lowers a call to a VOID imported (host) function. Native wasm code
// cannot call back into Go without cgo, so the call is LOGGED to an in-memory
// buffer (at [linMem-offCustomCtx]) and replayed on the Go stack after the wasm
// function returns. Fire-and-forget: no result. Returning imports take the
// synchronous re-entry path instead (callHostSync). The caller (emitCall) routes
// by result arity, so ft here always has zero results.
func (f *fn) callHost(importIdx int, ft *wasm.CompType) error {
	f.stats.call(callKindHost)
	p := len(ft.Params)
	types, argSlot := f.flushSuffix(p)
	// The logger does not leave native execution; only its fixed X9-X11 scratch
	// bank needs preservation. Locals and value-pinned globals share that extended
	// pin bank, so home both before reusing it without evicting unrelated GP/FP pins.
	hostLogScratch := maskOf(X9, X10, X11)
	f.spillLocalsForClobbers(hostLogScratch, 0)
	f.storePinnedGlobalsIn(hostLogScratch, false)
	if p > 0 {
		f.ld32(X0, SP, f.spillOff(argSlot)) // first param
	} else {
		f.a.MovImm64(X0, 0) // zero (no flag side effect on arm64)
	}
	// The extended pin bank has already been homed, so X0/X9/X10/X11 are free
	// for the async host-log sequence below.
	f.ld64(X11, linMemReg, -int32(offCustomCtx)) // X11 = host-call log
	f.ld32(X9, X11, 0)                           // count
	f.a.AddShifted(X10, X11, X9, 3, false)       // entry = log + count*8
	f.leaDisp(X10, X10, 8, true)                 // + 8 header
	f.a.MovImm64(X16, uint64(uint32(importIdx)))
	f.st32(X10, 0, X16)
	f.st32(X10, 4, X0)
	f.a.AddImm32(X9, X9, 1) // count++
	f.st32(X11, 0, X9)
	f.dropFlushedSuffix(types, p)
	f.derivePinnedGlobalsIn(hostLogScratch)
	// The legacy non-STACK_REG model restores the selected local pins eagerly.
	// STACK_REG leaves them memory-resident and recovers each on its next read.
	f.reloadLocalsForClobbers(hostLogScratch, 0)
	return nil
}

// moduleUsesSyncHostCalls reports whether the module has any returning host
// import (a function import with results, not bound cross-instance). Such a
// module routes ALL host calls through the synchronous control frame, so the
// async host-call log and the control frame never both occupy offCustomCtx.
func moduleUsesSyncHostCalls(m *wasm.Module, bindings []ImportBinding) bool {
	for i := 0; i < m.TableCount(); i++ {
		if tt, ok := m.TableType(uint32(i)); ok && wasm.ExternReferenceType(wasm.RefVal(tt.Ref)) {
			return true
		}
	}
	for i := 0; i < m.GlobalCount(); i++ {
		if gt, ok := m.GlobalTypeByIndex(uint32(i)); ok && wasm.ExternReferenceType(wasm.GlobalValueType(gt)) {
			return true
		}
	}

	imported := m.ImportedFuncCount()
	for i := 0; i < imported; i++ {
		if bindings != nil && i < len(bindings) && bindings[i].CrossInstance {
			continue
		}
		if ft, ok := m.FuncSignature(uint32(i)); ok && (len(ft.Results) != 0 || funcTypeUsesV128(ft)) {
			return true
		}
	}
	return false
}

func funcTypeUsesV128(ft *wasm.CompType) bool {
	for _, t := range ft.Params {
		if wasm.EqualValType(t, wasm.V128) {
			return true
		}
	}
	for _, t := range ft.Results {
		if wasm.EqualValType(t, wasm.V128) {
			return true
		}
	}
	return false
}

func funcTypeSlots(ts []wasm.ValType) int {
	n := 0
	for _, t := range ts {
		n += mtOf(t).stackSlots()
	}
	return n
}

func (f *fn) syncHostAddress(base Reg, disp int32, size int) (Reg, int32) {
	if disp >= 0 && disp%int32(size) == 0 && disp/int32(size) <= 0xfff {
		return base, disp
	}
	f.a.MovImm64(X16, uint64(uint32(disp)))
	f.a.Add64(X16, base, X16)
	return X16, 0
}

func (f *fn) syncHostStore64(base Reg, disp int32, src Reg) {
	addr, off := f.syncHostAddress(base, disp, 8)
	f.st64(addr, off, src)
}

func (f *fn) syncHostLoad64(dst, base Reg, disp int32) {
	addr, off := f.syncHostAddress(base, disp, 8)
	f.ld64(dst, addr, off)
}

func (f *fn) syncHostStoreV128(base Reg, disp int32, src Reg) {
	addr, off := f.syncHostAddress(base, disp, 16)
	f.a.VMovdquStoreDisp(addr, off, src)
}

func (f *fn) syncHostLoadV128(dst, base Reg, disp int32) {
	addr, off := f.syncHostAddress(base, disp, 16)
	f.a.VMovdquLoadDisp(dst, addr, off)
}

func (f *fn) gcFramePrefixRoots(roots []*elem, n int) []bool {
	if !f.tracksGCFrameRoots() || n <= 0 {
		return nil
	}
	flags := f.tmpGCRoots2[:0]
	for _, root := range roots[:n] {
		flags = append(flags, root.elemKind() == ekValue && root.st.hasGCRoot())
	}
	f.tmpGCRoots2 = flags
	return flags
}

// callHostSync lowers a call to a RETURNING imported (host) function via the
// synchronous re-entry protocol (see src/core/runtime/hostcall_arm64.go). The p
// params are marshaled into the off-heap control frame (at [linMem-offCustomCtx]);
// `blr [ctrl+hcTrampoline]` runs the shared hostCallStub, which saves the wasm
// register state and unwinds to Go; Go runs the host function, writes the
// results, and resumes here; the rN results are read out of the control frame
// onto the operand stack.
//
// hostCallStub saves and resumeNative restores the callee-saved registers
// (X19..linMemReg, low 64 bits of V8..V15), but the extended local-pin pool also
// uses caller-saved X8..X11 and vector values may occupy the full 128 bits.
// Pinned locals are therefore homed before the transition and restored under the
// old non-STACK_REG model. Value-pinned and module-pinned globals are also synced
// around the call: the host may read or write the instance's globals through
// their cells.
func (f *fn) callHostSync(importIdx int, ft *wasm.CompType) error {
	nativeDeadStructType := f.nativeDeadStructType
	f.nativeDeadStructType = 0
	nativeDeadArrayBatchBytes := f.nativeDeadArrayBatchBytes
	f.nativeDeadArrayBatchBytes = 0
	nativeDeadStructBatchType := f.nativeDeadStructBatchType
	f.nativeDeadStructBatchType = 0
	nativeArrayHelper, nativeArrayType := f.nativeArrayHelper, f.nativeArrayType
	f.nativeArrayHelper = 0
	nativeDeadArrayBytes := f.nativeDeadArrayBytes
	f.nativeDeadArrayBytes = 0
	f.stats.call(callKindHostSync)
	// Blocking waits use the complete host frame and GC callsite maps. Other
	// atomic helpers retain the compact internal transition.
	atomicWait := uint32(importIdx)&shared.AtomicWaitDispatchBit != 0 &&
		(uint32(importIdx)&^shared.AtomicWaitDispatchBit == shared.AtomicHelperWait32 || uint32(importIdx)&^shared.AtomicWaitDispatchBit == shared.AtomicHelperWait64)
	internalGC := uint32(importIdx)&gcStructDispatchBit != 0 || uint32(importIdx)&shared.AtomicWaitDispatchBit != 0 && !atomicWait
	p := len(ft.Params)
	notifyIndex := uint32(0)
	notifyFast := uint32(importIdx) == shared.AtomicWaitDispatchBit|shared.AtomicHelperNotify && f.opt(optAtomicNotifyEmpty) && (p == 3 || p == 4)
	if notifyFast && p == 4 {
		top := f.s.back()
		if top.st.kind != stConst {
			notifyFast = false
		} else {
			notifyIndex = uint32(top.st.cval)
		}
	}

	var rootOffsets []uint32
	recordRoots := false
	if !internalGC {
		rootOffsets, recordRoots = f.prepareGCFrameCallsite(p)
	}
	paramSlots := funcTypeSlots(ft.Params)
	resultSlots := funcTypeSlots(ft.Results)
	internalGCHelper := uint32(importIdx)&gcStructDispatchBit != 0
	slotLimit := maxSyncHostSlots
	if internalGCHelper {
		slotLimit = f.syncHostSlots
	}
	wide := internalGCHelper && (paramSlots > maxSyncHostSlots || resultSlots > maxSyncHostSlots)
	if paramSlots > slotLimit || resultSlots > slotLimit {
		return fmt.Errorf("host import %d uses %d param slot(s), %d result slot(s); synchronous host frame supports at most %d slots in each direction", importIdx, paramSlots, resultSlots, slotLimit)
	}

	roots := f.rootsBottomToTop()
	d := len(roots)
	types := f.tmpTypes[:0]
	slotOf := f.tmpStackSlots[:0]
	slotTop := 0
	for _, root := range roots {
		typ := root.st.typ
		if root.elemKind() == ekDeferred && root.st.typ != mtNone {
			typ = root.st.typ
		}
		types = append(types, typ)
		slotOf = append(slotOf, uint32(slotTop))
		slotTop += typ.stackSlots()
	}
	f.tmpTypes = types
	f.tmpStackSlots = slotOf
	// Only memory32 index zero has this compact canonical-slot fast path.
	// Other memories retain their existing width-aware helper lowering.
	atomicFast := f.threadedMemory0 && !f.memoryAddr64(0) &&
		(atomicWait && p == 4 || notifyFast && p == 3)
	atomicOffset := uint32(0)
	if atomicFast {
		offset := roots[d-1].st
		atomicFast = offset.kind == stConst && uint64(offset.cval) <= 0xffffffff
		atomicOffset = uint32(offset.cval)
	}
	belowTypes := f.tmpTypes2[:0]
	if cap(belowTypes) < d-p {
		belowTypes = make([]machineType, 0, d-p)
	}
	belowTypes = append(belowTypes, types[:d-p]...)
	f.tmpTypes2 = belowTypes
	belowGCRoots := f.gcFramePrefixRoots(roots, d-p)

	f.flush() // operands to canonical slot-width slots
	// X9-X11 are part of the extended local-pin bank. Home every dirty pin before
	// globals, control-frame setup, or argument marshalling reuses those registers.
	f.spillLocalsForCall()
	if regallocCheckEnabled {
		f.checkHostSyncHomes()
	}
	f.storePinnedGlobals(false) // coherence/preservation for value-pinned caller-saved globals
	if !internalGC {
		// Internal GC helpers cannot observe or mutate numeric module-global cells,
		// and their module-pinned registers are preserved by the parked transition.
		f.storeModuleGlobals(X9)
	}

	atomicDone := -1
	if atomicFast {
		if regallocCheckEnabled {
			f.checkCallClobber()
		}
		atomicDone = f.emitAtomicWaitFastPath(uint32(importIdx)&^shared.AtomicWaitDispatchBit, int(slotOf[d-p]), atomicOffset)
		if notifyFast {
			f.stats.peep("atomic-notify-empty")
		}
	}

	gcDone := -1
	if nativeDeadArrayBatchBytes != 0 && !wide {
		gcDone = f.deadObjectCountShortcut(nativeDeadArrayBatchBytes, 8, int(slotOf[d-p]))
	}
	if nativeDeadStructBatchType != 0 && !wide {
		gcDone = f.deadStructBatchShortcut(nativeDeadStructBatchType-1, int(slotOf[d-p]))
	}
	if nativeDeadStructType != 0 && !wide {
		gcDone = f.deadStructShortcut(nativeDeadStructType - 1)
	}

	if nativeArrayHelper != 0 && !wide {
		if nativeDeadArrayBytes != 0 {
			gcDone = f.deadObjectShortcut(nativeDeadArrayBytes, 8)
		} else if nativeArrayHelper == gcArrayAllocUniform || nativeArrayHelper == gcArrayAllocDefault {
			gcDone = f.arrayAllocationShortcut(nativeArrayHelper, nativeArrayType, int(slotOf[d-p]))
		} else {
			gcDone = f.arrayScalarShortcut(nativeArrayHelper, nativeArrayType, int(slotOf[d-p]))
		}
	}

	if uint32(importIdx) == gcStructDispatchBit|gcArrayLen {
		gcDone = f.arrayLenShortcut(int(slotOf[d-p]))
	}

	// Marshal params into the control frame as wrapper-ABI slots. A v128 occupies
	// two adjacent little-endian uint64 slots, exactly like Invoke and cross-
	// instance wrapper calls.
	f.ld64(X11, linMemReg, -int32(offCustomCtx)) // X11 = control frame
	argsOffset, resultsOffset := int32(hcArgs), int32(hcResults)
	if wide {
		f.a.AddImm64(X11, X11, hcWideBase)
		argsOffset = hcWideArgs
		resultsOffset = hcWideArgs + int32(f.syncHostSlots)*8
	}
	argSlot, ctrlSlot := 0, 0
	if p > 0 {
		argSlot = int(slotOf[d-p])
	}
	for i := 0; i < p; i++ {
		mt := mtOf(ft.Params[i])
		if mt.isV128() {
			x := f.allocFReg(0)
			f.a.VMovdquLoadDisp(x, SP, f.spillOff(argSlot))
			f.syncHostStoreV128(X11, argsOffset+int32(ctrlSlot)*8, x)
			f.releaseF(x)
		} else if mt.is64() {
			f.ld64(X9, SP, f.spillOff(argSlot))
			f.syncHostStore64(X11, argsOffset+int32(ctrlSlot)*8, X9)
		} else {
			f.ld32(X9, SP, f.spillOff(argSlot)) // zero-extends into X9
			f.syncHostStore64(X11, argsOffset+int32(ctrlSlot)*8, X9)
		}
		argSlot += mt.stackSlots()
		ctrlSlot += mt.stackSlots()
	}
	if wide {
		f.ld64(X11, linMemReg, -int32(offCustomCtx))
	}
	f.a.MovImm64(X16, uint64(uint32(importIdx)))
	f.st32(X11, hcImportIdx, X16)
	// hcNArgs packs param slots (low 16) and result slots (high 16) so the Go
	// re-entry loop copies back only the real result count. Both fit uint16.
	f.a.MovImm64(X16, uint64(uint32(paramSlots)|uint32(resultSlots)<<16))
	f.st32(X11, hcNArgs, X16)

	notifyDone := -1
	if notifyFast && !atomicFast {
		notifyDone = f.notifyEmptyShortcut(notifyIndex)
	}
	// Park at the host call. Like the wrapper path, no post-call trap check: a
	// trap unwinds the whole native tree in one jump (it never returns here).
	f.ld64(X16, X11, hcTrampoline)
	if regallocCheckEnabled {
		f.checkCallClobber()
	}
	f.a.Blr(X16)
	if recordRoots {
		f.gcFrameRoots.RecordCallsite(uint32(f.a.Len()), 0, rootOffsets)
	}
	if gcDone >= 0 {
		f.patchBranch26(gcDone, f.a.Len())
	}
	if notifyDone >= 0 {
		f.patchBranch26(notifyDone, f.a.Len())
	}
	if atomicDone >= 0 {
		f.patchBranch26(atomicDone, f.a.Len())
	}
	f.setDepthTypesWithGCRoots(belowTypes, belowGCRoots)

	// Publish each result immediately so later loads can spill it to the existing
	// operand frame. Pin only the control pointer, never the whole result set.
	// setDepthTypesWithGCRoots clears transient pins, so reserve X11 after it.
	savedPins := f.pinned
	f.pinned = f.pinned.add(X11)
	f.ld64(X11, linMemReg, -int32(offCustomCtx))
	if wide {
		f.a.AddImm64(X11, X11, hcWideBase)
	}
	ctrlSlot = 0
	for _, result := range ft.Results {
		rt := mtOf(result)
		var value *elem
		switch {
		case rt.isV128():
			r := f.allocFReg(0)
			f.syncHostLoadV128(r, X11, resultsOffset+int32(ctrlSlot)*8)
			value = f.pushVReg(r)
		case rt.isFloat():
			tmp := f.allocReg(0)
			f.syncHostLoad64(tmp, X11, resultsOffset+int32(ctrlSlot)*8)
			r := f.allocFReg(0)
			f.a.FmovFromGpr(r, tmp, true)
			f.release(tmp)
			value = f.pushFReg(r, rt)
		default:
			r := f.allocReg(0)
			f.syncHostLoad64(r, X11, resultsOffset+int32(ctrlSlot)*8)
			value = f.pushReg(r, rt)
		}
		value.st.setGCRoot(f.tracksGCFrameRoots() && arm64GCFrameRefType(f.m, result))
		ctrlSlot += rt.stackSlots()
	}
	f.pinned = savedPins
	// A restored local or value-pinned global can occupy X11. Restore these
	// only after the final control-frame load. Their registers remain reserved
	// from result allocation throughout the reconstruction.
	f.reloadLocalsForCall()
	if !internalGC {
		f.deriveModuleGlobals()
	}
	f.derivePinnedGlobals()
	// Arbitrary host code can synchronously re-enter this instance and grow its
	// memory. Reload after reconstructing the operand stack so the continuation
	// cannot retain the parked activation's pre-call size.
	f.refreshCachedMemoryBoundAfterExternalCall()
	return nil
}

// HostIndirectThunk returns standalone machine code that logs a deferred host
// event for importIdx and returns. It is entered with the wrapper ABI (X1 =
// linMem, X0 = args buffer), appends (importIdx, first-arg-i32) to the host-call
// log at [linMem-offCustomCtx] exactly like callHost, and returns void, so the
// normal post-invoke replay delivers the event. Emitted per host funcref into
// a per-instance mapping; the same code is instance-independent (it reads the log
// pointer from X1 at run time).
func HostIndirectThunk(importIdx uint32) []byte {
	// Preserve the ordinary encoding; module functions opt into logical MOVs
	// through their policy.
	a := &a64.Asm{DisableLogicalMoveImmediate: true}
	a.Load32(X9, X0, 0)               // X9 = first arg (i32; a harmless slot read for 0-param funcs)
	a.SubImm64(X10, X1, offCustomCtx) // X10 = &host-call log (X1 = linMem in the wrapper ABI)
	a.Load64(X10, X10, 0)
	a.Load32(X11, X10, 0) // count
	a.CmpImm32LSL12(X11, runtime.HostCallLogEntries)
	full := a.Bcond(condAE)
	a.AddShifted(X12, X10, X11, 3, false) // entry = log + count*8
	a.AddImm64(X12, X12, 8)               // + 8 header
	a.MovImm64(X16, uint64(uint32(importIdx)))
	a.Store32(X16, X12, 0)
	a.Store32(X9, X12, 4)   // arg
	a.AddImm32(X11, X11, 1) // count++
	a.Store32(X11, X10, 0)
	a.Ret()
	if !a.PatchBranch19(full, a.Len()) {
		panic("arm64: fixed host thunk branch exceeds instruction range")
	}
	a.SubImm64(X10, X1, offTrapCellPtr)
	a.Load64(X10, X10, 0)
	a.MovImm64(X16, uint64(runtime.TrapHostEventOverflow))
	a.Store32(X16, X10, 0)
	a.SubImm64(X10, X1, offTrapStackReentry)
	a.Load64(X10, X10, 0)
	a.SubImm64(X11, X1, offTrapHandlerPtr)
	a.Load64(LR, X11, 0)
	a.AddImm64(SP, X10, 0)
	a.Ret()
	return a.B
}

// HostIndirectSyncThunk returns standalone machine code for a sync-mode host
// import reached through call_indirect. It is entered with the wrapper ABI
// (X0=args, X3=results, X1=home linMem). Unlike HostIndirectThunk, it must not
// touch the async host log at offCustomCtx; sync-mode instances store the
// host-call control frame there. The thunk marshals raw uint64 wrapper slots into
// the control frame, parks via hostCallStub, then copies result slots back into
// the wrapper results buffer before returning to the wasm caller.
func HostIndirectSyncThunk(importIdx uint32, paramSlots, resultSlots int) []byte {
	return hostIndirectSyncThunk(importIdx, paramSlots, resultSlots, true)
}

// HostIndirectOwnedSyncThunk uses the active caller's control frame so an
// explicitly owned host funcref can be invoked from another same-store instance.
func HostIndirectOwnedSyncThunk(importIdx uint32, paramSlots, resultSlots int) []byte {
	return hostIndirectSyncThunk(importIdx, paramSlots, resultSlots, false)
}

// emitHostThunkTransfers rebases each cursor at the 32 KiB scaled-offset
// boundary. This keeps every LDR/STR encodable without materializing a large
// address for each remaining slot.
func emitHostThunkTransfers(a *a64.Asm, value, loadBase, storeBase Reg, loadOffset, storeOffset uint32, slots int) {
	const offsetWindow = uint32(0x1000 * 8)
	for range slots {
		if loadOffset >= offsetWindow {
			a.AddImm64LSL12(loadBase, loadBase, offsetWindow)
			loadOffset -= offsetWindow
		}
		if storeOffset >= offsetWindow {
			a.AddImm64LSL12(storeBase, storeBase, offsetWindow)
			storeOffset -= offsetWindow
		}
		if !a.Load64(value, loadBase, loadOffset) {
			panic("arm64: host thunk load offset out of range")
		}
		if !a.Store64(value, storeBase, storeOffset) {
			panic("arm64: host thunk store offset out of range")
		}
		loadOffset += 8
		storeOffset += 8
	}
}

func hostIndirectSyncThunk(importIdx uint32, paramSlots, resultSlots int, useHome bool) []byte {
	// Preserve the ordinary encoding; module functions opt into logical MOVs
	// through their policy.
	a := &a64.Asm{DisableLogicalMoveImmediate: true}
	// The host-call round trip preserves only callee-saved registers recorded by
	// hostCallStub. Save the caller's linMemReg (active linMem), the wrapper result
	// pointer, and this thunk's incoming LR across the park/resume; set linMemReg to the
	// funcref's home linMem so the shared hostCallStub reads the correct basedata
	// control cells.
	a.StpPre(linMemReg, X3, SP, -32) // [SP]=linMemReg, [SP+8]=X3, [SP+16]=LR
	a.Store64(LR, SP, 16)
	if useHome {
		a.MovReg64(linMemReg, X1)
	}
	a.SubImm64(X10, linMemReg, offCustomCtx)
	a.Load64(X10, X10, 0) // X10 = sync host-call control frame
	wide := paramSlots > maxSyncHostSlots || resultSlots > maxSyncHostSlots
	argBase := X10
	argOffset := uint32(hcArgs)
	if wide {
		argBase = X11
		argOffset = 0
		a.AddImm64(X11, X10, uint32(hcWideBase+hcWideArgs))
	}
	emitHostThunkTransfers(a, X9, X0, argBase, 0, argOffset, paramSlots)
	a.MovImm64(X16, uint64(uint32(importIdx)))
	a.Store32(X16, X10, hcImportIdx)
	a.MovImm64(X16, uint64(uint32(paramSlots)|uint32(resultSlots)<<16)) // low16 params, high16 results
	a.Store32(X16, X10, hcNArgs)
	a.Load64(X16, X10, hcTrampoline)
	a.Blr(X16)

	// resumeNative returns here with linMemReg restored to the home linMem saved by
	// hostCallStub. Reload the control frame (caller-saved registers were
	// clobbered), restore the result pointer from the saved slot, copy result
	// slots, then restore the caller's original linMemReg (and balance SP) and return.
	a.SubImm64(X10, linMemReg, offCustomCtx)
	a.Load64(X10, X10, 0)
	a.Load64(X3, SP, 8) // reload the wrapper results pointer from the saved slot
	resultBase := X10
	resultOffset := uint32(hcResults)
	if wide {
		resultBase = X11
		resultOffset = 0
		a.Load32(X11, X10, uint32(hcWideBase+4))
		a.AddShifted(X11, X10, X11, 3, false)
		a.AddImm64(X11, X11, uint32(hcWideBase+hcWideArgs))
	}
	emitHostThunkTransfers(a, X9, resultBase, X3, resultOffset, 0, resultSlots)
	a.Load64(LR, SP, 16)
	a.LdpPost(linMemReg, X3, SP, 32) // restore caller linMemReg (X3 reload is harmless), SP += 32
	a.Ret()
	return a.B
}

// Basedata scratch offsets (negative from the linMem base), matching the runtime
// and backend/railshot/arm64: a scratch cell to carry the indirect code pointer
// across the flush, and the indirect-call table descriptor pointer.
const (
	offCustomCtx    = 40 // host-call log pointer / sync host-call control frame
	offSpillRegion  = 48 // 8B scratch
	offStackFence   = 72 // low stack bound for the fence check
	offTablePtr     = 80 // table descriptor pointer
	offMemoryDirPtr = abi.MemoryDirPtrOffset
	// offTrapHandlerPtr (32), offTrapStackReentry (24), and offTrapCellPtr
	// (== abi.TrapCellPtrOffset) are defined in memory.go.
)

// Control-frame field offsets for the synchronous host-call protocol. A
// returning host import needs no async log, so it reuses the customCtx slot
// (offCustomCtx) for its control frame. These MUST match
// src/core/runtime/hostcall_arm64.go (hcSavedSP..hcResults, maxHostArity=64).
const (
	hcTrampoline           = 176 // u64: hostCallStub address (published per-instance by CallWithHost)
	hcImportIdx            = 184 // u32: native -> Go
	hcNArgs                = 188 // u32: low 16 bits = param slots, high 16 bits = result slots
	hcArgs                 = 192 // [64]u64: native -> Go
	hcResults              = 704 // [64]u64: Go -> native (== hcArgs + 64*8)
	hcWideBase             = hcResults + maxSyncHostSlots*8
	hcWideArgs       int32 = 8
	maxSyncHostSlots       = 64 // must match runtime.MaxHostArity / maxHostArity
)

// copyInstanceContext runs only at flushed cross-instance transfer boundaries;
// X8 and X9 are therefore free call-clobbered scratch registers. The GC native
// view lives 280 bytes below linMem, outside STUR's signed 9-bit range, so form
// that destination address explicitly without clobbering the live dispatch
// pointer in X16 or target entry in X17.
func (f *fn) copyInstanceContext(dst, src Reg) {
	// The source descriptor is contiguous. Pair its loads, and pair the two
	// destination runs whose basedata cells are contiguous as well. The register
	// order in the first STP is reversed because basedata grows toward lower
	// addresses from dst.
	f.ld64(X9, src, 0)
	f.st64(dst, -offCustomCtx, X9)
	f.a.LdpOffset(X8, X9, src, 8)
	f.a.StpOffset(X9, X8, dst, -int32(offFuncRefDescPtr))
	f.a.LdpOffset(X8, X9, src, 24)
	f.a.StpOffset(X8, X9, dst, -int32(offPassiveElemPtr))
	f.a.LdpOffset(X8, X9, src, 40)
	f.st64(dst, -int32(offPassiveDataPtr), X8)
	f.st64(dst, -int32(offTableDirPtr), X9)
	f.a.LdpOffset(X8, X9, src, 56)
	f.st64(dst, -int32(offMemoryDirPtr), X8)
	f.st64(dst, -int32(offImportDispatchPtr), X9)
	// Exception tag identities follow the callee instance, not shared Memory.
	// This cell is immediately outside the wrapper tail bank so context and all
	// staged arguments remain valid together during wrapper entry.
	f.ld64(X9, src, runtime.InstanceContextEHTagDirOffset)
	f.st64(dst, -int32(abi.EHTagDirPtrOffset), X9)
	f.ld64(X9, src, runtime.InstanceContextGCNativeViewOffset)
	f.a.SubImm64(X8, dst, uint32(abi.GCNativeViewPtrOffset))
	f.a.Store64(X9, X8, 0)
}

// A bound ordinary Go thunk can use its known control-frame ABI directly.
// The instance's tagged dispatch word proves this is not a same-context Wasm
// target. Both alternatives join with canonical operands and homed locals.
func (f *fn) emitDynamicHostOrCrossInstance(b ImportBinding, ft *wasm.CompType) error {
	if !b.Dynamic || !f.dynamicHostFast || f.gcFrameRoots != nil && f.gcFrameRoots.Candidate && !f.gcFrameRoots.UnwindOnly || funcTypeSlots(ft.Params) > maxSyncHostSlots || funcTypeSlots(ft.Results) > maxSyncHostSlots {
		return f.emitCrossInstanceCall(b, ft)
	}
	for _, typ := range ft.Params {
		if typ.Kind() != wasm.ValNum || mtOf(typ) == mtV128 {
			return f.emitCrossInstanceCall(b, ft)
		}
	}
	for _, typ := range ft.Results {
		if typ.Kind() != wasm.ValNum || mtOf(typ) == mtV128 {
			return f.emitCrossInstanceCall(b, ft)
		}
	}
	roots := f.rootsBottomToTop()
	types := append([]machineType(nil), f.logicalTypes(roots)...)
	rootFlags := gcRootFlags(roots)
	if f.gcFrameRoots == nil && f.emitGuardedNativeImportCall(ft, roots, types) {
		f.stats.call(callKindImportDispatch)
		return nil
	}
	f.flush()

	locals := append([]localDef(nil), f.locals...)
	if b.ImportIndex > uint32((1<<31-1-runtime.ImportDispatchCallerContextOffset)/runtime.ImportDispatchEntryBytes) {
		return fmt.Errorf("import dispatch index overflows displacement")
	}
	disp := int32(b.ImportIndex * runtime.ImportDispatchEntryBytes)
	f.loadImportDispatchBase(X16)
	f.ld64(X12, X16, disp+runtime.ImportDispatchCallerContextOffset)
	nativeEarly := f.nativeLeafContextShortcut(b, ft, false) && f.m.ImportedFuncCount() > 1 && f.m.GlobalCount() == 0 && f.usesCalls && len(locals) <= len(localStateSnapshot{}) && !f.pinnedLocalMask.has(X16) && !f.pinnedLocalMask.has(X17)
	nativeBranch := -1
	if nativeEarly {
		f.a.AndImm64(X17, X12, runtime.ImportDispatchCallerNativeLeafTag)
		nativeBranch = f.a.Cbnz64(X17)
	}
	f.a.AndImm64(X12, X12, runtime.ImportDispatchCallerGoHostTag)
	slow := f.a.Cbz64(X12)
	callsiteIndex := f.gcCallsiteIndex
	if err := f.callHostSync(int(b.ImportIndex), ft); err != nil {
		return err
	}
	if f.preserveNativeImportLocals(f.nativeLeafContextShortcut(b, ft, false)) {
		var saved localStateSnapshot
		for x := range locals {
			saved[x] = locals[x].state
		}
		f.restoreNativeLeafPreservedLocals(saved)
	}
	f.flush()
	resultTypes := append([]machineType(nil), f.logicalTypes(f.rootsBottomToTop())...)
	resultFlags := gcRootFlags(f.rootsBottomToTop())
	fastLocals := append([]localDef(nil), f.locals...)
	done := f.a.Branch()
	f.patchBranch19(slow, f.a.Len())
	copy(f.locals, locals)
	f.setDepthTypesWithGCRoots(types, rootFlags)
	// These exclusive machine branches implement one logical Wasm call.
	f.gcCallsiteIndex = callsiteIndex
	if err := f.emitCrossInstanceCall(b, ft); err != nil {
		return err
	}
	f.flush()
	for i := range f.locals {
		if f.locals[i].state != fastLocals[i].state {
			return fmt.Errorf("direct Go import local-state join differs at local %d: cross=%d host=%d", i, f.locals[i].state, fastLocals[i].state)
		}
	}
	if nativeBranch >= 0 {
		crossDone := f.a.Branch()
		f.patchBranch19(nativeBranch, f.a.Len())
		copy(f.locals, locals)
		f.setDepthTypesWithGCRoots(types, rootFlags)
		// This branch is an already-verified native leaf. Load its target
		// before local stores and large SP-address calculations use X16.
		target := X17
		if f.cacheNativeImportTarget {
			target = X24
		} else {
			f.ld64(X17, X16, disp+runtime.ImportDispatchCodePtrOffset)
		}
		f.spillLocalsForClobbers((1<<18)-1, 0)
		argSlot := slotsOfTypes(types[:len(types)-len(ft.Params)])
		f.ld32(X0, SP, f.spillOff(argSlot))
		if len(ft.Params) == 2 {
			f.ld32(X1, SP, f.spillOff(argSlot+1))
		}
		if !f.cacheNativeImportTarget {
			f.a.AddImm64(X17, X17, runtime.NativeScalarLeafRegisterEntryOffset)
		}
		if regallocCheckEnabled {
			f.checkCallClobber()
		}
		f.stats.call(callKindImportDispatch)
		f.a.Blr(target)
		f.st64(SP, f.spillOff(argSlot), X0)
		for i := range f.locals {
			if f.locals[i].state != fastLocals[i].state {
				return fmt.Errorf("native import local-state join differs at local %d", i)
			}
		}
		f.patchBranch26(crossDone, f.a.Len())
	}
	f.patchBranch26(done, f.a.Len())
	f.setDepthTypesWithGCRoots(resultTypes, resultFlags)
	return nil
}

// emitGuardedNativeImportCall is reachable only inside the entry-guarded body.
// Its immutable native tag excludes Go/foreign dispatch for every import alias.
// This emitter canonicalizes older values; native leaves preserve their pins.
func (f *fn) emitGuardedNativeImportCall(ft *wasm.CompType, roots []*elem, types []machineType) bool {
	if !f.cacheNativeImportTarget || f.sc == nil || !f.sc.nativeImportFast {
		return false
	}
	p := len(ft.Params)
	argSlot := slotsOfTypes(types[:len(types)-p])
	directArg := f.threadedMemory0 && p == 1 && f.pinned == 0 && len(f.intervalLast) == 0 && f.pinnedLocalMask&((1<<18)-1) == 0 && nativeSharedArgPrefixSafe(roots) && os.Getenv("WAGO_ARM64_SHARED_IMPORT_ARG_REG") != "0"
	var arg Reg
	var owned bool
	savedPinned := f.pinned
	if directArg {
		arg, owned = f.materializeRead(f.popValue())
		f.pinned = f.pinned.add(arg)
	}
	f.flush()
	f.spillLocalsForClobbers((1<<18)-1, 0)
	if directArg {
		f.a.MovReg32(X0, arg)
		f.pinned = savedPinned
		if owned {
			f.release(arg)
		}
		f.stats.peep("shared-native-register-argument")
	} else {
		f.ld32(X0, SP, f.spillOff(argSlot))
		if p == 2 {
			f.ld32(X1, SP, f.spillOff(argSlot+1))
		}
	}
	if regallocCheckEnabled {
		f.checkCallClobber()
	}
	f.a.Blr(X24)
	if f.threadedMemory0 && os.Getenv("WAGO_ARM64_SHARED_IMPORT_RESULT_REG") != "0" {
		// The guarded native body cannot enter Go; X0 is the live i32 result.
		f.setDepthTypesWithGCRoots(types[:len(types)-p], nil)
		f.pushReg(X0, mtI32)
		f.stats.peep("shared-native-register-result")
	} else {
		if need := argSlot + 1; need > f.maxSpill {
			f.maxSpill = need
		}
		f.st64(SP, f.spillOff(argSlot), X0)
		f.setDepthTypesWithGCRoots(append(types[:len(types)-p], mtI32), nil)
	}
	return true
}

func (f *fn) nativeLeafContextShortcut(b ImportBinding, ft *wasm.CompType, recordRoots bool) bool {
	// Even zero-root unwind plans require a return map. All alternatives must
	// agree before emission: a native shortcut cannot bypass that callsite.
	recordRoots = recordRoots || f.gcFrameRoots != nil && f.gcFrameRoots.Candidate
	p := len(ft.Params)
	contextShortcut := len(f.m.Imports) > 1 || len(f.m.Memories) > 0 || len(f.m.Globals) > 0 || len(f.m.Tables) > 0
	return contextShortcut && b.Dynamic && !recordRoots && p >= 1 && p <= 2 && len(ft.Results) == 1 && ft.Results[0] == wasm.I32 && ft.Params[0] == wasm.I32 && (p == 1 || ft.Params[1] == wasm.I32)
}

func (f *fn) restoreNativeLeafPreservedLocals(saved localStateSnapshot) {
	for x := 0; x < f.nLocals; x++ {
		reg, fp, ok := f.pinReg(x)
		if !ok || !fp && reg < 18 {
			continue
		}
		if saved[x] == lsReg || saved[x] == lsStackReg {
			f.loadLocalReg(x, reg, fp)
		}
		f.locals[x].state = saved[x]
	}
}

// emitCrossInstanceCall lowers a call to an imported function that is bound to
// another instance's function (cross-instance linking). Unlike a host import
// (which logs and returns void), this is a real native call into the callee
// instance, staying on the same foreign stack. The callee's offset-0 entry
// re-establishes ITS module context from X1=linMem (linMemReg, memSize X27, module
// globals X23-X25), so the caller's whole-module-invariant registers are
// preserved across the call by STP/LDP; the three per-execution control words
// (trap re-entry, stack fence, trap cell) are copied caller→callee so a trap in
// the callee unwinds to this execution's enterNative. Production code loads the
// callee entry, home memory, and target/caller contexts from the import dispatch
// cell; the immediate form remains only for focused backend callers.
func (f *fn) emitCrossInstanceCall(b ImportBinding, ft *wasm.CompType) error {
	rootOffsets, recordRoots := f.prepareGCFrameCallsite(len(ft.Params))
	kind := callKindCrossInstance
	if b.Dynamic {
		kind = callKindImportDispatch
	}
	f.stats.call(kind)
	p := len(ft.Params)
	roots := f.rootsBottomToTop()
	d := len(roots)
	types := f.tmpTypes[:0]
	slotOf := f.tmpStackSlots[:0]
	slotTop := 0
	for _, root := range roots {
		typ := root.st.typ
		if root.elemKind() == ekDeferred && root.st.typ != mtNone {
			typ = root.st.typ
		}
		types = append(types, typ)
		slotOf = append(slotOf, uint32(slotTop))
		slotTop += typ.stackSlots()
	}
	f.tmpTypes = types
	f.tmpStackSlots = slotOf
	belowTypes := f.tmpTypes2[:0]
	if cap(belowTypes) < d-p {
		belowTypes = make([]machineType, 0, d-p)
	}
	belowTypes = append(belowTypes, types[:d-p]...)
	f.tmpTypes2 = belowTypes
	belowGCRoots := f.gcFramePrefixRoots(roots, d-p)
	resultSlot := slotTop
	resultSlots := funcTypeSlots(ft.Results)

	if f.emitGuardedNativeImportCall(ft, roots, types) {
		return nil
	}
	f.flush()
	f.storePinnedGlobals(false) // value-pinned globals → cells (reloaded after; callee can't touch B's cells)

	if need := resultSlot + resultSlots; need > f.maxSpill {
		f.maxSpill = need
	}
	argOff := f.spillOff(resultSlot) // p==0: unused, but a valid in-frame address
	if p > 0 {
		argOff = f.spillOff(int(slotOf[d-p]))
	}
	nativeCandidate := f.nativeLeafContextShortcut(b, ft, recordRoots)
	var nativeLocals localStateSnapshot
	// Import aliases and proven fixed shared loops preserve native callee-saved
	// pins. Every dynamic alternative joins with this same saved local state.
	preserveNativeLocals := f.preserveNativeImportLocals(nativeCandidate)
	if preserveNativeLocals {
		// Native leaf validation excludes every FP instruction and GP registers
		// X18 and above. Home only the local pins its wrapper can overwrite.
		f.spillLocalsForClobbers((1<<18)-1, 0)
		nativeLocals, _ = f.snapshotLocalStates()
	} else {
		f.spillLocalsForCall()
	}
	f.storeModuleGlobals(X9) // cross-instance boundary: shared globals must be cell-coherent

	// Only a runtime-verified native leaf may bypass context publication. Its
	// wrapper ABI and caller-clobbered register set stay unchanged. Operands
	// are homed above; proven preserved local pins can remain in registers.
	nativeLeaf := -1
	goDirect := -1
	directSharedGo := f.opt(optDirectGoHostImport) && f.cacheImportDispatch && f.threadedMemory0 && f.m.ImportedFuncCount() == 1 && !recordRoots && len(ft.Params) == 1 && ft.Params[0] == wasm.I32 && len(ft.Results) == 1 && ft.Results[0] == wasm.I32 && os.Getenv("WAGO_ARM64_FIXED_SHARED_GOCALL") != "0"
	// A single-import resource-free module retains its lean existing wrapper
	// route: the extra dispatch branch regresses short dependent callback loops.
	// Stateful modules and import aliases amortize this branch against context
	// publication, while keeping the same native-leaf contract.
	if nativeCandidate {
		disp := int32(b.ImportIndex * runtime.ImportDispatchEntryBytes)
		f.loadImportDispatchBase(X16)
		f.ld64(X12, X16, disp+runtime.ImportDispatchCallerContextOffset)
		if directSharedGo {
			f.a.AndImm64(X17, X12, runtime.ImportDispatchCallerNativeLeafTag)
			nativeLeaf = f.a.Cbnz64(X17)
			f.a.AndImm64(X12, X12, runtime.ImportDispatchCallerGoHostTag)
			goDirect = f.a.Cbnz64(X12)
		} else {
			f.a.AndImm64(X12, X12, runtime.ImportDispatchCallerNativeLeafTag)
			nativeLeaf = f.a.Cbnz64(X12)
		}
	}
	// Only wrapper calls need buffer pointers. The native register branch
	// skips this setup and loads its canonical i32 arguments directly.
	f.a.LeaSP(X0, argOff)
	f.a.LeaSP(X3, f.spillOff(resultSlot))
	if preserveNativeLocals {
		f.spillLocalsForCall()
	}

	// Preserve the caller's module-invariant registers (linMemReg=linMem, X27=memSize,
	// X23-X25=module globals), and X22=the active EH record (3 STP pairs =
	// 48 bytes, so SP stays 16-aligned). An exception-enabled callee inherits X22;
	// a non-EH callee may use it as a local pin, so restore it on normal return.
	f.a.StpPre(linMemReg, X24, SP, -16)
	f.a.StpPre(X25, X23, SP, -16)
	f.a.StpPre(X27, ehReg, SP, -16)

	sameContext := -1
	if b.Dynamic {
		if b.ImportIndex > uint32((1<<31-1-runtime.ImportDispatchCallerContextOffset)/runtime.ImportDispatchEntryBytes) {
			return fmt.Errorf("import dispatch index %d overflows displacement", b.ImportIndex)
		}
		disp := int32(b.ImportIndex * runtime.ImportDispatchEntryBytes)
		f.loadImportDispatchBase(X16)
		f.ld64(X1, X16, disp+runtime.ImportDispatchHomeLinMemOffset)     // wrapper-ABI arg 1
		f.ld64(X10, X16, disp+runtime.ImportDispatchTargetContextOffset) // target context
		f.ld64(X17, X16, disp+runtime.ImportDispatchCodePtrOffset)       // wrapper entry
		f.ld64(X12, X16, disp+runtime.ImportDispatchCallerContextOffset)
		f.a.AndImm64(X12, X12, ^runtime.ImportDispatchCallerTagMask)
		// Ordinary host imports target this exact instance context. Its basedata
		// is already installed, so publish neither a context image nor identical
		// trap words. Equal linear memory alone is insufficient for aliased
		// instances: their context identities must also match.
		f.cmpRR(X1, linMemReg, true)
		differentHome := f.a.Bcond(condNE)
		f.cmpRR(X10, X12, true)
		differentContext := f.a.Bcond(condNE)
		f.a.StpPre(ZR, X17, SP, -16) // zero caller context means no switch occurred
		sameContext = f.a.Branch()
		f.patchBranch19(differentHome, f.a.Len())
		f.patchBranch19(differentContext, f.a.Len())
		f.copyInstanceContext(X1, X10)
		f.a.StpPre(X12, X17, SP, -16)
		// The forward branch skips the per-execution control-word copies below.

	} else {
		f.a.MovImm64(X1, b.CalleeLinMem) // callee linMem base (wrapper-ABI arg 1)
	}
	// Copy the per-execution control words caller(linMemReg)→callee(X1).
	f.ld64(X9, linMemReg, -int32(offTrapHandlerPtr))
	f.st64(X1, -int32(offTrapHandlerPtr), X9)
	f.ld64(X9, linMemReg, -int32(offTrapStackReentry))
	f.st64(X1, -int32(offTrapStackReentry), X9)
	f.ld64(X9, linMemReg, -int32(offStackFence))
	f.st64(X1, -int32(offStackFence), X9)
	f.ld64(X9, linMemReg, -int32(offTrapCellPtr))
	f.st64(X1, -int32(offTrapCellPtr), X9)

	if sameContext >= 0 {
		f.patchBranch26(sameContext, f.a.Len())
	}

	if b.Dynamic {
		if regallocCheckEnabled {
			f.checkCallClobber()
		}
		f.a.Blr(X17)
	} else {
		f.a.MovImm64(X9, b.CalleeEntry)
		if regallocCheckEnabled {
			f.checkCallClobber()
		}
		f.a.Blr(X9)
	}
	if recordRoots {
		stackAdjust := uint32(48)
		if b.Dynamic {
			stackAdjust = 64
		}
		f.gcFrameRoots.RecordCallsite(uint32(f.a.Len()), stackAdjust, rootOffsets)
	}

	if b.Dynamic {
		f.a.LdpPost(X16, X17, SP, 16) // caller context + saved target
	}
	f.a.LdpPost(X27, ehReg, SP, 16)
	f.a.LdpPost(X25, X23, SP, 16)
	f.a.LdpPost(linMemReg, X24, SP, 16)
	if b.Dynamic {
		unchanged := f.a.Cbz64(X16)
		f.copyInstanceContext(linMemReg, X16)
		f.patchBranch19(unchanged, f.a.Len())
	}
	// A dynamic target may be arbitrary host code that synchronously re-enters
	// this caller and grows its memory. Reload from the restored caller context
	// before its continuation resumes.
	f.refreshCachedMemoryBoundAfterExternalCall()
	if preserveNativeLocals {
		// The ordinary branch may clobber every pin. Restore its original
		// register state before joining the native branch, where those values
		// never left their registers. Dirty slots remain conservatively dirty.
		f.restoreNativeLeafPreservedLocals(nativeLocals)
	}
	if nativeLeaf >= 0 {
		done := f.a.Branch()
		goDone := -1
		if goDirect >= 0 {
			f.patchBranch19(goDirect, f.a.Len())
			if preserveNativeLocals {
				f.spillLocalsForCall()
			}
			// The fixed shared import-only proof excludes helper/foreign guest
			// calls and GC roots. The runtime Go-host tag selects ordinary
			// rooted Go dispatch, with unchanged parked ownership and traps.
			f.ld64(X11, linMemReg, -int32(offCustomCtx))
			f.ld32(X9, SP, argOff)
			f.syncHostStore64(X11, hcArgs, X9)
			f.a.MovImm64(X16, uint64(b.ImportIndex))
			f.st32(X11, hcImportIdx, X16)
			f.a.MovImm64(X16, 0x10001)
			f.st32(X11, hcNArgs, X16)
			f.ld64(X16, X11, hcTrampoline)
			if regallocCheckEnabled {
				f.checkCallClobber()
			}
			f.a.Blr(X16)
			f.ld64(X11, linMemReg, -int32(offCustomCtx))
			f.syncHostLoad64(X9, X11, hcResults)
			f.st64(SP, f.spillOff(resultSlot), X9)
			f.refreshCachedMemoryBoundAfterExternalCall()
			if preserveNativeLocals {
				f.restoreNativeLeafPreservedLocals(nativeLocals)
			}
			f.stats.peep("fixed-shared-direct-go")
			goDone = f.a.Branch()
		}
		f.patchBranch19(nativeLeaf, f.a.Len())
		// Reload the cell target after the tag test. Native leaves keep this
		// instance's basedata and cached memory bound intact.
		disp := int32(b.ImportIndex * runtime.ImportDispatchEntryBytes)
		f.ld64(X17, X16, disp+runtime.ImportDispatchCodePtrOffset)
		f.ld32(X0, SP, argOff)
		if p == 2 {
			f.ld32(X1, SP, argOff+8)
		}
		f.a.AddImm64(X17, X17, runtime.NativeScalarLeafRegisterEntryOffset)
		if regallocCheckEnabled {
			f.checkCallClobber()
		}
		f.a.Blr(X17)
		f.st64(SP, f.spillOff(resultSlot), X0)
		f.patchBranch26(done, f.a.Len())
		if goDone >= 0 {
			f.patchBranch26(goDone, f.a.Len())
		}
	}

	f.reloadLocalsForCall() // non-STACK_REG model only
	f.deriveModuleGlobals() // cross-instance callee may have written shared global cells
	f.derivePinnedGlobals() // reload value-pinned globals from B's cells

	// Pop the arguments and publish the wrapper results without imposing a
	// physical-register arity limit.
	f.finishWrapperResultsWithRoots(belowTypes, belowGCRoots, resultSlot, ft.Results)
	return nil
}

// callInternal lowers a direct call to another local function. Integer-only
// callees use the fast register ABI (args/result in registers); others go
// through the wrapper (sp-buffer) ABI.
func (f *fn) callInternal(localIdx int, ft *wasm.CompType, resHint int) error {
	rootOffsets, recordRoots := f.prepareGCFrameCallsite(len(ft.Params))
	relocBase := len(f.relocs)
	finishRoots := func() {
		if !recordRoots {
			return
		}
		if len(f.relocs) != relocBase+1 {
			f.gcFrameRoots.Exact = false
			return
		}
		f.gcFrameRoots.RecordCallsite(uint32(f.relocs[relocBase].at+4), 0, rootOffsets)
	}
	if f.opt(optRegABI) && stagedTailRegisterABI(ft, f.stagedTailDescriptors) {
		if sigIsIntOnly(ft) {
			f.stats.call(callKindRegisterABI)
			preservesPins := f.directCalleePreservesPins(localIdx)
			if recordRoots {
				// Exact caller maps name frame slots. Force the ordinary spill-managed
				// call path even for a leaf that could otherwise preserve caller pins.
				preservesPins = false
			}
			f.emitRegisterCall(localIdx, ft, resHint, preservesPins)
		} else {
			f.stats.call(callKindMixed)
			f.emitMixedRegisterCall(localIdx, ft)
		}
		finishRoots()
		return nil
	}
	f.stats.call(callKindWrapper)
	f.emitWrapperCall(ft, func() {
		if regallocCheckEnabled {
			f.checkCallClobber()
		}
		site := f.a.Bl()
		f.relocs = append(f.relocs, f.newCallReloc(site, localIdx, false))
	})
	finishRoots()
	return nil
}

// consumeGCFrameCallsite advances the source-level call-liveness stream for a
// local call removed by inlining. The splice is a leaf and cannot suspend, so it
// needs no native return-PC map, but later real calls must still use their own
// source call masks.
func (f *fn) consumeGCFrameCallsite() {
	plan := f.gcFrameRoots
	if plan == nil || !plan.Candidate {
		return
	}
	if f.gcCallsiteIndex >= plan.CallMaskCount() {
		plan.Exact = false
		return
	}
	f.gcCallsiteIndex++
}

func (f *fn) prepareGCFrameCallsite(paramCount int) ([]uint32, bool) {
	plan := f.gcFrameRoots
	if plan == nil || !plan.Candidate {
		return nil, false
	}
	siteIndex := f.gcCallsiteIndex
	f.gcCallsiteIndex++
	if siteIndex >= plan.CallMaskCount() {
		plan.Exact = false
		return nil, false
	}
	roots := f.rootsBottomToTop()
	if paramCount < 0 || paramCount > len(roots) {
		plan.Exact = false
		return nil, false
	}
	f.materializeGCFrameLocalsAt(siteIndex, true)
	offsets := f.tmpGCOffsets[:0]
	defer func() {
		if uint64(cap(offsets))*4 <= shared.MaxRetainedGCCallsiteOffsetBytes {
			f.tmpGCOffsets = offsets[:0]
		} else {
			f.tmpGCOffsets = nil
		}
	}()
	if !plan.VisitLiveLocals(siteIndex, true, func(root int) {
		offsets = append(offsets, plan.Locals[root].Offset)
	}) {
		plan.Exact = false
		return nil, false
	}
	hidden := len(roots) - paramCount
	slot := 0
	for i, root := range roots {
		if i < hidden && root.elemKind() == ekValue && root.st.hasGCRoot() {
			off := f.spillOff(slot)
			if off < 0 {
				plan.Exact = false
				return nil, false
			}
			offsets = append(offsets, uint32(off))
		}
		slot += rootMachineType(root).stackSlots()
	}
	offsets = append(offsets, plan.FixedOffsets()...)
	sort.Slice(offsets, func(i, j int) bool { return offsets[i] < offsets[j] })
	return offsets, true
}

// emitRegisterCall lowers an internal call to a register-ABI function: the top p
// operands become the argument registers (via a parallel move), the callee is
// entered at its internal entry, and the single result is taken from X0.
// resHint >= 0 fuses a following `local.set resHint`: X0 moves straight into
// the pinned local's register instead of an allocated result register.
func (f *fn) emitRegisterCall(localIdx int, ft *wasm.CompType, resHint int, preservesPins bool) {
	f.emitRegisterCallVia(ft, resHint, preservesPins, localIdx, regNone)
}

// emitRegisterCallVia emits either a direct internal BL (localIdx >= 0) or an
// indirect BLR. Explicit operands avoid allocating a closure at every wasm call.
func (f *fn) emitRegisterCallVia(ft *wasm.CompType, resHint int, preservesPins bool, localIdx int, indirect Reg) uint32 {
	if indirect != regNone {
		// Argument staging owns X0-X7, including a target selected under pressure.
		f.a.MovReg64(X17, indirect)
		indirect = X17
	}
	p, rN := len(ft.Params), len(ft.Results)
	d := f.depth()
	allRoots := f.rootsBottomToTop()
	allTypes := f.logicalTypes(allRoots)
	belowTypes := append(f.tmpTypes2[:0], allTypes[:d-p]...)
	f.tmpTypes2 = belowTypes
	belowSlots := slotsOfTypes(belowTypes)
	belowGCRoots := f.gcFramePrefixRoots(allRoots, d-p)
	if !preservesPins {
		f.storePinnedGlobals(false) // spill value-pinned globals to their cells before the call (scratch is free here)
	}

	// Identify the p argument roots (top of stack), deepest first.
	argRoots := f.tmpRoots[:0]
	if cap(argRoots) < p {
		argRoots = make([]*elem, 0, p)
	}
	argRoots = argRoots[:p]
	f.tmpRoots = argRoots
	cur := f.s.back()
	for i := p - 1; i >= 0; i-- {
		argRoots[i] = cur
		if i > 0 {
			cur = f.s.prev(f.s.baseOfValentBlock(cur))
		}
	}

	// Capture register args and overlapping slots before the lower stack flush.
	moves := f.tmpMoves[:0]
	deferred := f.tmpDeferred[:0]
	for i := 0; i < p; i++ {
		root := argRoots[i]
		capture := root.isDeferred()
		if root.elemKind() == ekValue {
			switch root.st.kind {
			case stReg, stLocalReg, stGlobReg, stMemRef:
				capture = true
			case stSlot:
				capture = root.st.slotIndex() < belowSlots
			}
		}
		if capture {
			reg := f.materialize(root) // stMemRef → emits the deferred load into its addr reg
			f.pinned = f.pinned.add(reg)
			moves = append(moves, regMove{dst: intArgRegs[i], src: reg})
		} else {
			deferred = append(deferred, deferredArg{target: intArgRegs[i], root: root})
		}
	}
	if p > 0 {
		f.stats.addCallFlush()
		f.flushBelow(argRoots[0]) // operands below the args → canonical slots
	} else {
		f.stats.addCallFlush()
		f.flush()
	}
	// Store dirty pinned locals BEFORE the argument staging: a pinned local may
	// live in an argument register (X5-X7 for 6+-arg calls) or be clobbered by the
	// staging below. Their values were already copied out above where an argument
	// reads them. Lazy reload on the next read — WARP's STACK_REG model.
	if !preservesPins {
		f.spillLocalsForCall()
	}

	// Unpin the owned source registers, then resolve the parallel move into targets.
	for _, m := range moves {
		f.pinned = f.pinned.remove(m.src)
	}
	// AArch64 has no XCHG: a register swap goes through the backend scratch X16.
	var checkMoves func()
	if regallocCheckEnabled {
		checkMoves = f.checkBeginRegMoves(moves, false)
		defer checkMoves()
	}
	swapChains := resolveRegMovesWindow(moves,
		func(dst, src Reg) { f.a.MovReg64(dst, src) },
		func(x, y Reg) {
			f.a.MovReg64(X16, x)
			f.a.MovReg64(x, y)
			f.a.MovReg64(y, X16)
		},
		func(a, b, c Reg) {
			f.a.MovReg64(X16, a)
			f.a.MovReg64(a, b)
			f.a.MovReg64(b, c)
			f.a.MovReg64(c, X16)
		})
	if regallocCheckEnabled {
		checkMoves()
	}
	f.stats.peepN("machine-swap-chain", swapChains)
	f.tmpMoves = moves[:0]
	for _, da := range deferred {
		switch da.root.st.kind {
		case stConst:
			f.loadConst(da.target, da.root.st)
		case stSlot:
			f.ld64(da.target, SP, f.spillOff(da.root.st.slotIndex()))
		case stLocalRef:
			f.ld64(da.target, SP, f.localOff(da.root.st.index()))
		}
	}
	f.tmpDeferred = deferred[:0]

	// Consume the args while preserving v128 slot widths and collector identity.
	f.setDepthTypesWithGCRoots(belowTypes, belowGCRoots)

	// No environment passing: linMemReg (linMem) is a whole-module invariant and the
	// trap cell pointer lives in basedata — the callee inherits both (WARP model).
	var returnOffset uint32
	if localIdx >= 0 {
		if regallocCheckEnabled {
			f.checkCallClobber()
		}
		site := f.a.Bl()
		f.relocs = append(f.relocs, f.newCallReloc(site, localIdx, true))
		returnOffset = uint32(site + 4)
	} else {
		if regallocCheckEnabled {
			f.checkCallClobber()
		}
		f.a.Blr(indirect)
		returnOffset = uint32(f.a.Len())
	}

	// A pin-preserving callee leaves the caller state untouched, so its result can
	// remain allocator-owned in X0. Calls that reload state still copy it out first
	// because those reload sequences may use X0 as scratch.
	resReg := regNone
	if rN == 1 && resHint < 0 {
		if preservesPins {
			resReg = X0
			f.stats.peep("call-result-x0")
		} else {
			resReg = f.allocReg(maskOf(X0))
			f.a.MovReg64(resReg, X0)
		}
		f.pinned = f.pinned.add(resReg)
	}
	var pairRes [2]Reg
	if rN == 2 && isIntValType(ft.Results[0]) {
		if preservesPins {
			pairRes = [2]Reg{X0, X1}
		} else {
			pairRes[0] = f.allocReg(maskOf(X0, X1))
			f.pinned = f.pinned.add(pairRes[0])
			f.a.MovReg64(pairRes[0], X0)
			pairRes[1] = f.allocReg(maskOf(X0, X1))
			f.a.MovReg64(pairRes[1], X1)
		}
		f.pinned = f.pinned.add(pairRes[0]).add(pairRes[1])
	}
	var quadRes [8]Reg
	resultsInSlots := false
	if registerQuadResultsSupported && rN > 2 {
		// Results remain protected until local/global reloads finish. Whole-
		// function pins can leave fewer destinations than the result count.
		avoid := maskOf(X0, X1, X2, X3, X4, X5, X6, X7)
		blocked := avoid.union(f.pinned).union(f.pinnedLocalMask).union(f.reserved)
		available := 0
		for _, reg := range gpAlloc {
			if !blocked.has(reg) {
				available++
			}
		}
		resultsInSlots = available < rN
		base := 0
		if resultsInSlots {
			base = f.allocSpillSlots(rN)
		}
		for i, src := range []Reg{X0, X1, X2, X3, X4, X5, X6, X7}[:rN] {
			if resultsInSlots {
				f.st64(SP, f.spillOff(base+i), src)
				value := f.pushValue(storage{kind: stSlot, typ: mtOf(ft.Results[i]), slot: uint32(base + i)})
				value.st.setGCRoot(f.tracksGCFrameRoots() && arm64GCFrameRefType(f.m, ft.Results[i]))
			} else {
				quadRes[i] = f.allocReg(avoid)
				f.a.MovReg64(quadRes[i], src)
				f.pinned = f.pinned.add(quadRes[i])
			}
		}
	}
	if !preservesPins {
		f.reloadLocalsForCall() // non-STACK_REG model only
		f.derivePinnedGlobals() // reload value-pinned globals: the callee may have changed the shared cell
	}
	// No post-call trap check: a callee trap jumps straight back to enterNative
	// via emitTrap's handler-jump, so control never returns here with *trap set.

	if rN == 1 && resHint >= 0 {
		// Fused `local.set`: the result lands directly in the pinned local's
		// register — after any eager post-call reload, which would otherwise
		// overwrite it with the stale slot value.
		pr, _, _ := f.pinReg(resHint)
		if f.canonicalI32Local(resHint) && ft.Results[0] == wasm.I32 {
			f.a.MovReg32(pr, X0)
			f.stats.peep("local-i32-canonicalize")
		} else {
			f.a.MovReg64(pr, X0)
		}
		f.markLocalDirty(resHint)
	}

	if rN == 1 && resHint < 0 {
		f.pinned = f.pinned.remove(resReg)
		f.pushReg(resReg, mtOf(ft.Results[0]))
	}
	if preparedDirectFloatSupported && rN == 2 && isFloatValType(ft.Results[0]) {
		for i := range 2 {
			f.pushFReg(Reg(i), mtOf(ft.Results[i]))
		}
	} else if rN == 2 {
		for i, reg := range pairRes {
			f.pinned = f.pinned.remove(reg)
			f.pushReg(reg, mtOf(ft.Results[i]))
		}
	}
	if registerQuadResultsSupported && rN > 2 && !resultsInSlots {
		for i, reg := range quadRes[:rN] {
			f.pinned = f.pinned.remove(reg)
			f.pushReg(reg, mtOf(ft.Results[i]))
		}
	}
	return returnOffset
}

// directCalleePreservesPins returns the module-precomputed leaf classification
// for one direct target. This is compile-time only; execution stays a plain BL.
func (f *fn) directCalleePreservesPins(localIdx int) bool {
	// Even a pin-preserving leaf can throw. An active catch needs current local
	// homes, so keep the spill-managed call path until this try_table ends.
	if f.ehTryDepth != 0 {
		return false
	}
	if localIdx < 0 || localIdx >= len(f.calleeHints) {
		return false
	}
	return f.calleeHints[localIdx].flags.has(hintPreservesCallerPins)
}

// emitMixedRegisterCall uses the register ABI for signatures containing floats.
// GP and FP arguments are staged independently as parallel moves, so values that
// are already resident in registers do not round-trip through canonical slots.
func (f *fn) emitMixedRegisterCall(localIdx int, ft *wasm.CompType) {
	f.emitMixedRegisterCallVia(localIdx, regNone, ft)
}

// stageFlushSpills protects sources from the canonical stores in flushBelow.
func (f *fn) stageFlushSpills(belowSlots int, belowRoots []*elem) {
	if belowSlots == 0 {
		return
	}
	nextSlot := f.spillFloor
	direct := true
	for pass := 0; pass < 2; pass++ {
		rootIndex := 0
		canonicalSlot := 0
		overlaps := false
		for e := f.s.next(f.s.head); e != f.s.head; e = f.s.next(e) {
			canonical := false
			destination := -1
			if rootIndex < len(belowRoots) && e == belowRoots[rootIndex] {
				destination = canonicalSlot
				canonical = e.elemKind() == ekValue && e.st.kind == stSlot && e.st.slotIndex() == canonicalSlot
				canonicalSlot += rootMachineType(e).stackSlots()
				rootIndex++
			}
			if e.elemKind() != ekValue || e.st.kind != stSlot {
				continue
			}
			from, width := e.st.slotIndex(), e.st.typ.stackSlots()
			if pass == 0 && from+width > nextSlot {
				nextSlot = from + width
			}
			// A complete root already at its destination is skipped by the flush.
			// Deferred children and arguments never qualify for this exception.
			if from >= belowSlots || canonical {
				continue
			}
			overlaps = true
			if pass == 0 {
				direct = direct && destination >= from
				continue
			}
			for i := 0; i < width; i++ {
				f.ld64(X16, SP, f.spillOff(from+i))
				f.st64(SP, f.spillOff(nextSlot+i), X16)
			}
			e.st.slot = uint32(nextSlot)
			nextSlot += width
		}
		if !overlaps {
			return
		}
		if pass == 0 && direct {
			f.canonicalizeFlushSpills(belowSlots, belowRoots)
			break
		}
	}
	if nextSlot > f.maxSpill {
		f.maxSpill = nextSlot
	}
}

// When every overlapping source is a complete prefix root at or below its own
// destination, copy backwards directly to canonical homes. Each write then lies
// above all earlier sources; no temporary spill range or second copy is needed.
func (f *fn) canonicalizeFlushSpills(slot int, roots []*elem) {
	limit := slot
	for i := len(roots) - 1; i >= 0; i-- {
		root := roots[i]
		width := rootMachineType(root).stackSlots()
		slot -= width
		if root.elemKind() != ekValue || root.st.kind != stSlot {
			continue
		}
		from := root.st.slotIndex()
		if from >= limit || from == slot {
			continue
		}
		// Copy both halves backwards when a vector overlaps its new home.
		for j := width - 1; j >= 0; j-- {
			f.ld64(X16, SP, f.spillOff(from+j))
			f.st64(SP, f.spillOff(slot+j), X16)
		}
		root.st.slot = uint32(slot)
	}
}

func (f *fn) emitMixedRegisterCallVia(localIdx int, indirect Reg, ft *wasm.CompType) uint32 {
	if indirect != regNone {
		// GP argument staging owns X0-X7. Preserve a descriptor target selected in
		// that bank before parallel moves and deferred loads overwrite it.
		f.a.MovReg64(X17, indirect)
		indirect = X17
	}
	p, rN := len(ft.Params), len(ft.Results)
	d := f.depth()
	allRoots := f.rootsBottomToTop()
	allTypes := f.logicalTypes(allRoots)
	belowTypes := append(f.tmpTypes2[:0], allTypes[:d-p]...)
	f.tmpTypes2 = belowTypes
	// Existing and new spills must stay above slots written by flushBelow.
	oldSpillFloor := f.spillFloor
	belowSlots := 0
	for _, typ := range belowTypes {
		belowSlots += typ.stackSlots()
	}
	if belowSlots > f.spillFloor {
		f.spillFloor = belowSlots
	}
	belowGCRoots := f.gcFramePrefixRoots(allRoots, d-p)

	f.storePinnedGlobals(false) // spill value-pinned globals to their cells before the call
	// Materializing arguments preserves these roots and does not reuse tmpRoots.
	argRoots := allRoots[d-p:]
	type deferredMixedArg struct {
		target Reg
		root   *elem
		float  bool
	}
	var gpBuf, fpBuf [8]regMove
	var deferredBuf [16]deferredMixedArg
	gpMoves, fpMoves := gpBuf[:0], fpBuf[:0]
	deferred := deferredBuf[:0]
	gp, fp := 0, 0
	for i, t := range ft.Params {
		mt := mtOf(t)
		root := argRoots[i]
		if mt.isFloat() {
			target := fpArgRegs[fp]
			if root.elemKind() == ekValue && root.st.kind == stLocalReg {
				available := ^uint32(f.blockedFRegs(0))
				if available&(available-1) == 0 {
					// spillLocalsForCall makes this borrowed local's home current.
					deferred = append(deferred, deferredMixedArg{target: target, root: root, float: true})
					f.stats.peep("mixed-call-local-home")
					fp++
					continue
				}
			}
			if root.isDeferred() || (root.elemKind() == ekValue && (root.st.kind == stReg || root.st.kind == stLocalReg || root.st.kind == stGlobReg || root.st.kind == stMemRef)) {
				reg := f.materializeF(root)
				// Keep one V register for later arguments and the below-call flush.
				// Reload overflow arguments after the parallel register moves.
				if uint32(f.blockedFRegs(maskOf(reg))) == ^uint32(0) {
					f.spillF(root)
					deferred = append(deferred, deferredMixedArg{target: target, root: root, float: true})
				} else {
					f.fpinned = f.fpinned.add(reg)
					fpMoves = append(fpMoves, regMove{dst: target, src: reg})
					f.stats.peep("mixed-call-reg-arg")
				}
			} else {
				deferred = append(deferred, deferredMixedArg{target: target, root: root, float: true})
			}
			fp++
		} else {
			target := intArgRegs[gp]
			if root.isDeferred() || (root.elemKind() == ekValue && (root.st.kind == stReg || root.st.kind == stLocalReg || root.st.kind == stGlobReg || root.st.kind == stMemRef)) {
				reg := f.materialize(root)
				f.pinned = f.pinned.add(reg)
				gpMoves = append(gpMoves, regMove{dst: target, src: reg})
				f.stats.peep("mixed-call-reg-arg")
			} else {
				deferred = append(deferred, deferredMixedArg{target: target, root: root})
			}
			gp++
		}
	}
	if p > 0 {
		f.stats.addCallFlush()
		f.flushBelow(argRoots[0])
	} else {
		f.stageFlushSpills(belowSlots, allRoots[:d-p])
		f.stats.addCallFlush()
		f.flush()
	}
	// Save dirty locals before register moves or deferred local-home loads.
	f.spillLocalsForCall()
	for _, m := range gpMoves {
		f.pinned = f.pinned.remove(m.src)
	}
	var checkGPMoves func()
	if regallocCheckEnabled {
		checkGPMoves = f.checkBeginRegMoves(gpMoves, false)
		defer checkGPMoves()
	}
	gpSwapChains := resolveRegMovesWindow(gpMoves,
		func(dst, src Reg) { f.a.MovReg64(dst, src) },
		func(x, y Reg) {
			f.a.MovReg64(X16, x)
			f.a.MovReg64(x, y)
			f.a.MovReg64(y, X16)
		},
		func(a, b, c Reg) {
			f.a.MovReg64(X16, a)
			f.a.MovReg64(a, b)
			f.a.MovReg64(b, c)
			f.a.MovReg64(c, X16)
		})
	if regallocCheckEnabled {
		checkGPMoves()
	}
	f.stats.peepN("machine-swap-chain", gpSwapChains)
	for _, m := range fpMoves {
		f.fpinned = f.fpinned.remove(m.src)
	}
	fpSwapSlot := -1
	var checkFPMoves func()
	if regallocCheckEnabled {
		checkFPMoves = f.checkBeginRegMoves(fpMoves, true)
		defer checkFPMoves()
	}
	fpSwapChains := resolveRegMovesWindow(fpMoves,
		func(dst, src Reg) { f.a.FmovReg(dst, src, true) },
		func(x, y Reg) {
			if fpSwapSlot < 0 {
				fpSwapSlot = f.allocSpillSlot()
			}
			off := f.spillOff(fpSwapSlot)
			f.fst(SP, off, x, true)
			f.a.FmovReg(x, y, true)
			f.fld(y, SP, off, true)
		},
		func(a, b, c Reg) {
			if fpSwapSlot < 0 {
				fpSwapSlot = f.allocSpillSlot()
			}
			off := f.spillOff(fpSwapSlot)
			f.fst(SP, off, a, true)
			f.a.FmovReg(a, b, true)
			f.a.FmovReg(b, c, true)
			f.fld(c, SP, off, true)
		})
	if regallocCheckEnabled {
		checkFPMoves()
	}
	f.stats.peepN("machine-swap-chain", fpSwapChains)
	for _, da := range deferred {
		if da.float {
			switch da.root.st.kind {
			case stConst:
				if da.root.st.typ == mtF64 {
					f.a.MovImm64(X16, uint64(da.root.st.cval))
					f.a.FmovFromGpr(da.target, X16, true)
				} else {
					f.a.MovImm32(X16, int32(uint32(da.root.st.cval)))
					f.a.FmovFromGpr(da.target, X16, false)
				}
			case stSlot:
				// Scalar FP operand spill slots are eight bytes, including f32.
				f.fld(da.target, SP, f.spillOff(da.root.st.slotIndex()), true)
			case stLocalRef, stLocalReg:
				f.fld(da.target, SP, f.localOff(da.root.st.index()), da.root.st.typ == mtF64)
			}
			continue
		}
		switch da.root.st.kind {
		case stConst:
			f.loadConst(da.target, da.root.st)
		case stSlot:
			f.ld64(da.target, SP, f.spillOff(da.root.st.slotIndex()))
		case stLocalRef:
			f.ld64(da.target, SP, f.localOff(da.root.st.index()))
		}
	}
	f.setDepthTypesWithGCRoots(belowTypes, belowGCRoots)
	// Standalone emitter fixtures can omit a physical caller frame record.
	lrSlot := -1
	if !f.makesCalls {
		lrSlot = f.allocSpillSlot()
		f.st64(SP, f.spillOff(lrSlot), LR)
	}
	f.spillFloor = oldSpillFloor

	var returnOffset uint32
	if localIdx >= 0 {
		if regallocCheckEnabled {
			f.checkCallClobber()
		}
		site := f.a.Bl()
		f.relocs = append(f.relocs, f.newCallReloc(site, localIdx, true))
		returnOffset = uint32(site + 4)
	} else {
		if regallocCheckEnabled {
			f.checkCallClobber()
		}
		f.a.Blr(indirect)
		returnOffset = uint32(f.a.Len())
	}
	mixedPair := preparedDirectFloatSupported && rN == 2 && isFloatValType(ft.Results[0]) != isFloatValType(ft.Results[1])
	mixedIntReg := regNone
	if mixedPair {
		mixedIntReg = f.allocReg(maskOf(X0))
		f.a.MovReg64(mixedIntReg, X0)
		f.pinned = f.pinned.add(mixedIntReg)
	}
	mixedWideInts := [2]Reg{regNone, regNone}
	if sigHasMixedWideResults(ft) {
		gp := 0
		for _, typ := range ft.Results {
			if isFloatValType(typ) {
				continue
			}
			reg := f.allocReg(maskOf(X0, X1))
			f.a.MovReg64(reg, []Reg{X0, X1}[gp])
			f.pinned = f.pinned.add(reg)
			mixedWideInts[gp] = reg
			gp++
		}
	}
	if lrSlot >= 0 {
		f.ld64(LR, SP, f.spillOff(lrSlot))
	}
	f.reloadLocalsForCall() // non-STACK_REG model only
	f.derivePinnedGlobals() // reload value-pinned globals: the callee may have changed the shared cell

	if rN == 1 {
		rt := mtOf(ft.Results[0])
		if rt.isFloat() {
			f.pushFReg(0, rt) // V0
		} else {
			resReg := f.allocReg(maskOf(X0))
			f.a.MovReg64(resReg, X0)
			f.pushReg(resReg, rt)
		}
	}
	if mixedPair {
		for _, typ := range ft.Results {
			if isFloatValType(typ) {
				f.pushFReg(0, mtOf(typ))
			} else {
				f.pinned = f.pinned.remove(mixedIntReg)
				f.pushReg(mixedIntReg, mtOf(typ))
			}
		}
	} else if preparedDirectFloatSupported && rN == 2 && isFloatValType(ft.Results[0]) {
		f.pushFReg(0, mtOf(ft.Results[0]))
		f.pushFReg(1, mtOf(ft.Results[1]))
	} else if rN == 2 {
		// Two-int register return (X0/X1): a mixed sig has float params but may
		// still return two integers, e.g. (f64,i64,i64)->(i64,i64).
		var pairRes [2]Reg
		pairRes[0] = f.allocReg(maskOf(X0, X1))
		f.pinned = f.pinned.add(pairRes[0])
		f.a.MovReg64(pairRes[0], X0)
		pairRes[1] = f.allocReg(maskOf(X0, X1))
		f.a.MovReg64(pairRes[1], X1)
		f.pinned = f.pinned.add(pairRes[1])
		for i, reg := range pairRes {
			f.pinned = f.pinned.remove(reg)
			f.pushReg(reg, mtOf(ft.Results[i]))
		}
	}
	if sigHasMixedWideResults(ft) {
		gp, fp := 0, 0
		for _, typ := range ft.Results {
			if isFloatValType(typ) {
				f.pushFReg(Reg(fp), mtOf(typ))
				fp++
			} else {
				reg := mixedWideInts[gp]
				f.pinned = f.pinned.remove(reg)
				f.pushReg(reg, mtOf(typ))
				gp++
			}
		}
	} else if preparedDirectFloatSupported && rN > 2 {
		for i, typ := range ft.Results {
			f.pushFReg(Reg(i), mtOf(typ))
		}
	}
	return returnOffset
}

func (f *fn) descriptorEntryKind(home Reg, avoid regMask) Reg {
	kind := f.allocReg(avoid)
	f.a.LsrImm(kind, home, abi.FuncRefEntryTagShift, false)
	return kind
}

func (f *fn) stripDescriptorHomeTags(home Reg) {
	f.a.AndImm64(home, home, ^uint64(abi.FuncRefHomeTagMask))
}

func (f *fn) validateWrapperDescriptor(kind, home Reg) {
	// Valid wrapper tags are host=0, local=1, and cross=2. A retained local
	// wrapper may appear in another instance; home-aware dispatch decides whether
	// to switch contexts.
	f.cmpImm(kind, uint32(abi.FuncRefCrossInstanceTagValue), true)
	f.trapIf(condA, trapIndirectSig)
}

func (f *fn) checkCallType(entry Reg, offset int32, key uint64, typeIdx uint32, avoid regMask) {
	got := f.allocReg(avoid)
	f.ld64(got, entry, offset)
	want := f.allocReg(avoid.add(got))
	f.a.MovImm64(want, key)
	f.cmpRR(got, want, true)
	var matches []int
	if target, ok := f.m.TypeSubType(typeIdx); ok && !target.Final {
		subtypes, _ := f.m.FunctionSubtypeTypeIndexes(typeIdx)
		for _, subtype := range subtypes {
			candidate, valid := f.m.StructuralTypeKeyChecked(subtype)
			if !valid || candidate == key {
				continue
			}
			matches = append(matches, f.a.Bcond(condE))
			f.a.MovImm64(want, candidate)
			f.cmpRR(got, want, true)
		}
	}
	f.release(want)
	f.release(got)
	f.trapIf(condNE, trapIndirectSig)
	for _, match := range matches {
		f.patchBranch19(match, f.a.Len())
	}
}

func (f *fn) callRef(r *wasm.Reader) error {
	f.stats.call("ref")
	typeIdx, err := r.U32()
	if err != nil {
		return err
	}
	ft, ok := f.m.TypeFunc(typeIdx)
	if !ok {
		return fmt.Errorf("call_ref: bad type %d", typeIdx)
	}
	canon, ok := f.m.StructuralTypeKeyChecked(typeIdx)
	if !ok {
		return fmt.Errorf("call_ref: type %d exceeds bounded native identity", typeIdx)
	}

	f.materializePendingTraps()
	ref := f.materialize(f.popValue())
	rootOffsets, recordRoots := f.prepareGCFrameCallsite(len(ft.Params))
	f.pinned = f.pinned.add(ref)
	f.trapIfZero(ref, true, true, trapIndirectOOB)
	code := f.allocReg(0)
	f.ld64(code, ref, runtime.TableEntryCodePtrOffset)
	f.trapIfZero(code, true, true, trapIndirectOOB)
	f.checkCallType(ref, runtime.TableEntrySigKeyOffset, canon, typeIdx, maskOf(ref, code))
	home := f.allocReg(maskOf(ref, code))
	f.ld64(home, ref, runtime.TableEntryHomeLinMemOffset)
	targetContext := f.allocReg(maskOf(ref, code, home))
	f.ld64(targetContext, ref, runtime.FuncRefContextOffset)
	f.trapIfZero(targetContext, true, true, trapIndirectOOB)
	f.pinned = f.pinned.remove(ref)
	f.release(ref)

	if sigFitsRegABI(ft) && sigIsIntOnly(ft) || sigFitsReferenceResultRegABI(ft) {
		roots := f.rootsBottomToTop()
		types := make([]machineType, len(roots))
		var gcRoots []bool
		if f.tracksGCFrameRoots() {
			gcRoots = gcRootFlags(roots)
		}
		for i, root := range roots {
			types[i] = rootMachineType(root)
		}
		f.pinned = f.pinned.add(code).add(home).add(targetContext)
		f.flush()
		savedLocals := append([]localDef(nil), f.locals...)
		kind := f.descriptorEntryKind(home, maskOf(code, home, targetContext))
		f.cmpImm(kind, uint32(abi.FuncRefInternalTagValue), true)
		wrapper := f.a.Bcond(condNE)
		f.stripDescriptorHomeTags(home)
		f.pinned = f.pinned.remove(home)
		var returnOffset uint32
		if sigFitsReferenceResultRegABI(ft) {
			returnOffset = f.emitMixedRegisterCallVia(-1, code, ft)
		} else {
			returnOffset = f.emitRegisterCallVia(ft, -1, false, -1, code)
		}
		if recordRoots {
			f.gcFrameRoots.RecordCallsite(returnOffset, 0, rootOffsets)
		}
		f.pinned = f.pinned.remove(code)
		f.release(code)
		done := f.a.Branch()

		f.patchBranch19(wrapper, f.a.Len())
		f.locals = savedLocals
		f.setDepthTypesWithGCRoots(types, gcRoots)
		f.stripDescriptorHomeTags(home)
		f.validateWrapperDescriptor(kind, home)
		f.release(kind)
		f.st64(linMemReg, -int32(offSpillRegion), code)
		f.pinned = f.pinned.remove(code)
		f.release(code)
		f.emitIndirectCallHomeAware(ft, home, targetContext, rootOffsets, recordRoots)
		f.patchBranch26(done, f.a.Len())
		return nil
	}

	kind := f.descriptorEntryKind(home, maskOf(code, home, targetContext))
	f.stripDescriptorHomeTags(home)
	f.validateWrapperDescriptor(kind, home)
	f.release(kind)
	f.st64(linMemReg, -int32(offSpillRegion), code)
	f.release(code)
	f.emitIndirectCallHomeAware(ft, home, targetContext, rootOffsets, recordRoots)
	return nil
}

// callIndirect lowers call_indirect: bounds-check the table index, verify the
// entry's canonical type key, reject a null entry, then call the entry's code
// pointer via the wrapper ABI. Table layout matches the runtime (32-byte entries;
// +8 code ptr, +16 type key) with the descriptor pointer at [linMem-offTablePtr].
func (f *fn) callIndirect(r *wasm.Reader) error {
	f.stats.call(callKindIndirect)
	typeIdx, err := r.U32()
	if err != nil {
		return err
	}
	tableIdx, err := r.U32()
	if err != nil {
		return err
	}
	ft, ok := f.m.TypeFunc(typeIdx)
	if !ok {
		return fmt.Errorf("call_indirect: bad type %d", typeIdx)
	}
	canon, ok := f.m.StructuralTypeKeyChecked(typeIdx)
	if !ok {
		return fmt.Errorf("call_indirect: type %d exceeds bounded native identity", typeIdx)
	}

	f.materializePendingTraps()
	idxReg := f.materialize(f.popValue())
	rootOffsets, recordRoots := f.prepareGCFrameCallsite(len(ft.Params))
	relocBase := len(f.relocs)
	f.canonicalizeTableOperand(idxReg, tableIdx)
	f.pinned = f.pinned.add(idxReg)
	tbl := f.allocReg(0)
	f.loadTableDescriptor(tbl, tableIdx)
	f.pinned = f.pinned.add(tbl)

	ln := f.allocReg(0)
	f.ld32(ln, tbl, 0) // table length
	f.cmpRR(idxReg, ln, f.tableAddr64(tableIdx))
	f.release(ln)
	f.trapIf(condAE, trapIndirectOOB) // idx >= length → cold stub

	// 64-bit pointer arithmetic: entry address = tbl + idx*32 (TableEntryBytes).
	f.a.LslImm64(idxReg, idxReg, 5) // idx *= 32
	f.a.Add64(idxReg, idxReg, tbl)  // idx += tbl
	f.pinned = f.pinned.remove(tbl)
	f.release(tbl)

	// Entry fields (folding the 8-byte descriptor header): +8 code, +16 type key,
	// +24 home linMem. Check null (uninitialized element) BEFORE the signature so a
	// zero-initialized entry traps as an empty slot, not a type mismatch.
	code := f.allocReg(0)
	f.ld64(code, idxReg, 8)                         // entry code ptr (offset-0 entry)
	f.trapIfZero(code, true, true, trapIndirectOOB) // null entry

	if f.gcTypeSubtypingRefTest {
		f.pinned = f.pinned.add(code)
		identity := f.allocReg(maskOf(idxReg, code))
		f.ld64(identity, idxReg, 8+runtime.TableEntryRefSlotOffset)
		f.emitLocalFunctionSubtypeIdentityCheck(identity, typeIdx, false, false, trapIndirectSig)
		f.release(identity)
		f.pinned = f.pinned.remove(code)
	} else if tableIdx == 0 && f.immutableTableTyped && f.immutableTableType == canon {
		f.stats.peep("immutable-table-type-check-elide")
	} else {
		f.checkCallType(idxReg, 8+runtime.TableEntrySigKeyOffset, canon, typeIdx, maskOf(idxReg, code))
	}

	// With one private local immutable table and no function imports, every non-null
	// entry is necessarily a same-module internal entry. Avoid loading its home pointer,
	// testing the internal-entry tag, emitting the wrapper/cross-instance path, and
	// reconciling two compiler states. The ordinary OOB/null/type checks above are
	// still required and deliberately remain on this hot path.
	if tableIdx == 0 && f.opt(optRegABI) && f.immutableLocalTable && f.monomorphicTarget >= 0 && sigFitsRegABI(ft) && sigIsIntOnly(ft) {
		f.pinned = f.pinned.remove(idxReg)
		f.release(idxReg)
		f.pinned = f.pinned.remove(code)
		f.release(code)
		f.stats.peep("monomorphic-call-indirect")
		preservesPins := f.directCalleePreservesPins(f.monomorphicTarget)
		if recordRoots {
			preservesPins = false
		}
		f.emitRegisterCall(f.monomorphicTarget, ft, -1, preservesPins)
		if recordRoots {
			if len(f.relocs) != relocBase+1 {
				f.gcFrameRoots.Exact = false
			} else {
				f.gcFrameRoots.RecordCallsite(uint32(f.relocs[relocBase].at+4), 0, rootOffsets)
			}
		}
		return nil
	}
	home := f.allocReg(maskOf(idxReg, code))
	f.ld64(home, idxReg, 24) // entry home linMem base
	// The uniform private-table proof only accepts active function-index elements
	// and no table initializer. Without function imports, its non-null entries
	// therefore have valid local descriptors. Keep the entry cursor until the
	// wrapper arm needs that descriptor, while retaining the runtime ABI tag fork.
	localDescriptors := tableIdx == 0 && f.immutableLocalTable && f.immutableTableTyped && f.immutableTableType == canon && f.m.ImportedFuncCount() == 0
	targetContext := idxReg
	if !localDescriptors {
		targetContext = f.allocReg(maskOf(idxReg, code, home))
		f.ld64(targetContext, idxReg, 32) // canonical descriptor pointer
		f.trapIfZero(targetContext, true, true, trapIndirectOOB)
		f.pinned = f.pinned.remove(idxReg)
		f.release(idxReg)
	}
	if sigFitsRegABI(ft) && sigIsIntOnly(ft) || sigFitsReferenceResultRegABI(ft) {
		// Flush once, then emit both guarded paths from the same canonical stack
		// state. The compiler state for locals is restored before producing the
		// wrapper path; at run time only one branch executes.
		roots := f.rootsBottomToTop()
		types := make([]machineType, len(roots))
		gcRoots := gcRootFlags(roots)
		for i, root := range roots {
			types[i] = root.st.typ
			if root.elemKind() == ekDeferred && root.st.typ != mtNone {
				types[i] = root.st.typ
			}
		}
		f.pinned = f.pinned.add(code).add(home).add(targetContext)
		f.flush()
		savedLocals := append([]localDef(nil), f.locals...)
		kind := f.descriptorEntryKind(home, maskOf(code, home, targetContext))
		f.cmpImm(kind, uint32(abi.FuncRefInternalTagValue), true)
		wrapper := f.a.Bcond(condNE)
		// Internal entries inherit the active instance context. Resolve the
		// descriptor's context only in the wrapper arm, where it is needed.
		f.stats.peep("internal-call-indirect-context-elide")
		if localDescriptors {
			f.stats.peep("immutable-local-indirect-descriptor-elide")
		}
		f.stripDescriptorHomeTags(home)
		f.pinned = f.pinned.remove(home)
		var returnOffset uint32
		if sigFitsReferenceResultRegABI(ft) {
			returnOffset = f.emitMixedRegisterCallVia(-1, code, ft)
		} else {
			returnOffset = f.emitRegisterCallVia(ft, -1, false, -1, code)
		}
		if recordRoots {
			f.gcFrameRoots.RecordCallsite(returnOffset, 0, rootOffsets)
		}
		done := f.a.Branch()
		f.patchBranch19(wrapper, f.a.Len())
		f.locals = savedLocals
		f.setDepthTypesWithGCRoots(types, gcRoots)
		if localDescriptors {
			f.ld64(targetContext, targetContext, 32)
			f.trapIfZero(targetContext, true, true, trapIndirectOOB)
		}
		f.ld64(targetContext, targetContext, runtime.FuncRefContextOffset)
		f.trapIfZero(targetContext, true, true, trapIndirectOOB)
		f.st64(linMemReg, -int32(offSpillRegion), code)
		f.pinned = f.pinned.remove(code)
		f.release(code)
		f.stripDescriptorHomeTags(home)
		f.validateWrapperDescriptor(kind, home)
		f.release(kind)
		f.emitIndirectCallHomeAware(ft, home, targetContext, rootOffsets, recordRoots)
		f.patchBranch26(done, f.a.Len())
		return nil
	}

	// This signature always uses the wrapper entry and its descriptor context.
	if localDescriptors {
		f.ld64(targetContext, targetContext, 32)
		f.trapIfZero(targetContext, true, true, trapIndirectOOB)
	}
	f.ld64(targetContext, targetContext, runtime.FuncRefContextOffset)
	f.trapIfZero(targetContext, true, true, trapIndirectOOB)
	// Stash the code ptr in linMem scratch so it survives the call staging.
	kind := f.descriptorEntryKind(home, maskOf(code, home, targetContext))
	f.stripDescriptorHomeTags(home)
	f.validateWrapperDescriptor(kind, home)
	f.release(kind)
	f.st64(linMemReg, -int32(offSpillRegion), code)
	f.release(code)

	f.emitIndirectCallHomeAware(ft, home, targetContext, rootOffsets, recordRoots)
	return nil
}

// emitIndirectCallHomeAware makes the indirect call to the code ptr stashed at
// [linMem-offSpillRegion], running the funcref in its home instance's context.
// homeReg holds the entry's home linMem base and targetContextReg identifies its
// owning instance. Matching caller/target contexts take the plain frameless
// wrapper path, even when memory aliases are possible. Otherwise preserve the caller's
// whole-module-invariant registers (linMemReg, X23-X25, X27), copy the per-execution control
// words caller→callee, and enter the callee's offset-0 entry with X1 = its linMem
// (the same context-swap as emitCrossInstanceCall, selected at run time).
func (f *fn) emitIndirectCallHomeAware(ft *wasm.CompType, homeReg, targetContextReg Reg, rootOffsets []uint32, recordRoots bool) {
	p := len(ft.Params)
	roots := f.rootsBottomToTop()
	d := len(roots)
	types := f.tmpTypes[:0]
	slotOf := f.tmpStackSlots[:0]
	slotTop := 0
	for _, root := range roots {
		typ := root.st.typ
		if root.elemKind() == ekDeferred && root.st.typ != mtNone {
			typ = root.st.typ
		}
		types = append(types, typ)
		slotOf = append(slotOf, uint32(slotTop))
		slotTop += typ.stackSlots()
	}
	f.tmpTypes = types
	f.tmpStackSlots = slotOf
	belowTypes := f.tmpTypes2[:0]
	if cap(belowTypes) < d-p {
		belowTypes = make([]machineType, 0, d-p)
	}
	belowTypes = append(belowTypes, types[:d-p]...)
	f.tmpTypes2 = belowTypes
	belowGCRoots := f.gcFramePrefixRoots(roots, d-p)
	resultSlot := slotTop
	resultSlots := 0
	for _, rt := range ft.Results {
		resultSlots += mtOf(rt).stackSlots()
	}

	// Stash the home linear-memory and target-context pointers above the results.
	// The frame is stable during the frameless call, so both survive arg staging
	// and the cross-instance path's SP changes. Reserve the whole scratch range
	// through spillFloor while flushing: maxSpill sizes the frame, but curSpillSlot
	// deliberately does not treat that high-water mark as live storage. In
	// particular, flushWideStack stages above the current operand extent and would
	// otherwise overwrite these manually written slots.
	homeSlot := resultSlot + resultSlots
	targetContextSlot := homeSlot + 1
	scratchEnd := targetContextSlot + 1
	if scratchEnd > f.maxSpill {
		f.maxSpill = scratchEnd
	}
	f.st64(SP, f.spillOff(homeSlot), homeReg)
	f.st64(SP, f.spillOff(targetContextSlot), targetContextReg)
	f.release(homeReg)
	f.release(targetContextReg)

	oldSpillFloor := f.spillFloor
	if scratchEnd > f.spillFloor {
		f.spillFloor = scratchEnd
	}
	f.flush() // args → canonical slot-width slots
	f.spillFloor = oldSpillFloor
	f.storePinnedGlobals(false)      // value-pinned globals → cells
	f.storeModuleGlobals(X9)         // same-instance callee's offset-0 prologue reloads from cells
	argOff := f.spillOff(resultSlot) // p==0: unused, but a valid in-frame address
	if p > 0 {
		argOff = f.spillOff(int(slotOf[d-p]))
	}
	f.spillLocalsForCall()
	f.a.LeaSP(X0, argOff)                 // args = &first arg slot
	f.a.LeaSP(X3, f.spillOff(resultSlot)) // results = &slot top

	f.ld64(X11, SP, f.spillOff(homeSlot))          // target home linMem
	f.ld64(X12, SP, f.spillOff(targetContextSlot)) // target instance context
	f.ld64(X13, linMemReg, -int32(offFuncRefDescPtr))
	f.ld64(X13, X13, runtime.FuncRefContextOffset) // caller instance context
	f.cmpRR(X12, X13, true)
	jne := f.a.Bcond(condNE)
	// Same instance: establish the complete wrapper ABI and call directly.
	f.a.MovReg64(X1, linMemReg)
	f.ld64(X2, linMemReg, -int32(offTrapCellPtr))
	f.ld64(X16, linMemReg, -int32(offSpillRegion))
	if regallocCheckEnabled {
		f.checkCallClobber()
	}
	f.a.Blr(X16)
	if recordRoots {
		f.gcFrameRoots.RecordCallsite(uint32(f.a.Len()), 0, rootOffsets)
	}
	jdone := f.a.Branch()
	// Cross-instance: preserve the caller's invariants (+ one alignment pad), copy
	// the control words caller→callee, enter with X1 = callee linMem, then restore.
	f.patchBranch19(jne, f.a.Len()) // the false edge is a B.cond (imm19)
	f.a.StpPre(linMemReg, X24, SP, -16)
	f.a.StpPre(X25, X23, SP, -16)
	f.a.StpPre(X27, ehReg, SP, -16)
	f.a.StpPre(X13, X12, SP, -16)
	f.copyInstanceContext(X11, X12)
	f.ld64(X9, linMemReg, -int32(offTrapHandlerPtr))
	f.st64(X11, -int32(offTrapHandlerPtr), X9)
	f.ld64(X9, linMemReg, -int32(offTrapStackReentry))
	f.st64(X11, -int32(offTrapStackReentry), X9)
	f.ld64(X9, linMemReg, -int32(offStackFence))
	f.st64(X11, -int32(offStackFence), X9)
	f.ld64(X9, linMemReg, -int32(offTrapCellPtr))
	f.st64(X11, -int32(offTrapCellPtr), X9)
	f.a.MovReg64(X1, X11)
	f.ld64(X2, X11, -int32(offTrapCellPtr))
	f.ld64(X16, linMemReg, -int32(offSpillRegion)) // linMemReg unchanged by the pushes
	if regallocCheckEnabled {
		f.checkCallClobber()
	}
	f.a.Blr(X16)
	if recordRoots {
		// Four 16-byte records preserve caller invariants while the foreign
		// wrapper runs. Frame walking adds this adjustment to recover the
		// caller's stable post-prologue SP.
		f.gcFrameRoots.RecordCallsite(uint32(f.a.Len()), 64, rootOffsets)
	}
	f.a.LdpPost(X13, X12, SP, 16)
	f.a.LdpPost(X27, ehReg, SP, 16)
	f.a.LdpPost(X25, X23, SP, 16)
	f.a.LdpPost(linMemReg, X24, SP, 16)
	f.copyInstanceContext(linMemReg, X13)
	f.refreshCachedMemoryBoundAfterExternalCall()
	f.deriveModuleGlobals()           // cross-instance callee may have written shared global cells
	f.patchBranch26(jdone, f.a.Len()) // fr.jdone is an unconditional B (imm26)

	f.reloadLocalsForCall()
	f.derivePinnedGlobals()

	// Publish the wrapper results without imposing a physical-register arity limit.
	f.finishWrapperResultsWithRoots(belowTypes, belowGCRoots, resultSlot, ft.Results)
}

// emitWrapperCall sets up the wrapper ABI registers (X0=args, X3=results,
// X1=linMem, X2=trap), runs emitCall, and loads the results back onto the
// operand stack. Frameless: the wrapper argument and result buffers are the
// operand SPILL SLOTS themselves — after the flush, the p arguments already sit
// contiguously and in order at their canonical spill slots (exactly the wrapper
// ABI layout the callee's prologue reads), and the results land in free slots
// just above the current operand slot top. So there is no separate native-stack
// buffer and no transient SubSP/AddSP — SP stays put for the whole call.
func (f *fn) emitWrapperCall(ft *wasm.CompType, emitCall func()) {
	p := len(ft.Params)
	roots := f.rootsBottomToTop()
	d := len(roots)
	types := f.tmpTypes[:0]
	slotOf := f.tmpStackSlots[:0]
	slotTop := 0
	for _, root := range roots {
		typ := root.st.typ
		if root.elemKind() == ekDeferred && root.st.typ != mtNone {
			typ = root.st.typ
		}
		types = append(types, typ)
		slotOf = append(slotOf, uint32(slotTop))
		slotTop += typ.stackSlots()
	}
	f.tmpTypes = types
	f.tmpStackSlots = slotOf
	belowTypes := f.tmpTypes2[:0]
	if cap(belowTypes) < d-p {
		belowTypes = make([]machineType, 0, d-p)
	}
	belowTypes = append(belowTypes, types[:d-p]...)
	f.tmpTypes2 = belowTypes
	belowGCRoots := f.gcFramePrefixRoots(roots, d-p)
	resultSlot := slotTop
	resultSlots := 0
	for _, rt := range ft.Results {
		resultSlots += mtOf(rt).stackSlots()
	}

	f.flush()                   // all operands to canonical slots; args start at slotOf[d-p]
	f.storePinnedGlobals(false) // spill value-pinned globals to their cells before the call
	f.storeModuleGlobals(X9)    // wrapper callee's offset-0 prologue reloads from the cells

	// Reserve result slots above the full slot-width operand area, including v128 args.
	if need := resultSlot + resultSlots; need > f.maxSpill {
		f.maxSpill = need
	}
	argOff := f.spillOff(resultSlot) // p==0: unused, but a valid in-frame address
	if p > 0 {
		argOff = f.spillOff(int(slotOf[d-p]))
	}
	// Store dirty pinned locals BEFORE the call-setup writes below: a pinned
	// local may be clobbered by the setup itself. Lazy reload on the next read —
	// WARP's STACK_REG.
	f.spillLocalsForCall()
	f.a.LeaSP(X0, argOff)                 // args = &first arg slot
	f.a.LeaSP(X3, f.spillOff(resultSlot)) // results = &slot top
	f.a.MovReg64(X1, linMemReg)           // linMem (kept in linMemReg); trap ptr lives in basedata
	emitCall()

	// No post-call trap check: a callee trap unwinds the whole native call tree
	// in one jump (emitTrap's handler-jump back to enterNative), so control never
	// returns here with *trap set.
	f.reloadLocalsForCall() // non-STACK_REG model only
	f.derivePinnedGlobals() // reload value-pinned globals: the callee may have changed the shared cell

	// Publish the wrapper results without imposing a physical-register arity limit.
	f.finishWrapperResultsWithRoots(belowTypes, belowGCRoots, resultSlot, ft.Results)
}

// finishWrapperResults removes consumed arguments and publishes wrapper-ABI
// results on the operand stack. Common narrow signatures retain the established
// register-resident path. Very wide signatures stay in canonical slots so legal
// multi-value calls are not limited by the physical register file.
func (f *fn) finishWrapperResults(belowTypes []machineType, resultSlot int, results []wasm.ValType) {
	f.finishWrapperResultsWithRoots(belowTypes, nil, resultSlot, results)
}

func (f *fn) finishWrapperResultsWithRoots(belowTypes []machineType, belowGCRoots []bool, resultSlot int, results []wasm.ValType) {
	const maxRegisterResults = 12
	if len(results) > maxRegisterResults || !f.wrapperResultsFitRegisters(results) {
		f.adoptWideWrapperResults(belowTypes, belowGCRoots, resultSlot, results)
		return
	}

	f.setDepthTypesWithGCRoots(belowTypes, belowGCRoots)
	resultN := len(results)
	regs := f.tmpRegs[:0]
	if cap(regs) < resultN {
		regs = make([]Reg, 0, resultN)
	}
	regs = regs[:resultN]
	f.tmpRegs = regs
	types := f.tmpTypes[:0]
	if cap(types) < resultN {
		types = make([]machineType, 0, resultN)
	}
	types = types[:resultN]
	f.tmpTypes = types
	resultSlotCursor := resultSlot
	for i, result := range results {
		typ := mtOf(result)
		types[i] = typ
		switch {
		case typ.isV128():
			regs[i] = f.allocFReg(0)
			f.a.VMovdquLoadDisp(regs[i], SP, f.spillOff(resultSlotCursor))
			f.fpinned = f.fpinned.add(regs[i])
		case typ.isFloat():
			tmp := f.allocReg(0)
			f.ld64(tmp, SP, f.spillOff(resultSlotCursor))
			regs[i] = f.allocFReg(0)
			f.a.FmovFromGpr(regs[i], tmp, true)
			f.release(tmp)
			f.fpinned = f.fpinned.add(regs[i])
		default:
			regs[i] = f.allocReg(0)
			f.ld64(regs[i], SP, f.spillOff(resultSlotCursor))
			f.pinned = f.pinned.add(regs[i])
		}
		resultSlotCursor += typ.stackSlots()
	}
	for i, typ := range types {
		var value *elem
		switch {
		case typ.isV128():
			f.fpinned = f.fpinned.remove(regs[i])
			value = f.pushVReg(regs[i])
		case typ.isFloat():
			f.fpinned = f.fpinned.remove(regs[i])
			value = f.pushFReg(regs[i], typ)
		default:
			f.pinned = f.pinned.remove(regs[i])
			value = f.pushReg(regs[i], typ)
		}
		value.st.setGCRoot(f.tracksGCFrameRoots() && arm64GCFrameRefType(f.m, results[i]))
	}
}

// wrapperResultsFitRegisters mirrors the amd64 pressure gate. Wrapper results
// are pinned until all slot loads finish, while local/global reservations and FP
// constant registers remain unavailable after setDepthTypes. Scalar floats also
// need one temporary GPR for the slot-to-V-register move.
func (f *fn) wrapperResultsFitRegisters(results []wasm.ValType) bool {
	gpNeed, fpNeed := 0, 0
	needsFloatTmp := false
	for _, result := range results {
		typ := mtOf(result)
		switch {
		case typ.isV128():
			fpNeed++
		case typ.isFloat():
			fpNeed++
			needsFloatTmp = true
		default:
			gpNeed++
		}
	}
	if needsFloatTmp {
		gpNeed++
	}
	gpBlock := f.pinnedLocalMask.union(f.reserved)
	gpAvail := 0
	for _, r := range gpAlloc {
		if !gpBlock.has(r) {
			gpAvail++
		}
	}
	fpBlock := f.fpinnedLocalMask.union(f.fconstMask())
	fpAvail := 0
	for _, r := range fpAllocRegs {
		if !fpBlock.has(r) {
			fpAvail++
		}
	}
	return gpNeed <= gpAvail && fpNeed <= fpAvail
}

func (f *fn) adoptWideWrapperResults(belowTypes []machineType, belowGCRoots []bool, resultSlot int, results []wasm.ValType) {
	dstSlot := 0
	for _, typ := range belowTypes {
		dstSlot += typ.stackSlots()
	}
	resultSlots := funcTypeSlots(results)
	f.moveSlots(resultSlot, dstSlot, resultSlots)

	types := f.tmpTypes[:0]
	if need := len(belowTypes) + len(results); cap(types) < need {
		types = make([]machineType, 0, need)
	}
	types = append(types, belowTypes...)
	for _, result := range results {
		types = append(types, mtOf(result))
	}
	f.tmpTypes = types
	if !f.tracksGCFrameRoots() {
		f.setDepthTypes(types)
		return
	}
	gcRoots := f.tmpGCRoots[:0]
	gcRoots = append(gcRoots, belowGCRoots...)
	for _, result := range results {
		gcRoots = append(gcRoots, arm64GCFrameRefType(f.m, result))
	}
	f.tmpGCRoots = gcRoots
	f.setDepthTypesWithGCRoots(types, gcRoots)
}

// loadImportDispatchBase uses the function-local cache only for the import-only
// call graph whose entry establishes it.
func (f *fn) loadImportDispatchBase(dst Reg) {
	if f.cacheImportDispatch {
		f.a.MovReg64(dst, X25)
	} else {
		f.ld64(dst, linMemReg, -int32(offImportDispatchPtr))
	}
}

// nativeI32ImportAliases admits identical scalar imports or one scalar import in a shared-memory
// module, whose body must also pass nativeImportVariantEligible. A
// runtime native-leaf tag still guards entry to the specialized body.
func nativeI32ImportAliases(m *wasm.Module) bool {
	if len(m.Imports) < 2 && !(len(m.Imports) == 1 && len(m.Memories) == 1 && m.Memories[0].Shared) {
		return false
	}
	first := m.Imports[0]
	if first.Type.Kind != wasm.ExternFunc {
		return false
	}
	ft, ok := m.ImportFuncType(0)
	if !ok || len(ft.Params) < 1 || len(ft.Params) > 2 || len(ft.Results) != 1 || ft.Results[0] != wasm.I32 {
		return false
	}
	for _, param := range ft.Params {
		if param != wasm.I32 {
			return false
		}
	}
	for _, imp := range m.Imports[1:] {
		if imp.Module != first.Module || imp.Name != first.Name || imp.Type != first.Type {
			return false
		}
	}
	return true
}

// beginNativeImportVariant selects the unchecked body only while every alias
// names the same immutable, runtime-admitted scalar native leaf. Such a body
// cannot enter Go or mutate its bindings; the ordinary body remains complete.
func (f *fn) beginNativeImportVariant() {
	if f.sc == nil || f.sc.nativeImportFast || !f.cacheNativeImportTarget {
		return
	}
	f.ld64(X16, linMemReg, -int32(offImportDispatchPtr))
	f.ld64(X17, X16, runtime.ImportDispatchCallerContextOffset)
	f.a.AndImm64(X17, X17, runtime.ImportDispatchCallerNativeLeafTag)
	f.nativeImportRouter = f.a.Cbnz64(X17)
	f.patchBranch19(f.nativeImportRouter, f.nativeImportRouter)
}

func (f *fn) nativeImportVariantEligible(body []byte) bool {
	if len(f.m.Memories) != 0 {
		mt := f.m.Memories[0]
		if f.guardMode || len(f.m.Memories) != 1 || !mt.Shared || mt.Limits.Addr64 || !mt.Limits.HasMax || mt.Limits.Min != mt.Limits.Max {
			return false
		}
		if bounded, _ := shared.BoundedFixedSharedHostSegments(body, uint32(f.m.ImportedFuncCount()), 0); !bounded {
			return false
		}
	}
	if profileEnabled || len(body) > 384 || len(f.m.Tables) != 0 || len(f.m.Tags) != 0 || f.gcFrameRoots != nil && f.gcFrameRoots.Candidate || len(f.ft.Params) != 1 || f.ft.Params[0] != wasm.I32 || len(f.ft.Results) != 1 || f.ft.Results[0] != wasm.I32 || len(f.importBindings) != f.m.ImportedFuncCount() {
		return false
	}
	for i, binding := range f.importBindings {
		if !binding.Dynamic || binding.ImportIndex != uint32(i) {
			return false
		}
	}
	return nativeImportIntegerBody(f, body)
}

func nativeImportIntegerBody(f *fn, body []byte) bool {
	for _, typ := range f.localType {
		if typ != mtI32 && typ != mtI64 {
			return false
		}
	}
	r := wasm.ReaderFrom(body)
	for r.HasNext() {
		op, err := r.Byte()
		if err != nil {
			return false
		}
		var imm wasm.InstructionImmediate
		if wasm.ClassifyInstructionImmediateInto(&r, op, &imm) != nil {
			return false
		}
		switch {
		case op == 0 || op == 1 || op >= 2 && op <= 5 || op >= 0x0b && op <= 0x10 || op == 0x1a || op == 0x1b || op >= 0x20 && op <= 0x22:
		case op == 0x28 || op == 0x29 || op >= 0x2c && op <= 0x37 || op >= 0x3a && op <= 0x3e:
			if len(f.m.Memories) != 1 || !f.threadedMemory0 {
				return false
			}
		case op == 0x41 || op == 0x42 || op >= 0x45 && op <= 0x5a || op >= 0x67 && op <= 0x8a || op == 0xa7 || op == 0xac || op == 0xad || op >= 0xc0 && op <= 0xc4:
		default:
			return false
		}
	}
	return true
}

// Snapshot the choice once at function setup so all dynamic import alternatives
// agree on their local-state join. Go and foreign paths still home every pin.
func (f *fn) preserveNativeImportLocals(nativeCandidate bool) bool {
	return nativeCandidate && f.usesCalls && len(f.locals) <= len(localStateSnapshot{}) && (f.m.ImportedFuncCount() > 1 || f.sharedNativePins)
}

// Keep source trap/load order and reject overlapping noncanonical homes.
func nativeSharedArgPrefixSafe(roots []*elem) bool {
	const params = 1
	if params < 1 || params > 2 || len(roots) < params || len(roots) > len(intArgRegs) {
		return false
	}
	for i, root := range roots[:len(roots)-params] {
		plain := root.st.kind == stLocalReg || root.st.kind == stConst || root.st.kind == stSlot && root.st.slotIndex() == i
		if root.elemKind() != ekValue || !plain || root.st.typ != mtI32 && root.st.typ != mtI64 {
			return false
		}
	}
	for i, root := range roots[len(roots)-params:] {
		if root.elemKind() == ekValue && root.st.kind == stSlot && root.st.slotIndex() != len(roots)-params+i {
			return false
		}
	}
	return true
}
